INSERT INTO public.larpmanager_eventrole_members VALUES (1, 1, 2);

INSERT INTO public.larpmanager_feature VALUES (1, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Prologues', 'Enables "Prologues", short introductory paragraphs for each act of the event, which participants receive to guide them', 'prologue', 240, false, '', false, 1, 'orga_prologues', 'You can now create prologues for the event', false);
INSERT INTO public.larpmanager_feature VALUES (2, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Quests and Traits', 'Introduces ''Quests'' as building blocks of the character sheet, each with multiple ''traits''', 'questbuilder', 120, false, '', false, 1, 'orga_quest_types', 'You can now create quests for the event', false);
INSERT INTO public.larpmanager_feature VALUES (3, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Copy', 'Allows you to copy any element directly from another event', 'copy', 10, false, '', false, 3, 'orga_copy', 'You can now copy elements from another event.', false);
INSERT INTO public.larpmanager_feature VALUES (4, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Pay what you want', 'Allows participants to add an optional extra amount to their registration fee', 'pay_what_you_want', 50, false, '', false, 2, 'orga_registration_form', 'You can now configure the registration question', false);
INSERT INTO public.larpmanager_feature VALUES (5, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Discount', 'Allows you to generate discount codes that participants can use to reduce their ticket price', 'discount', 30, false, '', false, 2, 'orga_discounts', 'You can now create discounts for the event', false);
INSERT INTO public.larpmanager_feature VALUES (6, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'LAOG', 'Treats this event as a digital/online occurrence that does not require in-person registration', 'laog', 70, false, '', false, 3, '', '', false);
INSERT INTO public.larpmanager_feature VALUES (7, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Reminder', 'Performs daily checks for upcoming payments deadlines and sends reminder emails automatically', 'remind', 20, true, '', false, 4, 'config/remind', 'You can now set the reminder options', false);
INSERT INTO public.larpmanager_feature VALUES (8, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Bring a friend', 'Enables ''bring a friend'' discount. A participant can provides their unique code to a new registrant, granting both a discounted price', 'bring_friend', 9999, false, '', false, 2, 'config/bring_friend', 'You can now set the discount options', false);
INSERT INTO public.larpmanager_feature VALUES (9, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'PDF generation', 'Automatically generates and updates PDFs of character sheets, gallery and participant profiles', 'print_pdf', 25, false, '', false, 1, 'orga_characters_pdf', 'You can now set the PDF generation options', false);
INSERT INTO public.larpmanager_feature VALUES (10, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Workshop', 'Adds a quiz-style system for workshop questions. Organizers can define forms, questions, and correct answers for participants to complete', 'workshop', 20, false, '', false, 3, 'orga_workshop_modules', 'You can now start creating workshops, starting from modules', false);
INSERT INTO public.larpmanager_feature VALUES (11, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Speed Larp', 'Manages pre-larp ''mini-scenes.'' You can create any number of scenes and assign participants to them, with checks to avoid scheduling conflicts', 'speedlarp', 60, false, '', false, 3, 'orga_speedlarps', 'You can now start creating speed-larps', false);
INSERT INTO public.larpmanager_feature VALUES (12, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Safety', 'Lets staff access the safety information submitted by participants', 'safety', 20, false, '', false, 7, 'orga_safety', 'You can now review the safety information submitted by participants', true);
INSERT INTO public.larpmanager_feature VALUES (13, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Casting algorithm', 'Lets participants submit character preferences, then finds the optimal overall match', 'casting', 10, false, '', false, 6, 'config/casting', 'You can now set the casting options', false);
INSERT INTO public.larpmanager_feature VALUES (14, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Matchmaker', 'Lets organizers define custom questions on the characters participants would like to play, and assign them with a grid system', 'matchmaker', 91, false, '', false, 6, 'form/matchmaker/', 'You can now set the matchmaker form', false);
INSERT INTO public.larpmanager_feature VALUES (15, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Debrief', 'Lets organizers define custom questions for participants to fill in after the event, to collect their feedback', 'debrief', 92, false, '', false, 6, 'form/debrief/', 'You can now set the debrief form', false);
INSERT INTO public.larpmanager_feature VALUES (16, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Help', 'Allows participants to submit questions, and organizers to review and organize them', 'help', 10, true, '', false, 7, 'exe_questions', 'You can now review participants'' questions', false);
INSERT INTO public.larpmanager_feature VALUES (17, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Collections', 'Allows participants to create and contribute to collections aimed at assisting another participant with event fees', 'collection', 40, true, '', false, 2, 'exe_collections', 'Participants can now submit collections, and you can review them', false);
INSERT INTO public.larpmanager_feature VALUES (18, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Pre-registration', 'Enables free pre-registration to events', 'pre_register', 30, true, '', false, 4, 'exe_pre_registrations', 'Participants can now submit preregistrations, and you can review them', false);
INSERT INTO public.larpmanager_feature VALUES (19, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Donation', 'Adds a link on personal accounts pages, allowing users to donate money to the association freely', 'donate', 20, true, '', false, 2, 'exe_donations', 'Participants can now submit donations, and you can review them.', false);
INSERT INTO public.larpmanager_feature VALUES (20, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Newsletter', 'Adds a page displaying participant mailing lists, sorted by participants'' newsletter preferences', 'newsletter', 60, true, '', false, 7, 'exe_newsletter', 'You can now review mailing lists for newsletters.', false);
INSERT INTO public.larpmanager_feature VALUES (21, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Utility', 'Lets you upload and host files directly on the platform, making them available either to staff or to participants via secret external links', 'utils', 30, false, '', false, 3, 'orga_utils', 'You can now host files on the platform.', false);
INSERT INTO public.larpmanager_feature VALUES (22, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Character customization', 'Enables participants to customize specific attributes (name, pronoun, public info, etc.) of the characters they''re assigned', 'custom_character', 40, false, '', false, 6, 'config/custom_character', 'You can now set customization options', false);
INSERT INTO public.larpmanager_feature VALUES (23, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Membership', 'Requires Executive Committee approval of membership before participating in an event', 'membership', 40, true, '', false, 7, 'config/membership', 'You can now set membership options', false);
INSERT INTO public.larpmanager_feature VALUES (24, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Shuttle', 'Allows participants to submit shuttle requests (e.g., pickup logistics), and staff can manage the status of those requests', 'shuttle', 30, true, '', false, 3, '', '', false);
INSERT INTO public.larpmanager_feature VALUES (25, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'External mail server', 'Allows you to configure a custom external mail server that will be used instead of the standard one', 'custom_mail', 40, true, '', false, 3, 'config/custom_mail_server', 'You can now set the external mail server settings', false);
INSERT INTO public.larpmanager_feature VALUES (26, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Lottery', 'Enables ''lottery'' tickets with unlimited availability and no cost, from which a random subset is converted into normal tickets', 'lottery', 90, false, '', false, 4, 'orga_registration_tickets', 'You can now create the lottery ticket', false);
INSERT INTO public.larpmanager_feature VALUES (27, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Reserve', 'Enables ''Reserve'' characters: simpler character sheets, assigned to participants who are ready to replacing last-minute dropout of main characters.', 'filler', 70, false, '', false, 4, 'orga_registration_tickets', 'You can now create the ticket for reserves', false);
INSERT INTO public.larpmanager_feature VALUES (28, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Check-in', 'Generates a unique QR code per registration and lets staff scan it on-site to mark participants present, working offline with automatic sync', 'checkin', 300, false, '', false, 4, 'orga_checkin', 'You can now scan QR codes to check-in participants', false);
INSERT INTO public.larpmanager_feature VALUES (29, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Chat', 'Enables participants to send private messages to each other, without revealing personal email addresses', 'chat', 50, true, '', false, 7, '', '', false);
INSERT INTO public.larpmanager_feature VALUES (30, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Waiting list', 'Activates ''waiting list'' style tickets, available only when all main tickets are sold out', 'waiting', 60, false, '', false, 4, 'orga_registration_tickets', 'You can now create the waiting ticket', false);
INSERT INTO public.larpmanager_feature VALUES (31, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Problems', 'Enables a ticket-like system for issues during the event, where staff can log issues, assign severity/urgency, and track them', 'problems', 40, false, '', false, 3, 'orga_problems', 'You can now review the event''s problems', false);
INSERT INTO public.larpmanager_feature VALUES (32, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Dynamic rates', 'Enables dynamic installment management: the total fee is evenly split into multiple installments, each due on a date determined by dividing the remaining days until the event.', 'reg_quotas', 20, false, '', false, 2, 'orga_registration_quotas', 'You can now set the dynamic installments', false);
INSERT INTO public.larpmanager_feature VALUES (33, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Vote', 'Lets participants cast votes for the election of the organisation''s Executive Committee', 'vote', 90, true, '', false, 7, 'config/vote', 'You can now set the vote options', false);
INSERT INTO public.larpmanager_feature VALUES (34, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Badge', 'Allows the organisation to award badges and enables a public leaderboard', 'badge', 80, true, '', false, 7, 'exe_badges', 'You can now create badges', false);
INSERT INTO public.larpmanager_feature VALUES (35, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Warehouse', 'Enables warehouse management for the organization.', 'warehouse', 5, true, '', false, 3, 'exe_warehouse_containers', 'You can now add warehouse containers and items', false);
INSERT INTO public.larpmanager_feature VALUES (36, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Secret link', 'Generates a special, hidden link that lets certain participants register even if general registration is closed (e.g., early access for a specific group)', 'registration_secret', 20, false, '', false, 4, 'orga_run', 'You can now set the registration secret link', false);
INSERT INTO public.larpmanager_feature VALUES (37, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Fixed instalments', 'Enables fixed installment deadlines for registration fees, allowing you to define multiple due dates and amounts', 'reg_installments', 10, false, '', false, 2, 'orga_registration_installments', 'You can now create fixed installments', false);
INSERT INTO public.larpmanager_feature VALUES (38, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Relationships', 'Allows authors to add relationships to characters', 'relationships', 200, false, '', false, 1, 'orga_characters', 'You can now add relationships when editing a character', false);
INSERT INTO public.larpmanager_feature VALUES (39, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Sections', 'Lets you define sections in the registration form, grouping questions to make lengthy forms clearer', 'reg_que_sections', 40, false, '', false, 4, 'orga_registration_sections', 'You can now define registration form sections', false);
INSERT INTO public.larpmanager_feature VALUES (40, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Campaign', 'Enables a ''campaign'' style setup where multiple events share the same set of characters and factions', 'campaign', 30, true, '', false, 10, '', '', false);
INSERT INTO public.larpmanager_feature VALUES (41, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Patron and Reduced', 'Adds ''Patron'' and ''Reduced'' ticket types. Each Patron ticket purchased makes one Reduced ticket available', 'reduced', 80, false, '', false, 4, 'orga_registration_tickets', 'You can now create the ''patron'' and ''reduced'' tickets', false);
INSERT INTO public.larpmanager_feature VALUES (42, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Accounting tracking', 'Keeps a daily record of the organisation''s and events'' financial status, displaying trend graphs over time', 'record_acc', 140, true, '', false, 2, 'exe_accounting_rec', 'You can now review historical accounting information.', false);
INSERT INTO public.larpmanager_feature VALUES (43, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Progress', 'Adds a ''progress'' status field (e.g. draft, ready, approved) to key writing elements', 'progress', 110, false, '', false, 1, 'orga_progress_steps', 'You can now create the progress steps', false);
INSERT INTO public.larpmanager_feature VALUES (44, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Diet', 'Lets staff access the diet information submitted by participants', 'diet', 30, false, '', false, 7, 'orga_diet', 'You can now review the diet information submitted by participants', true);
INSERT INTO public.larpmanager_feature VALUES (45, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Deadlines', 'Activates a page summarizing overdue participants and their deadlines (payments, memberships, forms, casting, etc.)', 'deadlines', 10, true, '', false, 4, 'exe_deadlines', 'You can now review the organization''s deadlines', false);
INSERT INTO public.larpmanager_feature VALUES (46, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Plots', 'Enables Plots, story arcs involving selected characters, adding extra content to their character sheets', 'plot', 130, false, '', false, 1, 'orga_plots', 'You can now create the plots of the event', false);
INSERT INTO public.larpmanager_feature VALUES (47, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Factions', 'Enables ''Factions'' to organize characters into groups, either visible, transversal or secret', 'faction', 120, false, '', false, 1, 'orga_factions', 'You can now create the factions of the event', false);
INSERT INTO public.larpmanager_feature VALUES (48, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Handout', 'Enables ''Handouts,'' pre-written texts that provide information about a plot or lore', 'handout', 140, false, '', false, 1, 'orga_handouts', 'You can now create the handouts of the event', false);
INSERT INTO public.larpmanager_feature VALUES (49, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Expenses', 'Lets staff upload receipts for event expenses, tracking both the event expenses, and the amount to refund the staff', 'expense', 30, true, '', false, 2, 'exe_expenses', 'Crew can now upload expenses, and you can review them', false);
INSERT INTO public.larpmanager_feature VALUES (50, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Tokens', 'Allows managing Tokens, which participants can use instead of money for registration fees', 'tokens', 50, true, '', false, 2, 'config/tokens', 'You can now set up the tokens configuration', false);
INSERT INTO public.larpmanager_feature VALUES (51, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Credits', 'Allows managing Credits, which participants can use instead of money for registration fees. Credits can also be redeemed for cash', 'credits', 55, true, '', false, 2, 'config/credits', 'You can now set up the credits configuration', false);
INSERT INTO public.larpmanager_feature VALUES (52, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Outflows', 'Enables management of expenses paid using the organization''s financial instruments', 'outflow', 90, true, '', false, 2, 'exe_outflows', 'You can now create outflows', false);
INSERT INTO public.larpmanager_feature VALUES (53, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Verification payments', 'Allows you to upload financial system statements (e.g., bank statements) to match and approve corresponding wire payments', 'verification', 130, true, '', false, 2, 'exe_verification', 'You can now verify wire payments', false);
INSERT INTO public.larpmanager_feature VALUES (54, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Annual fiscal report', 'Generates an annual summary of fiscal activity for the Italian budget report', 'ita_balance', 10, true, '', false, 9, 'exe_balance', 'You can now review the annual balance sheet.', false);
INSERT INTO public.larpmanager_feature VALUES (55, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Payments', 'Enables payment processing, specifying which payment methods to accept', 'payment', 10, true, '', false, 2, 'exe_methods', 'You can now configure the payment methods.', false);
INSERT INTO public.larpmanager_feature VALUES (56, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Refunds', 'Enables participants to request a refund (a money transfer from the organization)', 'refund', 60, true, '', false, 2, 'exe_refunds', 'Participants can now create refund requests, and you can review them', false);
INSERT INTO public.larpmanager_feature VALUES (57, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Legal Notice', 'Adds a link to legal notices on every page, and provides a management panel link to edit the content of that notice', 'legal_notice', 10, true, '', false, 5, 'exe_texts', 'You can now set the legal notice text', false);
INSERT INTO public.larpmanager_feature VALUES (58, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Experience points', 'Adds support for assigning XP (experience points) to characters, which can then be used to purchase abilities', 'experience', 50, false, '', false, 6, 'config/experience', 'You can now configure experience point settings.', false);
INSERT INTO public.larpmanager_feature VALUES (59, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Character creation', 'Allows participants to create and modify their own characters freely', 'user_character', 30, false, '', false, 6, 'config/user_character', 'You can now configure character creation by players.', false);
INSERT INTO public.larpmanager_feature VALUES (60, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Player relationships', 'Enables participants to write their own list of character relationships', 'player_relationships', 31, false, '', false, 6, '', '', false);
INSERT INTO public.larpmanager_feature VALUES (61, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Character inventory', 'Allows characters to have inventories', 'inventory', 31, false, '', false, 6, '', '', false);
INSERT INTO public.larpmanager_feature VALUES (62, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Organizational fee', 'Allows you to set a ''tax'' percentage on event income that must be set aside for the organisation', 'organization_tax', 110, true, '', false, 2, 'config/organization_tax', 'You can now set the options for the Organizational fee', false);
INSERT INTO public.larpmanager_feature VALUES (63, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Easter egg', 'Occasionally shows a special page to users, based on a defined probability, and optionally assigns a result', 'centauri', 9999, true, '', false, 9, 'config/centauri', 'You can now configure the special page options.', false);
INSERT INTO public.larpmanager_feature VALUES (64, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'URL shortener', 'Adds a page where you can define shorter URLs for long links', 'urlshortner', 10, true, '', false, 3, 'exe_urlshortner', 'You can now create URL shorteners.', false);
INSERT INTO public.larpmanager_feature VALUES (65, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Surcharge', 'Enables the definition of surcharges that are added to every registration made after a specified date', 'reg_surcharges', 40, false, '', false, 2, 'orga_registration_surcharges', 'You can now create registration surcharges', false);
INSERT INTO public.larpmanager_feature VALUES (66, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Inflows', 'Enables managing of entry of revenue for an event that do not originate from participant registrations', 'inflow', 80, true, '', false, 2, 'exe_inflows', 'You can now create inflows', false);
INSERT INTO public.larpmanager_feature VALUES (67, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Carousel', 'Introduces a new way to display past and upcoming events, inspired by popular streaming-service layouts', 'carousel', 20, true, '', false, 5, '', '', false);
INSERT INTO public.larpmanager_feature VALUES (68, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Treasurer', 'Lets you specify a set of users who receive payment confirmation emails for all events, instead of each event''s organizers', 'treasurer', 120, true, '', false, 2, '', '', false);
INSERT INTO public.larpmanager_feature VALUES (69, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Receipt', 'Automatically generates a PDF fiscal receipt for each payment, in accordance with Italian legislation', 'receipts', 9999, true, '', false, 9, 'config/receipts', 'You can now set up the receipts data', false);
INSERT INTO public.larpmanager_feature VALUES (70, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Register of volunteers', 'Enables a volunteer register, as required by Italian RUNTS regulations', 'volunteer_registry', 20, true, '', false, 9, 'exe_volunteer_registry', 'You can now review the volunteer registry.', false);
INSERT INTO public.larpmanager_feature VALUES (71, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Taxes', 'Shows the calculated tax amount on each payment', 'vat', 100, true, '', false, 2, 'config/vat', 'You can now set the taxes options', false);
INSERT INTO public.larpmanager_feature VALUES (72, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Delegated accounts', 'Allows a user to create ''delegated'' accounts they fully manage (e.g., children), avoiding the need for separate login credentials', 'delegated_members', 70, true, '', false, 7, '', '', false);
INSERT INTO public.larpmanager_feature VALUES (73, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Gift', 'Allows participants to purchase tickets as gifts. A special code is generated and provided to the gift recipient for registration', 'gift', 60, false, '', false, 2, 'orga_registration_tickets', 'You can now select which tickets can be gifted', false);
INSERT INTO public.larpmanager_feature VALUES (74, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Additional tickets', 'Allows a user to reserve extra tickets in addition to their own', 'additional_tickets', 50, false, '', false, 4, 'orga_registration_form', 'You can now configure the registration question', false);
INSERT INTO public.larpmanager_feature VALUES (75, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Characters', 'Enables the creation, editing, and assignment of characters to registered participants', 'character', 1, false, '', false, 1, 'orga_characters', 'You can now create characters', false);
INSERT INTO public.larpmanager_feature VALUES (76, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Template', 'Lets you create ''template'' events whose configurations and settings can be used as a starting point for other events', 'template', 11, true, '', false, 10, 'exe_templates', 'You can now create event templates', false);
INSERT INTO public.larpmanager_feature VALUES (77, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Fiscal code check', 'Check the validity of the fiscal code', 'fiscal_code_check', 30, true, '', false, 9, 'exe_membership_check', 'You can now perform the fiscal code validity check.', false);
