INSERT INTO public.larpmanager_feature VALUES (107, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'New player', 'Enables ''New player'' tickets, reserved for users that never participated in an event of the organization', 'new_player', 75, false, '', false, 4, 'orga_registration_tickets', 'You can now create the "new player" ticket', false);
INSERT INTO public.larpmanager_feature VALUES (108, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Promotion', 'Makes upcoming events visible to external sites through a public API', 'publisher', 80, true, '', false, 10, 'config/publication', 'You can now set the promotion configurations', false);
INSERT INTO public.larpmanager_feature VALUES (109, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'One-Time Content', 'Enables secure streaming of video/audio content via one-time access tokens. Each token can only be used once and tracks who accessed the content, when, and from where', 'onetime_content', 50, false, '', false, 3, 'orga_onetimes', 'You can now upload content and generate access tokens', false);
INSERT INTO public.larpmanager_feature VALUES (110, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Translations', 'Allows to fine-tune how words and phrases are translated in the organization''s space', 'translation', 30, true, '', false, 5, 'exe_translations', 'You can now define custom organization translations', false);
INSERT INTO public.larpmanager_feature VALUES (111, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Experience Rules', 'Pseudo-feature activated by exp_rules configuration', 'exp_rules', 0, false, '', true, 3, '', '', true);
INSERT INTO public.larpmanager_feature VALUES (112, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Experience Modifiers', 'Pseudo-feature activated by exp_modifiers configuration', 'exp_modifiers', 0, false, '', true, 3, '', '', true);
INSERT INTO public.larpmanager_feature VALUES (113, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Experience Criteria', 'Pseudo-feature activated by exp_criterions configuration', 'exp_criterions', 0, false, '', true, 3, '', '', true);
INSERT INTO public.larpmanager_feature VALUES (114, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Experience Templates', 'Pseudo-feature activated by exp_templates configuration', 'exp_templates', 0, false, '', true, 3, '', '', true);
INSERT INTO public.larpmanager_feature VALUES (115, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Experience Systems', 'Pseudo-feature activated by exp_systems configuration', 'exp_systems', 0, false, '', true, 3, '', '', true);
INSERT INTO public.larpmanager_feature VALUES (116, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Activity Log', 'Show detailed activity log on entities created, updated or deleted.', 'logs', 1, true, '', false, 3, '', '', false);
INSERT INTO public.larpmanager_feature VALUES (117, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'App Integration', 'Enables a button in the topbar to redirect authenticated users to an external application, using a configurable URL and optional JWT-based SSO', 'app_integration', 90, true, '', false, 3, 'config/app_integration', 'Now you can configure the integration button and the external application settings', false);
INSERT INTO public.larpmanager_feature VALUES (118, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Activation', '', 'exe_activation', 9999, true, '', true, NULL, '', NULL, false);
INSERT INTO public.larpmanager_feature VALUES (119, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Milestones', 'Track event milestones', 'milestones', 250, false, '', false, 3, 'orga_milestones', 'You can now create milestones for the event', false);
INSERT INTO public.larpmanager_feature VALUES (120, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Ensemble', 'Provides a character learning page with multiple display modes (book, cards, compact list) to help players memorise other characters before the event', 'ensemble', 5, false, '', false, 3, 'config/ensemble', 'You can now configure the ensemble page', false);
INSERT INTO public.larpmanager_feature VALUES (121, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Trash', 'Pseudo-feature activated by allow_bulk_delete configuration to restore deleted items', 'exe_trash', 0, true, '', true, 2, '', '', true);
INSERT INTO public.larpmanager_feature VALUES (122, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'User Status Flags', 'Pseudo-feature activated by member_flags_active configuration', 'member_status_flags', 0, true, '', true, 7, '', '', true);
INSERT INTO public.larpmanager_feature VALUES (123, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Version Upgrade', 'Internal pseudo-feature for the platform version upgrade page', 'exe_version_upgrade', 0, true, '', true, NULL, '', '', true);
INSERT INTO public.larpmanager_feature VALUES (124, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Guilds', 'Enables ''Guilds'', player-created groups of characters with a self-managed admin, invite and text', 'guild', 125, false, '', false, 1, 'orga_guilds', 'Players can now create guilds for the event', false);
INSERT INTO public.larpmanager_feature VALUES (125, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Experience Calls', 'Pseudo-feature activated by exp_calls configuration', 'exp_calls', 0, false, '', true, 3, '', '', true);
