INSERT INTO public.larpmanager_larpmanagerguide VALUES (1, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 1, 'Your first event', 'How to create your organization, complete the activation checklist and open your first event to participants', 'first', '<p>LarpManager takes you from an empty account to a live event in nine steps: create your organization, set up your first event, follow the activation checklist, and unlock the full platform.</p>
<hr>
<h4>Step 1 &ndash; Create Your Organization</h4>
<p>On larpmanager.com, click Get started and skip the demo. Enter the name of your organization: the preview shows the address of your pages. Choose your payment currency and submit. You land on the dashboard of your new organization.</p>
<h4>Step 2 &ndash; Create Your First Event</h4>
<p>Click Create your first event, then enter its name and dates. Your first event opens its registrations automatically, and you can change their status at any time from the <a href="/guide/manage/">event dashboard</a>.</p>
<p>The pills in the top bar move between your two workspaces: the organization pill manages what all your events share, and the event pill manages that single event.</p>
<h4>Step 3 &ndash; Follow the Activation Checklist</h4>
<p>New organizations start in Lite Mode, with only the essentials. Open <a href="https://larpmanager.com/redirect/manage/activation/" target="_blank" rel="noopener"><strong>Organization &gt; Activation</strong></a> from the dashboard to see the checklist: each completed step brings you closer to all the features of the platform. Start with the <a href="/tutorials/payments/">payment methods</a>, choosing how participants will pay and entering the details of each method.</p>
<h4>Step 4 &ndash; Set Your Ticket Price</h4>
<p>Every event starts with a Standard ticket. Open <a href="https://larpmanager.com/redirect/event/manage/tickets/" target="_blank" rel="noopener"><strong>Event &gt; Tickets</strong></a> and set its price, or add other tickets.</p>
<h4>Step 5 &ndash; Set Up the Registration Form</h4>
<p>Open <a href="https://larpmanager.com/redirect/event/manage/form/" target="_blank" rel="noopener"><strong>Event &gt; Form</strong></a> to add the questions participants answer when they register, such as dietary restrictions. Each question can be text, or a choice among options with their own price.</p>
<h4>Step 6 &ndash; Reach Your Event Page</h4>
<p>The switch in the top bar moves between Admin, where you manage, and User, what participants see. Click User to see the site as participants do. The home page of your organization lists the upcoming events: click one to open its event page, the page to share with your participants.</p>
<h4>Step 7 &ndash; Register for Your Event</h4>
<p>Complete a registration yourself to try the whole flow. Choose a ticket, answer the questions and confirm. A registration stays provisional until its ticket is paid.</p>
<h4>Step 8 &ndash; Add a Character and Assign It</h4>
<p>Switch back to Admin. Open <a href="https://larpmanager.com/redirect/event/manage/characters/" target="_blank" rel="noopener"><strong>Event &gt; Characters</strong></a> to create a character, then open <a href="https://larpmanager.com/redirect/event/manage/registrations/" target="_blank" rel="noopener"><strong>Event &gt; Registrations</strong></a>, edit your registration and assign the character to it.</p>
<h4>Step 9 &ndash; Unlock All Features</h4>
<p>With every step of the checklist done, click Activate advanced mode. Features, configuration, e-mails and appearance all become available, and you can activate only the <a href="/tutorials/manage-events/#event-features">features</a> you need, for the whole organization or for a single event.</p>
<p>If you need help at any time, use the help button in the top bar.</p>
<hr>
<p><strong>Related resources</strong></p>
<ul>
<li>Find your way around the <strong>organization</strong> and its management pages (<a href="/tutorials/create-organization/">read here</a>)</li>
<li>Configure <strong>events</strong>, their status and what participants see (<a href="/tutorials/manage-events/">read here</a>)</li>
<li>Manage <strong>registrations</strong> and assign characters to participants (<a href="/tutorials/registrations/">read here</a>)</li>
<li>Create and edit <strong>characters</strong> (<a href="/tutorials/characters/">read here</a>)</li>
<li>Set up <strong>tickets and the registration form</strong> in detail (<a href="/guide/tickets/">read here</a>)</li>
<li>Control <strong>visibility and registrations</strong>, add sessions and set up your organization (<a href="/guide/manage/">read here</a>)</li>
<li>Collect <strong>payments</strong> and keep your accounting up to date (<a href="/guide/payments/">read here</a>)</li>
<li>Write <strong>characters, factions and plots</strong> (<a href="/guide/writing/">read here</a>)</li>
<li>Give your public pages <strong>your own look</strong> (<a href="/guide/appearance/">read here</a>)</li>
</ul>
', '', true, 'first event, organization, activation checklist, getting started, setup', 'flag-checkered', 'Getting started', 'pFaLVSFe-cI');
INSERT INTO public.larpmanager_larpmanagerguide VALUES (2, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 2, 'Managing your event', 'How to control event visibility and registrations, change them from the dashboard, add new sessions and set up organization features and configuration', 'manage', '<p>Once your event exists, a few settings decide everything participants see. LarpManager lets you control its <strong>visibility</strong> and its <strong>registrations</strong>, add new <strong>sessions</strong>, and set up what your whole organization shares.</p>
<hr>
<h4>Step 1 &ndash; Choose Who Sees Your Event</h4>
<p>Open <a href="https://larpmanager.com/redirect/event/manage/event/" target="_blank" rel="noopener"><strong>Event &gt; Event</strong></a> and click Show other options next to <a href="/tutorials/manage-events/#event-settings">Status</a>. Hidden keeps the event in preparation, open only to staff and already registered participants. Visible publishes it on the homepage and calendar. Cancelled hides it from users and excludes it from accounting. Concluded archives it among past events and freezes registrations.</p>
<h4>Step 2 &ndash; Publish It from the Dashboard</h4>
<p>Home opens your public calendar, where a Hidden event does not appear. Back on the event dashboard, the pencil next to Status, Registrations and Dates changes each value without opening the full form. Choose Visible to publish the event.</p>
<h4>Step 3 &ndash; Choose When People Register</h4>
<p>Registrations have their own status, on the dashboard and in <a href="https://larpmanager.com/redirect/event/manage/event/" target="_blank" rel="noopener"><strong>Event &gt; Event</strong></a>. Closed stops signups, and Open accepts them right away. <a href="/tutorials/registrations/#pre-registration">Pre-registration</a> collects interest before you open, once its feature is active. External site sends new participants to your link. Open on date and Close on date switch by themselves at the date you set.</p>
<h4>Step 4 &ndash; Add a New Session</h4>
<p>A session repeats the event on new dates. In <a href="https://larpmanager.com/redirect/manage/events/" target="_blank" rel="noopener"><strong>Organization &gt; Events</strong></a>, click New session, pick the event and set the dates. It shares tickets, form and features with the event, while dates, registrations and accounting are its own. See <a href="/tutorials/manage-events/#event-sessions">Event sessions</a>.</p>
<h4>Step 5 &ndash; Set Up Your Organization</h4>
<p>Features add tools for your whole organization: activate <a href="/tutorials/promotion/">Promotion</a> to publish your events on external sites, and its settings open next, to choose what is shared. <a href="https://larpmanager.com/redirect/manage/config/interface/" target="_blank" rel="noopener"><strong>Organization &gt; Configuration &gt; Interface</strong></a> chooses what the calendar shows for each event: with Website active, <a href="https://larpmanager.com/redirect/event/manage/event/" target="_blank" rel="noopener"><strong>Event &gt; Event</strong></a> gains the External website field, and every session links it on the calendar. <a href="https://larpmanager.com/redirect/manage/appearance/" target="_blank" rel="noopener"><strong>Organization &gt; Appearance</strong></a> and <a href="https://larpmanager.com/redirect/manage/texts/" target="_blank" rel="noopener"><strong>Organization &gt; Texts</strong></a> shape your public pages.</p>
<hr>
<p><strong>Related resources</strong></p>
<ul>
<li>Explore all the <strong>event settings</strong>, sessions and templates (<a href="/tutorials/manage-events/">read here</a>)</li>
<li>Export your events to <strong>LarpDatabase and LarpRadar</strong> (<a href="/tutorials/promotion/">read here</a>)</li>
<li>Customize the <strong>appearance</strong> of your organization (<a href="/tutorials/organization-appearance/">read here</a>)</li>
<li>Manage <strong>registrations</strong> and pre-registrations (<a href="/tutorials/registrations/">read here</a>)</li>
<li>Create your organization and <strong>your first event</strong> (<a href="/guide/first/">read here</a>)</li>
<li>Set <strong>tickets and the registration form</strong>, with prices and availability (<a href="/guide/tickets/">read here</a>)</li>
<li>Collect <strong>payments</strong> and keep your accounting up to date (<a href="/guide/payments/">read here</a>)</li>
<li>Link multiple events in a <strong>campaign</strong> to share characters across them (<a href="/guide/campaign/">read here</a>)</li>
<li>Give your public pages <strong>your own look</strong> (<a href="/guide/appearance/">read here</a>)</li>
<li>Keep an <strong>inventory of your props</strong> and load them for each event (<a href="/guide/inventory/">read here</a>)</li>
</ul>
', '', true, 'manage event, visibility, registrations, sessions, dashboard, configuration', 'sliders', 'Getting started', 'uPSfBRU2F0Y');
INSERT INTO public.larpmanager_larpmanagerguide VALUES (3, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 3, 'Staff and roles', 'How to create a staff role with its permissions, invite a collaborator by email, and give organization wide access', 'roles', '<p>Most teams share the work of an event. LarpManager lets you create <strong>roles</strong>, each with only the permissions a job needs, and <strong>invite</strong> collaborators by email, for a single event or for your whole organization.</p>
<hr>
<h4>Step 1 &ndash; Open the Event Roles</h4>
<p>Open <a href="https://larpmanager.com/redirect/event/manage/roles/" target="_blank" rel="noopener"><strong>Event &gt; Roles</strong></a>. The Organizer role is created automatically, is assigned to whoever created the event, and has every permission.</p>
<h4>Step 2 &ndash; Create a Role and Pick Its Permissions</h4>
<p>Click New, name the role after the job it covers, and check only the pages its members need, such as Registrations, Tickets and Form. More permissions appear as you activate new features. A member of several roles gets the permissions of all of them.</p>
<h4>Step 3 &ndash; Invite a Collaborator by Email</h4>
<p>Members can only be picked once they have shared their data with your organization. For anyone else, click the envelope icon on the role row and enter their email address. The invite is listed as pending under the role until it is accepted.</p>
<h4>Step 4 &ndash; The Collaborator Accepts</h4>
<p>The collaborator opens the link in the email and logs in, or creates an account, with that same email address. They agree to share their profile with your organization and accept the invitation. From then on they see only the management pages of their role. An invitation works once, only for the address it was sent to, and expires after a few days.</p>
<h4>Step 5 &ndash; Give Organization Wide Access</h4>
<p>For work that spans every event, such as accounting, open <a href="https://larpmanager.com/redirect/manage/roles/" target="_blank" rel="noopener"><strong>Organization &gt; Roles</strong></a> and create a role the same way. Anyone who already shares their data can be added directly in <a href="https://larpmanager.com/redirect/manage/membership/" target="_blank" rel="noopener"><strong>Organization &gt; Members</strong></a>, without a new invite.</p>
<hr>
<p><strong>Related resources</strong></p>
<ul>
<li>Set up <strong>event roles</strong> and their permissions (<a href="/tutorials/event-roles/">read here</a>)</li>
<li>Set up <strong>organization roles</strong> for your whole team (<a href="/tutorials/organization-roles/">read here</a>)</li>
<li>Explore all the <strong>event settings</strong> (<a href="/tutorials/manage-events/">read here</a>)</li>
<li>Create your organization and <strong>your first event</strong> (<a href="/guide/first/">read here</a>)</li>
<li>Collect <strong>payments</strong> and keep your accounting up to date (<a href="/guide/payments/">read here</a>)</li>
</ul>
', '', true, 'roles, staff, permissions, invite, collaborator', 'user-shield', 'Getting started', 'gs-MLZdwlig');
INSERT INTO public.larpmanager_larpmanagerguide VALUES (4, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 4, 'Your event''s look', 'How to add your logo, pick a theme, set your own background and colors, give each event its cover and title font, and add custom texts and navigation buttons', 'appearance', '<p>Your public pages are the first thing participants see. LarpManager lets you add your <strong>logo</strong>, choose a <strong>theme</strong> or your own <strong>colors and background</strong>, give each event its own <strong>cover and title font</strong>, and add your own <strong>texts</strong> and <strong>navigation buttons</strong>.</p>
<hr>
<h4>Step 1 &ndash; Add Your Logo</h4>
<p>Open <a href="https://larpmanager.com/redirect/manage/organization/" target="_blank" rel="noopener"><strong>Organization &gt; Organization</strong></a> and upload your logo in the Logo field, then confirm. It marks your organization in the top bar and in the browser tab. Square images work best.</p>
<h4>Step 2 &ndash; Pick a Theme</h4>
<p>Open <a href="https://larpmanager.com/redirect/manage/appearance/" target="_blank" rel="noopener"><strong>Organization &gt; Appearance</strong></a>, which styles every page of your organization. The page previews each theme as you choose it: Aurora is fully light, Eclipse fully dark, and Nebula, the default, mixes dark and light.</p>
<h4>Step 3 &ndash; Make It Yours with Halo</h4>
<p>Choose Halo to unlock your own background image and colors. Pick a calm background with little detail, then set the text, highlight and link colors, checking that they contrast well. Advanced users can also add their own CSS.</p>
<h4>Step 4 &ndash; Give the Event Its Own Look</h4>
<p>Open <a href="https://larpmanager.com/redirect/event/manage/appearance/" target="_blank" rel="noopener"><strong>Event &gt; Appearance</strong></a>. Upload a cover, shown on the calendar and on the event page, and a title font file (TTF, OTF or WOFF) for the page titles. Event settings override the organization ones, so each event can have its own theme, background and colors.</p>
<h4>Step 5 &ndash; Write Your Own Texts</h4>
<p><a href="https://larpmanager.com/redirect/event/manage/texts/" target="_blank" rel="noopener"><strong>Event &gt; Texts</strong></a> adds your words to pages and emails. Click New, write the text, and choose its type, which sets where it appears: a Registration form text is shown on the registration page, before the form. Add one version per language.</p>
<h4>Step 6 &ndash; Add a Navigation Button</h4>
<p><a href="https://larpmanager.com/redirect/event/manage/buttons/" target="_blank" rel="noopener"><strong>Event &gt; Navigation</strong></a> adds your own links for participants. Click New and enter a name, a tooltip shown on hover, the link (starting with https://) and an icon.</p>
<h4>Step 7 &ndash; See Your Public Pages</h4>
<p>Home shows the event card with its cover. The event page has the cover, the colors and the title font, and your button joins its sidebar. Your text welcomes people as they register.</p>
<hr>
<p><strong>Related resources</strong></p>
<ul>
<li>Customize the <strong>appearance of your organization</strong> (<a href="/tutorials/organization-appearance/">read here</a>)</li>
<li>Customize the <strong>appearance of each event</strong> (<a href="/tutorials/event-appearance/">read here</a>)</li>
<li>Create your organization and <strong>your first event</strong> (<a href="/guide/first/">read here</a>)</li>
<li>Control <strong>visibility and registrations</strong> of your event (<a href="/guide/manage/">read here</a>)</li>
</ul>
', '', true, 'appearance, theme, logo, colors, background, custom texts', 'palette', 'Getting started', 'iYGVMqXyV2k');
INSERT INTO public.larpmanager_larpmanagerguide VALUES (5, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 5, 'Tickets and registration form', 'How to set ticket prices and availability, add hidden staff tickets with a direct link, limit participants and build the registration form', 'tickets', '<p>Before opening registrations, decide what participants can buy and what you need to know about them. LarpManager lets you set <strong>tickets</strong> with their price and availability, limit the event, and build a <strong>registration form</strong> with your own questions.</p>
<hr>
<h4>Step 1 &ndash; Set Price and Availability</h4>
<p>Every event starts with a Standard ticket. Open <a href="https://larpmanager.com/redirect/event/manage/tickets/" target="_blank" rel="noopener"><strong>Event &gt; Tickets</strong></a> and edit it: add a description of what it includes, its price and how many are for sale in Total availability.</p>
<h4>Step 2 &ndash; Unlock the Staff Tier</h4>
<p>Tiers beyond Standard come from the event configuration. Open <a href="https://larpmanager.com/redirect/event/manage/config/tickets/" target="_blank" rel="noopener"><strong>Event &gt; Configuration &gt; Tickets</strong></a> and enable Staff.</p>
<h4>Step 3 &ndash; Add a Hidden Staff Ticket</h4>
<p>In <a href="https://larpmanager.com/redirect/event/manage/tickets/" target="_blank" rel="noopener"><strong>Event &gt; Tickets</strong></a>, click New and pick the Staff tier. Leave the price at zero and untick Visible: participants will not see this ticket in the form. Each ticket has its own direct link in the list, to share with the people who should use it.</p>
<h4>Step 4 &ndash; Cap the Whole Event</h4>
<p>Open <a href="https://larpmanager.com/redirect/event/manage/event/" target="_blank" rel="noopener"><strong>Event &gt; Event</strong></a> and set Maximum participants, the limit for the whole event. It does not include Staff tickets.</p>
<h4>Step 5 &ndash; Add Custom Questions</h4>
<p>Open <a href="https://larpmanager.com/redirect/event/manage/form/" target="_blank" rel="noopener"><strong>Event &gt; Form</strong></a> and click New. A text question collects free answers, and its status can make it mandatory. A choice question has <a href="/tutorials/registration-form/#manage-options">options</a>, each with an optional price and a maximum number of selections. Drag a question by its handle to change its position.</p>
<h4>Step 6 &ndash; See the Form as a Player</h4>
<p>Participants register from the event page. The form offers only the visible tickets, with their price and the spots left, followed by your questions. The summary adds up the ticket and the selected options before the final confirmation.</p>
<h4>Step 7 &ndash; Use the Direct Link</h4>
<p>The Signup link of a hidden ticket opens the form with that ticket selected. A free ticket is confirmed at once. Every signup lands in <a href="https://larpmanager.com/redirect/event/manage/registrations/" target="_blank" rel="noopener"><strong>Event &gt; Registrations</strong></a>, listed with its ticket.</p>
<hr>
<p><strong>Related resources</strong></p>
<ul>
<li>Configure more <strong>ticket tiers</strong>, such as patron, reduced, reserve, waiting list, lottery and new player (<a href="/tutorials/manage-ticket/">read here</a>)</li>
<li>Explore all <strong>question types</strong>, sections and form configurations (<a href="/tutorials/registration-form/">read here</a>)</li>
<li>Manage <strong>registrations</strong> and their status (<a href="/tutorials/registrations/">read here</a>)</li>
<li>Enable <strong>installments, discounts and deadlines</strong> (<a href="/tutorials/registration-accounting/">read here</a>)</li>
<li>Create your organization and <strong>your first event</strong> (<a href="/guide/first/">read here</a>)</li>
<li>Control <strong>visibility and registrations</strong>, and open them on a date (<a href="/guide/manage/">read here</a>)</li>
<li>Collect <strong>payments</strong> for tickets and paid options (<a href="/guide/payments/">read here</a>)</li>
<li>Share a <strong>secret link</strong>, create <strong>discount codes</strong> and run a waiting list (<a href="/guide/advanced-registration/">read here</a>)</li>
<li>Require <strong>approval</strong> before players can register (<a href="/guide/approval/">read here</a>)</li>
</ul>
', '', true, 'tickets, prices, availability, registration form, questions, staff ticket', 'ticket', 'Registrations', 'HFOjfQ1BdCg');
INSERT INTO public.larpmanager_larpmanagerguide VALUES (6, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 6, 'Secret links, discounts and waiting list', 'How to share a secret registration link, create discount codes, run a waiting list and keep freed spots for the people already waiting', 'advanced-registration', '<p>Once the basics are in place, a few options give you more control over who signs up and when. You can open a <strong>private signup</strong> through a secret link, reward people with <strong>discount codes</strong>, and handle a sold out event with a <strong>waiting list</strong> that keeps freed spots for the people already in line.</p>
<hr>
<h4>Step 1 &ndash; Turn On the Advanced Options</h4>
<p>Each option is a feature of the event. Open <a href="https://larpmanager.com/redirect/event/manage/features/" target="_blank" rel="noopener"><strong>Event &gt; Features</strong></a> and enable <a href="/tutorials/registrations/#secret-registration-link">Secret link</a>, <a href="/tutorials/registration-accounting/#discount">Discount</a> and <a href="/tutorials/manage-ticket/#waiting-list">Waiting list</a>, then confirm.</p>
<h4>Step 2 &ndash; Open a Private Signup</h4>
<p>Open <a href="https://larpmanager.com/redirect/event/manage/event/" target="_blank" rel="noopener"><strong>Event &gt; Event</strong></a> and keep the registration status Closed, so the public cannot sign up. The Secret registration code is already filled in; you can replace it with your own, using only English letters and digits. After saving, the dashboard shows the Secret registration link with a button to copy it: share it with the people you want to invite.</p>
<h4>Step 3 &ndash; Create a Discount Code</h4>
<p>Open <a href="https://larpmanager.com/redirect/event/manage/discounts/" target="_blank" rel="noopener"><strong>Event &gt; Discounts</strong></a> and click New. Give it an internal name, the amount to take off the registration fee, the maximum number of uses and the code players will type. Choose the Standard type and tick Visible, so participants can use it.</p>
<h4>Step 4 &ndash; Sign Up with the Link</h4>
<p>The secret link opens the registration form even while registrations are closed. Players enter the code in the Discounts section of the form: it is reserved for them for 15 minutes, and the summary shows the total with the discount already taken off. You can also share a link that applies the code by itself, by adding <code>discount/CODE/</code> to the secret link, for example <code>/event/register/secret/discount/CODE/</code>.</p>
<h4>Step 5 &ndash; Set Up the Waiting List</h4>
<p>The Waiting list feature adds its own Waiting ticket in <a href="https://larpmanager.com/redirect/event/manage/tickets/" target="_blank" rel="noopener"><strong>Event &gt; Tickets</strong></a>, which you can edit like any other. It is offered only once the event is full. In <a href="https://larpmanager.com/redirect/event/manage/event/" target="_blank" rel="noopener"><strong>Event &gt; Event</strong></a>, set Maximum participants and Maximum waiting list (0 means unlimited), then open registrations to everyone.</p>
<h4>Step 6 &ndash; Join the Waiting List</h4>
<p>When every spot is taken, the event page says the event is sold out and invites players to join the waiting list. The registration form then offers only the Waiting ticket. Discount codes are not available on the waiting list.</p>
<h4>Step 7 &ndash; Keep Freed Spots for the Waiting List</h4>
<p>If a participant cancels, the freed spot would go to whoever signs up first, ahead of the people already waiting. To prevent it, once the event is full set Maximum participants to 1: since at least one participant is registered, the regular tickets stay closed, and new players can only join the waiting list, even after a cancellation.</p>
<h4>Step 8 &ndash; Move Up from the Waiting List</h4>
<p>You decide who takes a freed spot. In <a href="https://larpmanager.com/redirect/event/manage/registrations/" target="_blank" rel="noopener"><strong>Event &gt; Registrations</strong></a>, waiting list signups are listed in their own group: edit the registration and switch its ticket to a regular one. The participant moves to the main list.</p>
<hr>
<p><strong>Related resources</strong></p>
<ul>
<li>Set up the <strong>secret link</strong>, pre-registrations and cancellations (<a href="/tutorials/registrations/">read here</a>)</li>
<li>Configure <strong>discounts</strong>, installments and other registration fees (<a href="/tutorials/registration-accounting/">read here</a>)</li>
<li>Explore all <strong>ticket tiers</strong>, such as reserve, lottery and new player (<a href="/tutorials/manage-ticket/">read here</a>)</li>
<li>Set <strong>tickets and the registration form</strong> (<a href="/guide/tickets/">read here</a>)</li>
<li>Control <strong>visibility and registrations</strong>, and open them on a date (<a href="/guide/manage/">read here</a>)</li>
<li>Collect <strong>payments</strong> for discounted registrations (<a href="/guide/payments/">read here</a>)</li>
</ul>
', '', true, 'secret link, discount code, waiting list, sold out, private signup', 'user-clock', 'Registrations', 'zznZOyPT0-4');
INSERT INTO public.larpmanager_larpmanagerguide VALUES (7, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 7, 'Signup approval, matchmaker and debrief', 'How to approve signup requests before players can register, then collect matchmaker preferences and debrief feedback', 'approval', '<p>Some events need to choose their players before letting them in. With the <strong>approval process</strong>, players send a signup request with their answers to your questions, and only those you approve can complete the registration. The <strong>matchmaker</strong> then asks participants what they would like to play, and the <strong>debrief</strong> collects their feedback after the event.</p>
<hr>
<h4>Step 1 &ndash; Require Approval to Sign Up</h4>
<p>Open <a href="https://larpmanager.com/redirect/event/manage/config/registrations/" target="_blank" rel="noopener"><strong>Event &gt; Configuration &gt; Registrations</strong></a> and enable Approval process. Players can no longer sign up directly: the registration page sends them a signup request instead. A new <a href="https://larpmanager.com/redirect/event/manage/registrations/requests/" target="_blank" rel="noopener"><strong>Event &gt; Requests</strong></a> page appears in the sidebar.</p>
<h4>Step 2 &ndash; Ask Questions with the Request</h4>
<p>Open <a href="https://larpmanager.com/redirect/event/manage/form/" target="_blank" rel="noopener"><strong>Event &gt; Form</strong></a>: it now has a Request form next to the Registration one. Add the questions you need to choose your players, such as their motivation or their larp experience. These questions are asked only with the request, never in the registration form.</p>
<h4>Step 3 &ndash; Add Matchmaker and Debrief Questions</h4>
<p>Open <a href="https://larpmanager.com/redirect/event/manage/features/" target="_blank" rel="noopener"><strong>Event &gt; Features</strong></a> and enable <a href="/tutorials/matchmaker/">Matchmaker</a> and <a href="/tutorials/debrief/">Debrief</a>. <a href="https://larpmanager.com/redirect/event/manage/form/" target="_blank" rel="noopener"><strong>Event &gt; Form</strong></a> gets a tab for each of them. The Matchmaker form already contains a Faction preference question, where participants rank the <a href="/tutorials/factions/">factions</a> of the event; add your own questions next to it. On the Debrief form, add the questions participants answer after the event.</p>
<h4>Step 4 &ndash; Send a Signup Request</h4>
<p>Players click Register as usual, and find the request form: they answer your questions and confirm. The event page then shows that the request is awaiting organizer approval, and you are notified of the new request.</p>
<h4>Step 5 &ndash; Approve the Request</h4>
<p>The event dashboard counts the signup requests to approve. Open <a href="https://larpmanager.com/redirect/event/manage/registrations/requests/" target="_blank" rel="noopener"><strong>Event &gt; Requests</strong></a> to see everyone waiting, side by side with their answers, and Approve or Reject each player. Approved players receive an email.</p>
<h4>Step 6 &ndash; Complete the Registration</h4>
<p>Once approved, the player opens the registration form, picks a ticket and continues, like any other <a href="/tutorials/registrations/">registration</a>.</p>
<h4>Step 7 &ndash; Answer the Matchmaker</h4>
<p>Registered participants find Matchmaker in the event menu. They order the factions with the arrows, from the favourite down, answer your questions and save. They can come back and change their answers.</p>
<h4>Step 8 &ndash; Fill the Debrief</h4>
<p>Debrief is in the same menu. After the event, participants use it to share their feedback, and save their answers.</p>
<h4>Step 9 &ndash; Review the Answers</h4>
<p><a href="https://larpmanager.com/redirect/event/manage/matchmaker/" target="_blank" rel="noopener"><strong>Event &gt; Matchmaker answers</strong></a> lists every participant with their answers, and shows the average rank of each faction, to help you assign characters. <a href="https://larpmanager.com/redirect/event/manage/debrief/" target="_blank" rel="noopener"><strong>Event &gt; Debrief answers</strong></a> collects all the feedback on the event.</p>
<hr>
<p><strong>Related resources</strong></p>
<ul>
<li>Manage <strong>registrations</strong>, cancellations and pre-registrations (<a href="/tutorials/registrations/">read here</a>)</li>
<li>Build the <strong>registration form</strong> and its question types (<a href="/tutorials/registration-form/">read here</a>)</li>
<li>Set up the <strong>matchmaker</strong> (<a href="/tutorials/matchmaker/">read here</a>)</li>
<li>Collect feedback with the <strong>debrief</strong> (<a href="/tutorials/debrief/">read here</a>)</li>
<li>Create the <strong>factions</strong> players rank (<a href="/tutorials/factions/">read here</a>)</li>
<li>Assign characters with <strong>casting</strong> (<a href="/guide/assign/">read here</a>)</li>
<li>Set <strong>tickets and the registration form</strong> (<a href="/guide/tickets/">read here</a>)</li>
</ul>
', '', true, 'approval, signup request, matchmaker, debrief, feedback, faction preference', 'user-check', 'Registrations', 'aRwfsvPZo9c');
INSERT INTO public.larpmanager_larpmanagerguide VALUES (8, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 8, 'Payments', 'How to manage player dues, configure payment methods and keep the event accounting up to date', 'payments', '<p>LarpManager makes it simple to collect payments from participants, track how much each player owes, process payments securely, and keep your accounting records accurate and up to date.</p>
<hr>
<h4>Step 1 &ndash; Enable Payments</h4>
<p>Activate the <a href="/tutorials/payments/">Payments</a> feature for the organization. This unlocks ticket prices, fees and accounting tracking.</p>
<h4>Step 2 &ndash; Configure Payment Methods</h4>
<p>Choose which payment gateways will be available to players, and enter the details of each one. Follow the <a href="/tutorials/payments/">setup tutorials</a> to retrieve the credentials required by each gateway.</p>
<h4>Step 3 &ndash; Create the Event and Set Ticket Prices</h4>
<p>Create your event, then open <a href="https://larpmanager.com/redirect/event/manage/tickets/" target="_blank" rel="noopener"><strong>Event &gt; Tickets</strong></a> and set the price of each ticket.</p>
<h4>Step 4 &ndash; Add Paid Registration Options</h4>
<p>Open <a href="https://larpmanager.com/redirect/event/manage/form/" target="_blank" rel="noopener"><strong>Event &gt; Form</strong></a> to add <a href="/tutorials/registration-form/#manage-options">registration options</a>. Assign a price to any option that should affect the total amount due.</p>
<h4>Step 5 &ndash; Player Registration</h4>
<p>Players register through the event page. The total is calculated automatically, including the ticket and the selected options.</p>
<h4>Step 6 &ndash; Process Payment</h4>
<p>After registration, players choose one of the configured gateways. With a bank transfer, they notify the organizer once it is done, and you confirm it from <a href="https://larpmanager.com/redirect/event/manage/payments/" target="_blank" rel="noopener"><strong>Event &gt; Payments</strong></a> after receiving it.</p>
<h4>Step 7 &ndash; Accurate, Real-Time Accounting</h4>
<p>Open <a href="https://larpmanager.com/redirect/event/manage/accounting/" target="_blank" rel="noopener"><strong>Event &gt; Accounting</strong></a> for an always up-to-date overview of the finances of your event, including revenue and balances.</p>
<hr>
<p><strong>Related resources</strong></p>
<ul>
<li>Set up <strong>payment methods</strong> across many payment gateways (<a href="/tutorials/payments/">read here</a>)</li>
<li>Enable advanced features of registration accounting, such as <strong>installments, discounts or deadlines</strong> (<a href="/tutorials/registration-accounting/">read here</a>)</li>
<li>Activate precise <strong>account tracking</strong> with expenses, inflows and outflows (<a href="/tutorials/accounting/">read here</a>)</li>
<li>Set <strong>tickets and the registration form</strong>, with prices and availability (<a href="/guide/tickets/">read here</a>)</li>
<li>Create your organization and <strong>your first event</strong> (<a href="/guide/first/">read here</a>)</li>
<li>Conclude an event to add its balance to the <strong>organization accounting</strong> (<a href="/guide/manage/">read here</a>)</li>
<li>Split the fee into <strong>instalments</strong> and send automatic reminders (<a href="/guide/payment-plans/">read here</a>)</li>
<li>Track <strong>expenses, inflows and outflows</strong> and read the event balance (<a href="/guide/accounting/">read here</a>)</li>
<li>Collect the annual <strong>membership</strong> fee (<a href="/guide/membership/">read here</a>)</li>
</ul>
', '', true, 'payments, payment methods, dues, fees, registration accounting', 'coins', 'Accounting', 'CGvtcY3Jato');
INSERT INTO public.larpmanager_larpmanagerguide VALUES (9, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 9, 'Payment plans and deadlines', 'How to split the registration fee into instalments, add late surcharges, track overdue payments and send automatic reminders', 'payment-plans', '<p>Most paid events need more than a single payment. With LarpManager you can split the fee into instalments, make late registrations cost more, see at a glance who is behind on their payments, and let automatic emails remind them.</p>
<hr>
<h4>Step 1 &ndash; Turn On Fixed Instalments</h4>
<p>In <a href="https://larpmanager.com/redirect/event/manage/features/" target="_blank" rel="noopener"><strong>Event &gt; Features</strong></a>, activate <strong>Fixed instalments</strong> to give everyone the same payment schedule. As an alternative, <strong>Dynamic rates</strong> let players choose how many rates to pay, spread until the event: when both are active, fixed instalments take precedence.</p>
<h4>Step 2 &ndash; Split the Fee Into Instalments</h4>
<p>Add one instalment for each deadline. Set the amount to be paid by then, a deadline in days from registration or a fixed date, and the tickets it applies to. An amount of 0 asks for whatever is still outstanding, which is handy for the last instalment.</p>
<h4>Step 3 &ndash; Charge Late Registrations More</h4>
<p>Activate the <strong>Surcharge</strong> feature and add a surcharge with its starting date. Every registration made after that date pays the extra amount, which rewards those who sign up early.</p>
<h4>Step 4 &ndash; The Player Signs Up</h4>
<p>The registration form adds the surcharge to the ticket price. Once registered, players see only the instalment currently due, with its amount and deadline, on the event page.</p>
<h4>Step 5 &ndash; Track Deadlines and Send Reminders</h4>
<p>In <a href="https://larpmanager.com/redirect/manage/features/" target="_blank" rel="noopener"><strong>Organization &gt; Features</strong></a>, activate <strong>Deadlines</strong> and <strong>Reminder</strong>. In <a href="https://larpmanager.com/redirect/manage/config/deadlines/" target="_blank" rel="noopener"><strong>Organization &gt; Configuration &gt; Deadline</strong></a>, set the tolerance (the days of delay before a registration is marked for cancellation) and how often organizers receive a summary of missed deadlines; in <a href="https://larpmanager.com/redirect/manage/config/remind/" target="_blank" rel="noopener"><strong>Organization &gt; Configuration &gt; Reminder</strong></a>, set how often players receive their reminders.</p>
<h4>Step 6 &ndash; Review the Deadlines Dashboard</h4>
<p>Open <a href="https://larpmanager.com/redirect/manage/deadlines/" target="_blank" rel="noopener"><strong>Organization &gt; Deadlines</strong></a> to see who is late on every upcoming event, grouped by problem, with names and emails. Players past the tolerance are listed for cancellation: LarpManager never cancels a registration by itself, so you decide what to do.</p>
<h4>Step 7 &ndash; Players Are Reminded Automatically</h4>
<p>Every few days, each player late on a payment receives an email with the amount due and a link to pay. Every message sent is listed in <a href="https://larpmanager.com/redirect/manage/mail/archive/" target="_blank" rel="noopener"><strong>Organization &gt; Archive</strong></a>.</p>
<hr>
<p><strong>Related resources</strong></p>
<ul>
<li>Configure <strong>fixed instalments, dynamic rates</strong> and other registration accounting options (<a href="/tutorials/registration-accounting/">read here</a>)</li>
<li>Learn every check of the <strong>deadlines dashboard</strong> and of the reminders (<a href="/tutorials/deadlines/">read here</a>)</li>
<li>Set up <strong>payment methods</strong> across many payment gateways (<a href="/tutorials/payments/">read here</a>)</li>
<li>Collect and confirm the <strong>payments</strong> of your players (<a href="/guide/payments/">read here</a>)</li>
<li>Set <strong>tickets and the registration form</strong>, with prices and availability (<a href="/guide/tickets/">read here</a>)</li>
</ul>
', '', true, 'instalments, installments, quotas, surcharge, deadlines, reminders, overdue', 'calendar-check', 'Accounting', '1BQgwgk4lxw');
INSERT INTO public.larpmanager_larpmanagerguide VALUES (19, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 19, 'Inventory', 'How to track props and their quantities in numbered boxes on your shelves, assign them to event areas and load them from the manifest', 'inventory', '<p>Props, costumes and set dressing live in boxes on shelves between events. LarpManager keeps an <strong>inventory</strong> of every box, where it sits and what it holds, then turns the props each event needs into a <strong>manifest</strong> your crew can load from and check on site.</p>
<hr>
<h4>Step 1 &ndash; Turn On the Warehouse</h4>
<p>In <a href="https://larpmanager.com/redirect/manage/features/" target="_blank" rel="noopener"><strong>Organization &gt; Features</strong></a>, check Warehouse and confirm. The warehouse belongs to the organization, so every event shares the same boxes and items. Then open <a href="https://larpmanager.com/redirect/manage/config/warehouse/" target="_blank" rel="noopener"><strong>Organization &gt; Configuration &gt; Warehouse</strong></a> and check Quantity to count how many of each prop you own.</p>
<h4>Step 2 &ndash; Number Your Boxes</h4>
<p>Each container is a physical box. Click New, give it the number written on the box, such as Box 12, and in Position note where it sits: the shelf and the height, such as Shelf A, height 3. Add a short description of its content, then repeat for every box on your shelves.</p>
<h4>Step 3 &ndash; Add Items with a Photo</h4>
<p>Open <a href="https://larpmanager.com/redirect/manage/warehouse/items/" target="_blank" rel="noopener"><strong>Organization &gt; Items</strong></a> and click New. Name the prop, set in Quantity how many you own in total, choose the box it is stored in, add tags to group similar props, such as Lighting, and upload a photo so whoever packs or unpacks the box knows what to look for.</p>
<h4>Step 4 &ndash; Create the Event Areas</h4>
<p>Switch to your event and open <a href="https://larpmanager.com/redirect/event/manage/warehouse/area/" target="_blank" rel="noopener"><strong>Event &gt; Area</strong></a>. Areas are the places of the event where props are set up, such as the Tavern or the Camp. Give each one a name and a position on site.</p>
<h4>Step 5 &ndash; Assign the Props to Each Area</h4>
<p>Click Item assignments on an area, then type in Quantity how many of each prop it needs. Available shows what is left once the other areas of the event have taken their share, so you never assign more than you own. Add a note for the crew, such as how to set them up. Changes are saved as you type.</p>
<h4>Step 6 &ndash; Load the Boxes from the Manifest</h4>
<p><a href="https://larpmanager.com/redirect/event/manage/warehouse/manifest/" target="_blank" rel="noopener"><strong>Event &gt; Manifest</strong></a> lists every prop of the event with its area, how many to bring, its box and the shelf the box sits on. Sort it by container to walk the shelves box by box, and mark each prop as Loaded when it goes on the van.</p>
<h4>Step 7 &ndash; Check What Is Set Up on Site</h4>
<p>On site, mark each prop as Deployed once it is in its area. With both columns ticked, nothing gets left behind in the warehouse or on site.</p>
<hr>
<p><strong>Related resources</strong></p>
<ul>
<li>Explore all the <strong>organization tools</strong>, warehouse included (<a href="/tutorials/organization-tools/">read here</a>)</li>
<li>Give your crew access with <strong>organization roles</strong> (<a href="/tutorials/organization-roles/">read here</a>)</li>
<li>Control <strong>visibility and registrations</strong> of your event (<a href="/guide/manage/">read here</a>)</li>
<li>Give your staff the <strong>roles and permissions</strong> they need (<a href="/guide/roles/">read here</a>)</li>
</ul>
', '', true, 'inventory, warehouse, props, boxes, quantities, manifest', 'boxes-stacked', 'Organization', 'vuP01x3PVJQ');
INSERT INTO public.larpmanager_larpmanagerguide VALUES (10, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 10, 'Event accounting', 'How to track staff expenses, outflows and inflows, read the final balance of your event, and refund staff credits', 'accounting', '<p>Beyond registration fees, every event has its own costs and extra income. LarpManager collects staff expenses, payments made by the organization and other income in one place, and computes the final balance of each event.</p>
<hr>
<h4>Step 1 &ndash; Enable the Accounting Tools</h4>
<p>In <a href="https://larpmanager.com/redirect/manage/features/" target="_blank" rel="noopener"><strong>Organization &gt; Features</strong></a>, activate <a href="/tutorials/accounting/">Expenses, Inflows, Outflows and Refunds</a>. Expenses also activates Credits, used to pay back the staff.</p>
<h4>Step 2 &ndash; Staff Upload Their Receipts</h4>
<p>Staff members with the Upload Expenses permission open <a href="https://larpmanager.com/redirect/event/manage/upload_expenses/" target="_blank" rel="noopener"><strong>Event &gt; Upload Expenses</strong></a> and click "New". They enter the amount, the receipt, the type and a short description of what they paid out of pocket, with one request for each receipt.</p>
<h4>Step 3 &ndash; Approve the Expenses</h4>
<p>Review each receipt in <a href="https://larpmanager.com/redirect/event/manage/expenses/" target="_blank" rel="noopener"><strong>Event &gt; Expenses</strong></a> and click "Approve". The amounts are issued as credits to the staff member, who can use them for future registrations or ask for a refund.</p>
<h4>Step 4 &ndash; Staff Request a Refund of Their Credits</h4>
<p>Staff members find their credits in Accounting, from the sidebar of the home page. They click "Submit a new refund request", enter the payment details and the amount, up to their credits. The organization reviews the request in <a href="https://larpmanager.com/redirect/manage/refunds/" target="_blank" rel="noopener"><strong>Organization &gt; Refunds</strong></a> and marks it as done after the transfer.</p>
<h4>Step 5 &ndash; Record the Outflows</h4>
<p>Payments made from the organization accounts, such as the venue rent, go in <a href="https://larpmanager.com/redirect/event/manage/outflows/" target="_blank" rel="noopener"><strong>Event &gt; Outflows</strong></a>. Add the amount, a description, the invoice and the type of cost.</p>
<h4>Step 6 &ndash; Record the Inflows</h4>
<p>Income that does not come from registration fees, such as a sponsorship, goes in <a href="https://larpmanager.com/redirect/event/manage/inflows/" target="_blank" rel="noopener"><strong>Event &gt; Inflows</strong></a>, with its amount, description and document.</p>
<h4>Step 7 &ndash; Read the Event Balance</h4>
<p><a href="https://larpmanager.com/redirect/event/manage/accounting/" target="_blank" rel="noopener"><strong>Event &gt; Accounting</strong></a> adds everything up: realized revenue (registration fees plus inflows), total costs (expenses plus outflows) and the net profit of the event, with a breakdown of each entry.</p>
<h4>Step 8 &ndash; Close the Event</h4>
<p>Once the event is over, set its status to Concluded from the dashboard. Its net profit then joins the Global balance in <a href="https://larpmanager.com/redirect/manage/accounting/" target="_blank" rel="noopener"><strong>Organization &gt; Accounting</strong></a>.</p>
<hr>
<p><strong>Related resources</strong></p>
<ul>
<li>Learn every <strong>accounting tool</strong>, from tokens and credits to refunds and taxes (<a href="/tutorials/accounting/">read here</a>)</li>
<li>Enable advanced features of registration accounting, such as <strong>installments, discounts or surcharges</strong> (<a href="/tutorials/registration-accounting/">read here</a>)</li>
<li>Set up <strong>payment methods</strong> across many payment gateways (<a href="/tutorials/payments/">read here</a>)</li>
<li>Collect <strong>registration fees</strong> from players (<a href="/guide/payments/">read here</a>)</li>
<li>Give your staff the <strong>roles and permissions</strong> they need (<a href="/guide/roles/">read here</a>)</li>
</ul>
', '', true, 'accounting, expenses, inflows, outflows, balance, refunds, credits', 'calculator', 'Accounting', 'XDQD15lDAZs');
INSERT INTO public.larpmanager_larpmanagerguide VALUES (11, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 11, 'Character creation', 'How players create and submit characters, with staff able to review, request changes, and approve submissions', 'creation', '<p>With LarpManager, you can manage player-created characters with a clear approval process. Players propose their characters; staff can request changes or approve them.</p>
<hr>
<h4>Step 1 &ndash; Create the Event</h4>
<p>Create a new event, then enable <a href="/tutorials/character-creation/">character creation</a> to allow players to create and manage their own characters.</p>
<h4>Step 2 &ndash; Configure the Event</h4>
<p>In the event configuration, turn on the <a href="/tutorials/character-creation/#approval">approval process</a>.</p>
<h4>Step 3 &ndash; Define Character Fields</h4>
<p>Add the <a href="/tutorials/character-form/#manage-fields">fields</a> players fill in, such as background, class or origin. Choose which fields lock once the character is approved, and which stay editable by the player after approval.</p>
<h4>Step 4 &ndash; Test the Player View</h4>
<p>Sign up for the event as a player, then open the character creation form and fill in the requested data.</p>
<h4>Step 5 &ndash; Propose the Character</h4>
<p>The player confirms and submits the character. Staff see it waiting for approval, and can either request changes or approve it.</p>
<h4>Step 6 &ndash; Approval and Publishing</h4>
<p>Once approved, the character appears in the <a href="/tutorials/characters/#gallery-and-search">gallery</a>. The player can now edit only the fields you allowed to stay editable after approval.</p>
<hr>
<p><strong>Related resources</strong></p>
<ul>
<li>Explore the options of <strong>character creation</strong> and of the approval process (<a href="/tutorials/character-creation/">read here</a>)</li>
<li>Configure the <strong>character form</strong> with any number and type of fields (<a href="/tutorials/character-form/">read here</a>)</li>
<li>Manage <strong>characters</strong>, their gallery and field visibility (<a href="/tutorials/characters/">read here</a>)</li>
<li>Configure <strong>abilities</strong> and assign <strong>experience points</strong> to support character progression (<a href="/guide/xp/">read here</a>)</li>
<li>Link multiple events in a <strong>campaign</strong> to share characters across them (<a href="/guide/campaign/">read here</a>)</li>
<li>Prefer <strong>characters written by your staff</strong> (<a href="/guide/writing/">read here</a>)</li>
</ul>
', '', true, 'character creation, player characters, approval, character form', 'pen-nib', 'Characters', 'XyhQnXqRiLo');
INSERT INTO public.larpmanager_larpmanagerguide VALUES (12, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 12, 'Character progression', 'How to manage character progression with XP tracking, abilities / skills tree, and a player-friendly interface', 'xp', '<p>LarpManager makes character progression easy and structured: organizers can assign XP, define abilities with detailed constraints, and give players a clean interface to choose them. Everything stays transparent, letting organizers keep full oversight of character growth.</p>
<hr>
<h4>Step 1 &ndash; Create the Event</h4>
<p>Create a new event, then enable its features: <a href="/guide/creation/">character creation</a> and Experience points.</p>
<h4>Step 2 &ndash; Configure the Event</h4>
<p>In the <a href="/tutorials/xp/#configurations">event configuration</a>, set the starting XP and let players pick abilities themselves.</p>
<h4>Step 3 &ndash; Define Ability Types</h4>
<p>Create broad categories for abilities, such as Skills, Powers or Perks. Types organize abilities for players.</p>
<h4>Step 4 &ndash; Create Abilities</h4>
<p>Add individual <a href="/tutorials/xp/#abilities">abilities</a>, each with a name, a type and an XP cost. An ability can require others as prerequisites, letting you build progression trees.</p>
<h4>Step 5 &ndash; Test the Player View</h4>
<p>Sign up and create a character, then spend XP on an ability. Players only see abilities they can afford, so an ability costing more than the available XP stays hidden.</p>
<h4>Step 6 &ndash; Award Experience Points</h4>
<p><a href="/tutorials/xp/#awards">Give XP</a> to any group of characters. With the award, new abilities can be bought, and the bought ones are listed on the character.</p>
<hr>
<p><strong>Related resources</strong></p>
<ul>
<li>Set up character fields <strong>automatically computed</strong> from the abilities obtained, for example Hit Points (<a href="/tutorials/xp/#rules">read here</a>)</li>
<li>Configure an <strong>undo window</strong> to let players remove newly acquired abilities (<a href="/tutorials/xp/#configurations">read here</a>)</li>
<li>Handle <strong>complex ability interactions</strong>, like default class skills and blocked skills (<a href="/tutorials/xp/#modifiers">read here</a>)</li>
<li>Set up the <strong>character creation process</strong>, with approval by the organizers (<a href="/guide/creation/">read here</a>)</li>
<li>Keep characters and their growth across a <strong>campaign</strong> (<a href="/guide/campaign/">read here</a>)</li>
</ul>
', '', true, 'character progression, experience points, xp, abilities, skills', 'star', 'Characters', 'eFpxNMqGq1c');
INSERT INTO public.larpmanager_larpmanagerguide VALUES (13, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 13, 'Campaigns', 'How to configure LARP campaign events, connecting multiple sessions so players can keep and develop the same character across events', 'campaign', '<p>LarpManager makes it simple to run LARP <strong>campaigns</strong>: a series of connected events set in the same narrative universe, where players create a character and continue their story across multiple sessions.</p>
<hr>
<h4>Step 1 &ndash; Create the First Event</h4>
<p>Start from a <a href="/guide/first/">regular event</a>: no special settings are needed at this stage.</p>
<h4>Step 2 &ndash; Enable Character Creation</h4>
<p>In the first event, enable <a href="/guide/creation/">character creation</a> to let players create their own characters, and allow each player one character.</p>
<h4>Step 3 &ndash; The Player Registers</h4>
<p>The player signs up for the event, then creates their character.</p>
<h4>Step 4 &ndash; Enable Campaigns</h4>
<p>In the organization features, turn on <a href="/tutorials/manage-events/#campaign">Campaign</a>.</p>
<h4>Step 5 &ndash; Create the Next Event</h4>
<p>Create the next event and link it to the first one. Features and configuration are imported automatically. Repeat this for every event of the series. To repeat the same event on new dates instead, <a href="/guide/manage/">add a session</a>.</p>
<h4>Step 6 &ndash; Characters Carry Over</h4>
<p>The player registers for the next event and already has the same character.</p>
<hr>
<p><strong>Related resources</strong></p>
<ul>
<li>Explore all possible <strong>event configurations</strong> (<a href="/tutorials/manage-events/">read here</a>)</li>
<li>Set up <strong>roles</strong> for other staff members (<a href="/tutorials/event-roles/">read here</a>)</li>
<li>Set the gallery to display only the <strong>characters of registered players</strong>, hiding retired characters in later events (<a href="/tutorials/event-appearance/#customize-gallery">read here</a>)</li>
<li>Add a <strong>new session</strong> of the same event, and control who sees it (<a href="/guide/manage/">read here</a>)</li>
<li>Enable a <strong>character approval process</strong>, with staff approving each character (<a href="/guide/creation/">read here</a>)</li>
<li>Configure <strong>abilities</strong> and assign <strong>experience points</strong> across the campaign (<a href="/guide/xp/">read here</a>)</li>
</ul>
', '', true, 'campaign, sessions, recurring characters, continuity', 'calendar-days', 'Characters', 'ZvKKQxJkrF8');
INSERT INTO public.larpmanager_larpmanagerguide VALUES (20, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 20, 'Character sheet PDFs', 'How to generate character sheet PDFs, set page layout, header and footer, sizes and colors, and customize them with a background, your fonts and CSS', 'pdf', '<p>LarpManager turns every character into a printable <strong>PDF sheet</strong>, ready for players and for your printed materials. The standard layout works out of the box, and a few options give it the look of your event: page format, header and footer, sizes and colors, a <strong>background image</strong>, your own <strong>fonts</strong>, and custom <strong>CSS</strong> for anything else.</p><hr><h4>Step 1 &ndash; Turn on PDF generation</h4><p>Go to <a href="https://larpmanager.com/redirect/event/manage/features/" target="_blank" rel="noopener"><strong>Event &gt; Features</strong></a> and activate <em>PDF generation</em>, which needs <em>Characters</em>. You land on <a href="https://larpmanager.com/redirect/event/manage/pdf/" target="_blank" rel="noopener"><strong>Event &gt; PDF</strong></a>, where sheets, gallery and profiles are generated for you.</p><h4>Step 2 &ndash; Try the standard sheet</h4><p>Under <em>Try the sheet generation</em>, pick a character and open the <em>Complete sheet</em>: it holds everything the player should read, from presentation and text to factions and relationships. Without any option, it uses a clean standard layout.</p><h4>Step 3 &ndash; Set the page layout</h4><p>Choose the <em>Page size</em> (A4, A5 or Letter, also landscape) and the <em>Page margin</em> in centimeters. <em>Header</em> adds the names of organization, character and event on top of each page; <em>Footer</em> adds the event name and the page number. <em>Title size</em> and <em>Text size</em> are in percent of the standard one, and the colors set titles, text, links, bold text and separator lines. Every change is saved right away, so you can open the sheet again and see the result without confirming.</p><h4>Step 4 &ndash; Add a background and your fonts</h4><p>Upload a <em>Background image</em>: it is stretched over the whole page, so pick one with a calm center and set the margin to keep the text inside any frame. Then upload a TTF font for the titles and one for the text, to give the sheet the mood of your event.</p><h4>Step 5 &ndash; Fine-tune with your own CSS</h4><p>The <em>CSS</em> field is applied after all the other options, so it has the last word on every element. For example, <code>#char_name { text-transform: uppercase; border-bottom: 2px solid #8C6A3F; }</code> puts the character name in capitals and underlines it.</p><h4>Step 6 &ndash; Print and share the sheets</h4><p>The <em>Lightweight sheet</em> is a plain version, cheaper to print. From the top of the page you can download the gallery and the profiles, pick any set of sheets with <em>Bulk download</em>, or get all the printable sheets as a ZIP. Players download their own sheet from their character page.</p>
<hr>
<p><strong>Related resources</strong></p>
<ul>
<li>Explore all the options of <strong>PDF generation</strong> (<a href="/tutorials/pdf-generation/">read here</a>)</li>
<li>Manage <strong>characters</strong>, their gallery and field visibility (<a href="/tutorials/characters/">read here</a>)</li>
<li>Print the sheets of your <strong>factions</strong> (<a href="/tutorials/factions/">read here</a>)</li>
<li>Write <strong>characters, factions and plots</strong> (<a href="/guide/writing/">read here</a>)</li>
<li>Publish character sheets to players <strong>step by step</strong> (<a href="/guide/publishing/">read here</a>)</li>
<li>Let players <strong>create their own characters</strong> (<a href="/guide/creation/">read here</a>)</li>
</ul>
', '', true, 'pdf, character sheet, print, layout, fonts, background, css', 'file-pdf', 'Organization', 'eLjpuakdNqg');
INSERT INTO public.larpmanager_larpmanagerguide VALUES (14, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 14, 'Character fields, factions and plots', 'How to write characters with custom fields, organize them in factions and link them to plots', 'writing', '<p>LarpManager offers a variety of tools to help you write characters: you can organize them into <strong>factions</strong> and connect them to <strong>plots</strong> that drive quests, storylines and scenarios.</p>
<hr>
<h4>Step 1 &ndash; Create the Event</h4>
<p>Create your event: the character tools are ready to use.</p>
<h4>Step 2 &ndash; Enable Factions and Plots</h4>
<p>In the event features, activate <a href="/tutorials/factions/">Factions</a> and <a href="/tutorials/plots/">Plots</a> to structure group dynamics and narrative arcs.</p>
<h4>Step 3 &ndash; Design the Character Form</h4>
<p>Add any number and type of <a href="/tutorials/character-form/#manage-fields">fields</a>, and choose who can see each one. Drag a field to change its position.</p>
<h4>Step 4 &ndash; Write Characters</h4>
<p>Fill in the fields of <a href="/tutorials/characters/#manage-characters">each character</a> directly in the system, with automatic saving. Every saved text stays available as a version.</p>
<h4>Step 5 &ndash; Create Factions</h4>
<p>Create factions and group characters into them.</p>
<h4>Step 6 &ndash; Create Plots</h4>
<p>Create a plot for the event: its text is shared by every linked character. Link characters to plots, with their role in each. Each plot shows the characters involved, and the sheet combines fields, texts, factions and plots.</p>
<hr>
<p><strong>Related resources</strong></p>
<ul>
<li>Explore all the configurations of <strong>factions</strong> (<a href="/tutorials/factions/">read here</a>)</li>
<li>Explore all the configurations of <strong>plots</strong> (<a href="/tutorials/plots/">read here</a>)</li>
<li>Configure the <strong>character form</strong> with any number and type of fields (<a href="/tutorials/character-form/">read here</a>)</li>
<li>Manage <strong>characters</strong>, their gallery and field visibility (<a href="/tutorials/characters/">read here</a>)</li>
<li>Add <strong>handouts, workshops and other writing elements</strong> (<a href="/tutorials/writing-extras/">read here</a>)</li>
<li>Assign characters through a <strong>casting algorithm</strong> that maximizes satisfaction across player preferences (<a href="/guide/assign/">read here</a>)</li>
<li>Let players <strong>create their own characters</strong> instead (<a href="/guide/creation/">read here</a>)</li>
<li>Publish character sheets to players <strong>step by step</strong> (<a href="/guide/publishing/">read here</a>)</li>
<li>Write reusable <strong>quests and traits</strong> (<a href="/guide/quests/">read here</a>)</li>
<li>Print character sheets as <strong>PDF</strong> (<a href="/guide/pdf/">read here</a>)</li>
</ul>
', '', true, 'writing, characters, factions, plots, character form', 'feather', 'Writing', 'dfSwigh8Fgs');
INSERT INTO public.larpmanager_larpmanagerguide VALUES (15, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 15, 'Publishing characters', 'How to link characters with reference codes, then publish their sheets to players step by step', 'publishing', '<p>Write character sheets the way you prefer, linking characters to each other with <strong>reference codes</strong>, and keep them hidden until you are ready: with <strong>field visibility</strong> you choose which fields players see, and when.</p>
<hr>
<h4>Step 1 &ndash; Reference Other Characters</h4>
<p>While writing a character, type <strong>#</strong> and pick another character: its number is inserted in the text. Use <strong>@</strong> for a one-way link, and <strong>^</strong> for a simple mention.</p>
<h4>Step 2 &ndash; References Become Links</h4>
<p>On the sheet, each number becomes a link to the character: hover it to preview the character and their player. The <strong>relationships</strong> of the character are shown on the sheet too.</p>
<h4>Step 3 &ndash; Enable Field Visibility</h4>
<p>By default, players see every field of their sheet. In the event configuration, under <em>Characters</em>, enable <strong>Field visibility</strong> to choose what to show and when.</p>
<h4>Step 4 &ndash; Players See Nothing Yet</h4>
<p>While you are still writing, the sheet of the player stays empty.</p>
<h4>Step 5 &ndash; Reveal Name and Presentation</h4>
<p>In the event settings, under <em>Visibility</em>, pick the fields to show. Public fields go to every participant, private ones only to the player of the character. Players can now browse the characters in the gallery, and read the presentation of their own.</p>
<h4>Step 6 &ndash; Reveal the Full Sheet</h4>
<p>Right before the event, show the text and the relationships: the player now reads the full sheet, with links to the other characters.</p>
<hr>
<p><strong>Related resources</strong></p>
<ul>
<li>Use <strong>reference codes</strong> to link characters, factions and plots (<a href="/tutorials/character-references/">read here</a>)</li>
<li>Manage <strong>characters</strong>, their gallery and field visibility (<a href="/tutorials/characters/">read here</a>)</li>
<li>Configure the <strong>character form</strong> and the visibility of each field (<a href="/tutorials/character-form/">read here</a>)</li>
<li>Generate <strong>PDF sheets</strong> of the characters (<a href="/tutorials/pdf-generation/">read here</a>)</li>
<li>Write characters, factions and plots (<a href="/guide/writing/">read here</a>)</li>
<li>Let players <strong>create their own characters</strong> (<a href="/guide/creation/">read here</a>)</li>
</ul>
', '', true, 'publishing, visibility, references, character sheet, reveal', 'eye', 'Writing', 'gawXyccgiL0');
INSERT INTO public.larpmanager_larpmanagerguide VALUES (16, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 16, 'Quests and traits', 'How to write quest types, quests and traits, let participants choose them, and assign them to characters', 'quests', '<p>Quests and traits let you write parts of the character sheets as reusable pieces. Participants choose the traits they prefer, and each one is then assigned to a character, who reads its text in the character sheet.</p>
<hr>
<h4>Step 1 &ndash; Enable Quests and Traits</h4>
<p>In the event features, activate <a href="/tutorials/quests/">Quests and Traits</a>, together with the <a href="/tutorials/casting/">Casting algorithm</a> to collect the preferences of participants.</p>
<h4>Step 2 &ndash; Create a Quest Type</h4>
<p>In <a href="https://larpmanager.com/redirect/event/manage/quest_types/" target="_blank" rel="noopener"><strong>Event &gt; Quest type</strong></a>, create a quest type, such as Heist roles. It groups quests of the same category: each character gets at most one trait per quest type.</p>
<h4>Step 3 &ndash; Write a Quest</h4>
<p>In <a href="https://larpmanager.com/redirect/event/manage/quests/" target="_blank" rel="noopener"><strong>Event &gt; Quest</strong></a>, create a quest of that type. Its presentation is shown to all participants, while its text is visible only to the characters assigned one of its traits.</p>
<h4>Step 4 &ndash; Add Its Traits</h4>
<p>In <a href="https://larpmanager.com/redirect/event/manage/traits/" target="_blank" rel="noopener"><strong>Event &gt; Traits</strong></a>, add the traits of the quest, one for each role. Type # in the text to reference another trait: once traits are assigned, the reference shows the name of the character who received it.</p>
<h4>Step 5 &ndash; Choose Your Preferred Traits</h4>
<p>Participants find the quests in the Quest entry of the event menu, with their presentation and traits. In Casting, they select the quest type and rank the traits they prefer.</p>
<h4>Step 6 &ndash; Assign the Traits</h4>
<p>In <a href="https://larpmanager.com/redirect/event/manage/casting/" target="_blank" rel="noopener"><strong>Event &gt; Casting</strong></a>, select the quest type and start the algorithm, which gives each participant a trait following their preferences, then upload the result. Participants who did not send preferences, such as late sign-ups, get a trait by hand from their registration in <a href="https://larpmanager.com/redirect/event/manage/registrations/" target="_blank" rel="noopener"><strong>Event &gt; Registrations</strong></a>.</p>
<h4>Step 7 &ndash; Read the Trait in the Character Sheet</h4>
<p>Each participant finds the assigned trait in the character sheet, with its references replaced by the names of the other characters. Hovering a name shows who plays that character, and the sheet links to each of them.</p>
<hr>
<p><strong>Related resources</strong></p>
<ul>
<li>Explore all the options of <strong>quests and traits</strong> (<a href="/tutorials/quests/">read here</a>)</li>
<li>Assign traits with the <strong>casting</strong> algorithm (<a href="/tutorials/casting/">read here</a>)</li>
<li>Manage <strong>characters</strong>, their gallery and field visibility (<a href="/tutorials/characters/">read here</a>)</li>
<li>Assign characters with <strong>casting</strong> (<a href="/guide/assign/">read here</a>)</li>
<li>Write <strong>characters, factions and plots</strong> (<a href="/guide/writing/">read here</a>)</li>
</ul>
', '', true, 'quests, traits, quest types, preferences, character sheet', 'dungeon', 'Writing', 'eDMeRsDlfro');
INSERT INTO public.larpmanager_larpmanagerguide VALUES (17, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 17, 'Casting', 'How to assign characters using player preferences and an algorithm that maximizes overall satisfaction', 'assign', '<p>LarpManager helps you assign characters to players by collecting their preferences and running an algorithm that finds the best distribution, maximizing satisfaction for everyone.</p>
<hr>
<h4>Step 1 &ndash; Create the Event</h4>
<p>Create the event, enable the <a href="/tutorials/casting/#casting-algorithm">casting algorithm</a> and prepare the <a href="/guide/writing/">characters</a> players will choose from.</p>
<h4>Step 2 &ndash; Configure the Event</h4>
<p>In the event configuration, choose the minimum and maximum number of preferences each player can send.</p>
<h4>Step 3 &ndash; Test the Player View</h4>
<p>Sign up for the event as a player, as in the <a href="/guide/tickets/">registration form</a>, then choose characters in order of preference.</p>
<h4>Step 4 &ndash; Run the Casting Algorithm</h4>
<p>As an organizer, review the preferences of every player, then start the algorithm. It finds the distribution that satisfies everyone most.</p>
<h4>Step 5 &ndash; Refine and Re-run</h4>
<p>Block any assignment that is not possible, then run the algorithm again as many times as needed.</p>
<h4>Step 6 &ndash; Finalize Assignments</h4>
<p>When satisfied, upload the result. Characters are now officially assigned to players.</p>
<hr>
<p><strong>Related resources</strong></p>
<ul>
<li>Explore all the configurations of <strong>casting</strong> (<a href="/tutorials/casting/">read here</a>)</li>
<li>Configure the <strong>character form</strong> with any number and type of fields (<a href="/tutorials/character-form/">read here</a>)</li>
<li>Manage <strong>registrations</strong> and the characters assigned to them (<a href="/tutorials/registrations/">read here</a>)</li>
<li>Write characters with automatic saving and version control, and manage <strong>factions</strong> and <strong>plots</strong> (<a href="/guide/writing/">read here</a>)</li>
<li>Let players <strong>create their own characters</strong> instead (<a href="/guide/creation/">read here</a>)</li>
<li>Collect <strong>matchmaker preferences</strong> before casting (<a href="/guide/approval/">read here</a>)</li>
</ul>
', '', true, 'casting, character assignment, preferences, algorithm', 'users', 'Writing', 'mnjboL3o9TQ');
INSERT INTO public.larpmanager_larpmanagerguide VALUES (18, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 18, 'Membership', 'How players apply for membership, how to approve their requests, and how the annual fee is collected', 'membership', '<p>With the <a href="/tutorials/membership/">Membership</a> feature, only approved members can take part in the events of your organization. Each player downloads a request pre-filled with their data, signs it and uploads it with an identity document; the staff reviews and approves it, and the annual membership fee is added to the first payment of the year.</p>
<hr>
<h4>Step 1 &ndash; Enable Membership</h4>
<p>Activate the <a href="/tutorials/membership/">Membership</a> feature in <a href="https://larpmanager.com/redirect/manage/features/" target="_blank" rel="noopener"><strong>Organization &gt; Features</strong></a>. Its settings open right away: set the annual fee, which is added to the first registration payment of each membership year.</p>
<h4>Step 2 &ndash; Write the Membership Request</h4>
<p>The dashboard reminds you to set up the request text. In <a href="https://larpmanager.com/redirect/manage/texts/" target="_blank" rel="noopener"><strong>Organization &gt; Texts</strong></a>, add a text of type Membership request: placeholders such as <code>{{ member.name }}</code> are filled in with the data of each member.</p>
<h4>Step 3 &ndash; Register for the Event</h4>
<p>When a player registers, the summary shows the total with the membership fee included, and explains that a membership request is needed to confirm the registration. The player then consents to share their personal data.</p>
<h4>Step 4 &ndash; Upload the Signed Request</h4>
<p>The player downloads the request pre-filled with their data, signs it, and uploads the scan together with a photo of an identity document. After checking both documents, they send the request to the staff.</p>
<h4>Step 5 &ndash; Approve the Request</h4>
<p>New requests appear at the top of <a href="https://larpmanager.com/redirect/manage/membership/" target="_blank" rel="noopener"><strong>Organization &gt; Members</strong></a>. Open the request, review the documents and approve it: the player becomes a member. You can also reject it, and the player can submit a new one.</p>
<h4>Step 6 &ndash; Pay Registration and Fee</h4>
<p>Once approved, the member can pay. The payment page lists the registration fee and the membership fee together, and the member notifies the organizer after the transfer.</p>
<h4>Step 7 &ndash; Confirm the Payment</h4>
<p>Confirm the transfer in <a href="https://larpmanager.com/redirect/event/manage/payments/" target="_blank" rel="noopener"><strong>Event &gt; Payments</strong></a>. <a href="https://larpmanager.com/redirect/event/manage/registrations/" target="_blank" rel="noopener"><strong>Event &gt; Registrations</strong></a> shows the membership status and the payments of each participant.</p>
<hr>
<p><strong>Related resources</strong></p>
<ul>
<li>Explore all the options of <strong>membership</strong> (<a href="/tutorials/membership/">read here</a>)</li>
<li>Set up <strong>payment methods</strong> across many payment gateways (<a href="/tutorials/payments/">read here</a>)</li>
<li>Check the <strong>deadlines</strong> of membership and payments (<a href="/tutorials/deadlines/">read here</a>)</li>
<li>Manage the <strong>users</strong> of your organization (<a href="/tutorials/users/">read here</a>)</li>
<li>Collect and confirm the <strong>payments</strong> of your players (<a href="/guide/payments/">read here</a>)</li>
</ul>
', '', true, 'membership, members, annual fee, membership request, approval', 'id-card', 'Organization', 'IxMM5_T-So0');

INSERT INTO public.larpmanager_larpmanagernewsletter VALUES (1, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'test@test.it', 'a');
INSERT INTO public.larpmanager_larpmanagernewsletter VALUES (2, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'admin@test.it', 'a');

INSERT INTO public.larpmanager_larpmanagertutorial VALUES (1, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Create Organization', 'create-organization', '<p>This tutorial explains how to create your organization, the space where all your events live, and how to find your way around the management interface: the top bar, the sidebar and the help links.</p>
<p>To set up your organization, go to the <a href="https://larpmanager.com/get-started/#get-started-real" target="_blank" rel="noopener"><strong>Get started</strong></a> page and complete the creation form:</p>
<p><img src="/static/tutorials/001_create-organization_01.webp" alt="Create your organization form" width="942" height="1022"></p>
<hr>
<h2>Organization settings</h2>
<ul>
<li><strong>Name</strong>: The full name of your organization.</li>
<li><strong>Logo</strong>: An optional image used as your organization''s logo. You can upload any image format and size; it is scaled automatically.</li>
<li><strong>Subdomain</strong>: The subdomain name for your organization. For example, if you choose "lp", all your pages are under <code>https://lp.larpmanager.com</code>. Use only letters and numbers - no spaces or symbols.</li>
<li><strong>Payment currency</strong>: The currency used for all payments and pricing.</li>
</ul>
<hr>
<p>Click Submit to create your subdomain.</p>
<p>Upon submission, you are redirected to <a href="https://larpmanager.com/redirect/manage/" target="_blank" rel="noopener"><strong>Organization &gt; Dashboard</strong></a>. From this hub, you can create events, configure sessions, and access all organization-level tools.</p>
<p><em>Note: On first creation, the organization is in Lite Mode, where only basic functions are available. Complete the Activation Checklist to unlock Full Mode and access all features.</em></p>
<p><em>Note: the screenshots in these tutorials show an example organization, "Test Organization", with one event, "Test Event". In your pages you will see the names of your own organization and events.</em></p>
<p>At the top is the top bar, visible only to users with a management role in the organization or in one of its events. On the left, it shows the name of your organization and of the events you manage: click one to open its management pages.</p>
<p><img src="/static/tutorials/001_create-organization_02.webp" alt="Organization and event selector" width="304" height="49"></p>
<p>On the right, the <strong>User</strong> / <strong>Admin</strong> switch moves between the management pages and the pages seen by participants:</p>
<p><img src="/static/tutorials/001_create-organization_03.webp" alt="User and Admin switch" width="132" height="48"></p>
<p>On the left side of the page is the sidebar, with links to all the active functions of the organization or event you are managing:</p>
<p><img src="/static/tutorials/001_create-organization_04.webp" alt="Management sidebar" width="266" height="405"></p>
<p><em>On mobile, the left button opens the sidebar, and the right one the topbar:</em> </p>
<p><em><img src="/static/tutorials/001_create-organization_05.webp" alt="Mobile navigation bar" width="383" height="125"></em></p>
<hr>
<p>If in the future you need to update the Organization, go to <a href="https://larpmanager.com/redirect/manage/organization/" target="_blank" rel="noopener"><strong>Organization &gt; Organization</strong></a>.</p>
<hr>
<p>Remember to access the LarpManager help pages if you need any help!</p>
<p><img src="/static/tutorials/001_create-organization_06.webp" alt="Help links" width="271" height="151"></p>
<hr>
<h2>Organization features</h2>
<p>LarpManager includes over 100 features, activated only when you need them. Some have an organization-wide scope, and apply to all pages and events of the organization; others have an event scope, and are active only for a specific event (see <a href="https://larpmanager.com/tutorials/manage-events/#event-features" target="_blank" rel="noopener"><em><strong>Manage Events</strong></em></a>).</p>
<p>To activate features for the whole organization, go to <a href="https://larpmanager.com/redirect/manage/features/" target="_blank" rel="noopener"><strong>Organization &gt; Features</strong></a>:</p>
<p><img src="/static/tutorials/040_advanced-features_01.webp" alt="Organization features" width="992" height="576"></p>
<p>Click a feature''s name to open a popup with its description. Select the features you want to activate and confirm.</p>
<p>Some features need further settings, in <a href="https://larpmanager.com/redirect/manage/config/" target="_blank" rel="noopener"><strong>Organization &gt; Configuration</strong></a>.</p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/organization-roles/" target="_blank" rel="noopener"><em><strong>Organization Roles</strong></em></a>, <a href="https://larpmanager.com/tutorials/organization-appearance/" target="_blank" rel="noopener"><em><strong>Organization Appearance</strong></em></a>, <a href="https://larpmanager.com/tutorials/manage-events/" target="_blank" rel="noopener"><em><strong>Manage Events</strong></em></a>, <a href="https://larpmanager.com/tutorials/player-information/" target="_blank" rel="noopener"><em><strong>Personal Data</strong></em></a></em></p>', 1);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (2, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Personal Data', 'player-information', '<p>LarpManager can collect personal data from participants when they sign up for your events - such as address, date of birth, or fiscal code. This tutorial explains which fields are available, how to configure your organization''s profile form, and what participants will see when filling it in.</p>
<hr>
<h2>Organization profile</h2>
<p>When a user signs up for one of your events, LarpManager can collect and store specific personal data from them.</p>
<p>To choose which data to collect, go to <a href="https://larpmanager.com/redirect/manage/profile/" target="_blank" rel="noopener"><strong>Organization &gt; Profile</strong></a>.</p>
<p>(Note that the first name and surname are stored by default.)</p>
<p><img src="/static/tutorials/010_player-information_01.webp" alt="Profile fields" width="992" height="1183"></p>
<p>Here is a description of the available fields:</p>
<ul>
<li><strong>Portrait:</strong> A photo of the participant. Displayed in their public profile and in the game gallery.</li>
<li><strong>Alias</strong>: By default, LarpManager displays a participant''s first and last name in the event''s public participant list. If a participant prefers not to show their real name, they can enter a nickname. (Their real name will still be visible to organizers and to other participants of the same event)</li>
<li><strong>Pronouns</strong>: The participant''s preferred pronouns, shown in their public profile.</li>
<li><strong>Contact</strong>: A contact method for the participant (e.g., email, social media). Shown in the public profile.</li>
<li><strong>Nationality, Phone Contact, Birth Date, Birth Place, Residence Address</strong>: Personal data not shown in the public profile.</li>
<li><strong>First Aid</strong>: Indicates whether the participant is trained in first aid. Visible in the participant list for the game.</li>
<li><strong>Document Type, Document Number, Date of issue, Date of expiration</strong>: The type, number and dates of an official identity document, based on the participant''s country.</li>
<li><strong>Diet</strong>: Dietary restrictions or needs. Visible only to selected organizers.</li>
<li><strong>Safety</strong>: Information about physical or mental health. Visible only to selected organizers.</li>
<li><strong>Legal Name:</strong> If the participant uses a name different from their legal name, the legal name can be entered here. It is used only for legal documents generated by LarpManager and is not visible to other participants.</li>
<li><strong>Legal Gender:</strong> as it appears on official documents. It will only be used for internal bureaucratic purposes, and will NEVER be displayed to other participants.</li>
<li><strong>Presentation</strong>: A short personal description, used in advanced features.</li>
</ul><p><em>Note: If a participant previously provided this data when registering for an event from another organization using LarpManager, the data is pre-filled.</em></p>
<hr>
<h2>Sensitive data</h2>
<p>You can review all participant data of each event in <a href="https://larpmanager.com/redirect/event/manage/sensitive/" target="_blank" rel="noopener"><strong>Event &gt; Users</strong></a>.</p>
<p><img src="/static/tutorials/010_player-information_02.webp" alt="Users data of the event" width="993" height="628"></p>
<p>Additionally, in <a href="https://larpmanager.com/redirect/event/manage/registrations/" target="_blank" rel="noopener"><strong>Event &gt; Registrations</strong></a> of each event, an eye icon appears next to each participant''s name. Clicking the icon opens a popup displaying all available participant data (scrollable if the list is long).</p>
<p><em>Note: Sensitive data is visible only to users whose role includes the "<strong>Sensitive Data</strong>" permission.</em></p>
<p><img src="/static/tutorials/010_player-information_03.webp" alt="Registrations with the sensitive data icon" width="983" height="301"></p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/users/" target="_blank" rel="noopener"><em><strong>Users</strong></em></a>, <a href="https://larpmanager.com/tutorials/registrations/" target="_blank" rel="noopener"><em><strong>Registrations</strong></em></a>, <a href="https://larpmanager.com/tutorials/membership/" target="_blank" rel="noopener"><em><strong>Membership</strong></em></a></em></p>', 10);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (3, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Organization Roles', 'organization-roles', '<p>Roles let you delegate platform management to other team members without giving them full access. Each role is a named set of permissions; users assigned to it can access only the areas you choose. This tutorial covers how to create roles and assign users to them.</p>
<hr>
<h2>Organization roles</h2>
<p>To manage roles and grant permissions to other users, go to <a href="https://larpmanager.com/redirect/manage/roles/" target="_blank" rel="noopener"><strong>Organization &gt; Roles</strong></a>.</p>
<p>An "Admin" role is automatically created and assigned to the user who created the organization. By default, this role has all permissions.</p>
<p><img src="/static/tutorials/020_organization-roles_01.webp" alt="Organization roles" width="992" height="336"></p>
<p><em>(Note: You can only add users to a role if they have granted permission to share their data with your organization. If the organization is newly created, the list is empty. You can invite them clicking on the invite icon.)</em></p>
<p>You can add users to an existing role by clicking the edit icon, or create a new role by clicking "New".</p>
<p>(<em>Note: A user can be assigned to multiple roles. Their permissions are the combined total of all assigned roles)</em></p>
<p><img src="/static/tutorials/020_organization-roles_02.webp" alt="New organization role" width="1260" height="571"></p>
<p>Enter the role name in "<strong>Name</strong>", select the users to assign in "<strong>Members</strong>", and check the management pages they should have access to.</p>
<p><em>Note: Additional permissions will become available as you activate new features.</em></p>
<hr>
<h2>Inviting new users</h2>
<p>To add someone who is not yet in the list, click the envelope icon on the role row and enter their email address. They receive an email with a link to accept the invitation; once they log in (or create an account) with that email address and agree to share their data with your organization, they are added to the role.</p>
<p>Pending invitations are shown under the role, until they are accepted.</p>
<p><em>Note: an invitation can be used only once, only by the email address it was sent to, and expires after some time.</em></p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/event-roles/" target="_blank" rel="noopener"><em><strong>Event Roles</strong></em></a>, <a href="https://larpmanager.com/tutorials/create-organization/" target="_blank" rel="noopener"><em><strong>Create Organization</strong></em></a>, <a href="https://larpmanager.com/tutorials/user-flags/" target="_blank" rel="noopener"><em><strong>User Flags</strong></em></a></em></p>', 20);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (4, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Organization Appearance', 'organization-appearance', '<p>This tutorial explains how to customize the visual identity of your organization''s pages - background image, fonts, colors, and logo - so the platform matches your event brand. Changes apply across all pages of the organization.</p>
<h2>Organization appearance</h2>
<p>To customize the appearance of your organization, go to <a href="https://larpmanager.com/redirect/manage/appearance/" target="_blank" rel="noopener"><strong>Organization &gt; Appearance</strong></a>.</p>
<p><img src="/static/tutorials/030_organization-appearance_01.webp" alt="Organization appearance" width="992" height="521"></p>
<p>Input the following data:</p>
<ul>
<li><strong>Custom Title Font:</strong> A font file (TTF or OTF) used for all page titles.</li>
</ul>
<p>If you select theme Halo (custom), you can additionally input:</p>
<ul>
<li><strong>Background Image:</strong> An image applied as a background on all pages using CSS <code>background-cover</code>. Use an image with minimal detail and low color variation. Any size or format is accepted.</li>
<li><strong>Text Color:</strong> The color used for all text. Choose a color with good contrast against the background image.</li>
<li><strong>Background Color:</strong> The background color for text blocks. Choose a color with good contrast against both the text and background image.</li>
<li><strong>Link Color:</strong> The color used for all hyperlinks.</li>
<li><strong>Association CSS:</strong> Custom CSS code. Contact support if you need the HTML structure to target.</li>
</ul>
<p><em>Note: These settings apply to all pages under the Organization unless an Event has its own customized appearance.</em></p>
<hr>
<h2>Manage texts</h2>
<p>You can also customize some of the texts that are used by LarpManager. To manage them, go to <a href="https://larpmanager.com/redirect/manage/texts/" target="_blank" rel="noopener"><strong>Organization &gt; Texts</strong></a>.</p>
<p>You can edit an existing one, or add a new one by clicking on "New".</p>
<p><img src="/static/tutorials/030_organization-appearance_02.webp" alt="New organization text" width="1260" height="653"></p>
<p>Input the following data:</p>
<ul>
<li><strong>Text</strong>: The custom text content.</li>
<li><strong>Type</strong>: The type of text.</li>
<li><strong>Language</strong>: The language for which this text is shown, based on the user''s profile setting.</li>
<li><strong>Default</strong>: Indicates whether this version should be shown if no text exists for the user''s selected language.</li>
</ul>
<hr>
<p><em>Only one version per language is allowed for each text type.</em><br><em>Only one version can be set as default for each text type.</em></p>
<hr>
<h2>Calendar</h2>
<p>In <a href="https://larpmanager.com/redirect/manage/config/interface/" target="_blank" rel="noopener"><strong>Organization &gt; Configuration &gt; Interface</strong></a>, you can control the advanced display options:</p>
<p><img src="/static/tutorials/030_organization-appearance_03.webp" alt="Interface configuration" width="983" height="840"></p>
<p>Checking those option, additional fields are added in the event creation form, and their value is shown in the calendar.</p>
<hr>
<h2>Carousel</h2>
<p><em>Show your events in a scrolling gallery, like a streaming service.</em> To use it, activate the <a href="https://larpmanager.com/redirect/manage/features/carousel/on/" target="_blank" rel="noopener"><strong>Carousel</strong></a> feature.</p>
<p>Each event gets two new fields in <a href="https://larpmanager.com/redirect/event/manage/event/" target="_blank" rel="noopener"><strong>Event &gt; Event</strong></a>:</p>
<ul>
<li><strong>Carousel image</strong>: the image shown in the carousel.</li>
<li><strong>Carousel description</strong>: a short text shown next to the image.</li>
</ul>
<hr>
<h2>Legal notice</h2>
<p><em>Add a legal notice page, linked from every page.</em> To use it, activate the <a href="https://larpmanager.com/redirect/manage/features/legal_notice/on/" target="_blank" rel="noopener"><strong>Legal Notice</strong></a> feature.</p>
<p>Then, in <a href="https://larpmanager.com/redirect/manage/texts/" target="_blank" rel="noopener"><strong>Organization &gt; Texts</strong></a>, create a text of type "Legal notice" with its content. A "Legal Notice" link is added to the footer of every page.</p>
<hr>
<h2>Custom translations</h2>
<p><em>Change how single words or sentences of the interface are written for your organization.</em> To use it, activate the <a href="https://larpmanager.com/redirect/manage/features/translation/on/" target="_blank" rel="noopener"><strong>Translations</strong></a> feature.</p>
<p>Go to <a href="https://larpmanager.com/redirect/manage/translations/" target="_blank" rel="noopener"><strong>Organization &gt; Translations</strong></a> and click "New":</p>
<p><img src="/static/tutorials/900_sections_03.webp" alt="New custom translation" width="1260" height="716"></p>
<ul>
<li><strong>Language</strong>: the language the translation applies to.</li>
<li><strong>Original text</strong>: the English text as it appears in the interface.</li>
<li><strong>Translated text</strong>: the text to show instead.</li>
<li><strong>Context</strong>: optional, to tell apart the same text used with different meanings.</li>
<li><strong>Active</strong>: uncheck to disable the translation without deleting it.</li>
</ul>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/event-appearance/" target="_blank" rel="noopener"><em><strong>Event Appearance</strong></em></a>, <a href="https://larpmanager.com/tutorials/create-organization/" target="_blank" rel="noopener"><em><strong>Create Organization</strong></em></a>, <a href="https://larpmanager.com/tutorials/manage-mails/" target="_blank" rel="noopener"><em><strong>Mail Settings</strong></em></a></em></p>', 30);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (5, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Manage Events', 'manage-events', '<p>Events are the individual LARP sessions your organization runs. This tutorial explains how to create and configure them, setting dates, registration status, and appearance, as well as how to link events together into a campaign.</p>
<h2>Create event</h2>
<p>To create a new event, go to <a href="https://larpmanager.com/redirect/manage/events/" target="_blank" rel="noopener"><strong>Organization &gt; Events</strong></a>.</p>
<p>In this page, you can see all of your events. Click on "New event" to create a new one.</p>
<p><img src="/static/tutorials/050_manage-events_01.webp" alt="New event form" width="1260" height="597"></p>
<h2>Event settings</h2>
<p>Input the following values:</p>
<ul>
<li><strong>Name</strong>: The full name of the new Event.</li>
<li><strong>URL Identifier</strong>: A simplified name used to build the URL of the event''s pages. Use only letters and numbers; no spaces or symbols.</li>
<li><strong>Description</strong>: A brief summary of the event (maximum 1000 characters).</li>
<li><strong>Maximum participants:</strong> The maximum number of participants. Set to 0 for unlimited.</li>
<li><strong>Template:</strong> Choose one of the basic event template, or leave empty for full configuration.</li>
<li><strong>Start:</strong> the start date of the event;</li>
<li><strong>End:</strong> the end date of the event (can be the same as start).</li>
<li><strong>Status</strong>: who can see the event. <strong>Cancelled</strong> and <strong>Concluded</strong> are available once the event has its start and end dates.
<ul>
<li><strong>Hidden</strong>: the event is in preparation. It is hidden from the homepage and calendar, and only staff and already registered participants can access it.</li>
<li><strong>Visible</strong>: the event is published. It is listed in the homepage and calendar, and visible to all users.</li>
<li><strong>Cancelled</strong>: the event does not take place. It is hidden from users and excluded from accounting.</li>
<li><strong>Concluded</strong>: the event has taken place. It is archived among past events, and its balance is added to the organization accounting.</li>
</ul>
</li>
<li><strong>Registrations status</strong>: when participants can register.
<ul>
<li><strong>Closed</strong>: participants cannot register. The event page shows that registrations are closed.</li>
<li><strong>Open</strong>: participants can register right away through the registration form, up to the maximum participants.</li>
<li><strong>Pre-registration</strong>: participants cannot register yet, but can pre-register to show their interest and be notified when registrations open. This option appears when the <a href="https://larpmanager.com/redirect/manage/features/pre_register/on/" target="_blank" rel="noopener"><strong>Pre-registration</strong></a> feature is active: see <a href="https://larpmanager.com/tutorials/registrations/#pre-registration" target="_blank" rel="noopener"><em><strong>Pre-registration</strong></em></a>.</li>
<li><strong>External site</strong>: registrations are managed on another site. Input the address in <strong>External registration link</strong>: new participants are redirected there, while registered participants keep access to their registration.</li>
<li><strong>Open on date</strong>: registrations stay closed until the <strong>Registration date</strong>, then open automatically.</li>
<li><strong>Close on date</strong>: registrations are open until the <strong>Registration date</strong>, then close automatically.</li>
</ul>
</li>
</ul>
<hr>
<p><em>On Cancelled and Concluded events, participants cannot register or change a registration: existing registrations stay readable. These events no longer appear in the organizer''s quick bar.</em></p>
<hr>
<p>If you have activated the <em>Characters</em> feature, and the <strong>Field visibility</strong> configuration, in the form you can also control the visibility of specific writing elements to participants. These settings are session-specific, so you can choose to show these fields for one session and not for another.</p>
<p><img src="/static/tutorials/170_characters_03.webp" alt="Character fields visible to players" width="1260" height="164"></p>
<p>If you select "Name", the list of writing elements is visible to participants; furthermore, for each field, you can select to display either to all participants (if the field is set as Public) or only to the participant assigned to that writing element (if the field is set as Private).</p>
<hr>
<p><em>When you create a new event, your user is automatically assigned the Organizer role for that event.</em></p>
<hr>
<p>You can also change the dates, <strong>Status</strong> and <strong>Registrations status</strong> directly from <a href="https://larpmanager.com/redirect/event/manage/" target="_blank" rel="noopener"><strong>Event &gt; Dashboard</strong></a>: click the pencil next to each value.</p>
<p><img src="/static/tutorials/050_manage-events_03.webp" alt="Event card in the dashboard" width="325" height="313"></p>
<hr>
<h2>Participant pages</h2>
<p><em>What participants see, and how they reach your events.</em></p>
<p>The home page of your organization, at <code>https://&lt;subdomain&gt;.larpmanager.com/</code> (the subdomain chosen when creating the organization), lists the upcoming sessions, each with its name, dates and registration status:</p>
<p><img src="/static/tutorials/050_manage-events_08.webp" alt="Upcoming events on the organization home page" width="992" height="483"></p>
<p>A session is listed on the home page when:</p>
<ul>
<li>its <strong>Status</strong> is <em>Visible</em> (a <em>Hidden</em> session is shown only to users already registered to it);</li>
<li>it is not <em>Cancelled</em>;</li>
<li>its end date has not passed yet.</li>
</ul>
<p>To add a text at the top of the home page, create a text of type "Calendar" in <a href="https://larpmanager.com/redirect/manage/texts/" target="_blank" rel="noopener"><strong>Organization &gt; Texts</strong></a>. To show more details on each card (location, website, authors, genre, tagline) or a link to past events, see the <a href="https://larpmanager.com/tutorials/organization-appearance/" target="_blank" rel="noopener"><em><strong>Organization Appearance</strong></em></a> tutorial.</p>
<hr>
<p>Clicking on a session opens its event page, at <code>https://&lt;subdomain&gt;.larpmanager.com/&lt;URL identifier&gt;/</code>. It shows the registration status, the dates and the <strong>Description</strong> of the event:</p>
<p><img src="/static/tutorials/050_manage-events_09.webp" alt="Event page for participants" width="992" height="418"></p>
<p>Organizers can open it from <a href="https://larpmanager.com/redirect/event/manage/" target="_blank" rel="noopener"><strong>Event &gt; Dashboard</strong></a>, with the link icon next to the event name, or with the "User" switch in the top bar.</p>
<hr>
<p>From the registration box of the event page, participants reach the registration page, where they choose a ticket and answer the registration questions:</p>
<p><img src="/static/tutorials/050_manage-events_10.webp" alt="Registration page" width="992" height="537"></p>
<p>Whether participants can sign up depends on the <strong>Registrations status</strong> of the session (see <a href="https://larpmanager.com/tutorials/manage-events/#event-settings" target="_blank" rel="noopener"><em><strong>Event Settings</strong></em></a> above). To configure tickets and questions, see the <a href="https://larpmanager.com/tutorials/manage-ticket/" target="_blank" rel="noopener"><em><strong>Registration Ticket</strong></em></a> and <a href="https://larpmanager.com/tutorials/registration-form/" target="_blank" rel="noopener"><em><strong>Registration Form</strong></em></a> tutorials.</p>
<p><em>Note: to let selected people register to a session that is not yet public, share its secret link (see <a href="https://larpmanager.com/tutorials/registrations/#secret-registration-link" target="_blank" rel="noopener"><em><strong>Secret registration link</strong></em></a> in the Registrations tutorial).</em></p>
<hr>
<h2>Event features</h2>
<p>To activate features for a specific event, go to <a href="https://larpmanager.com/redirect/event/manage/features/" target="_blank" rel="noopener"><strong>Event &gt; Features</strong></a>:</p>
<p><img src="/static/tutorials/040_advanced-features_02.webp" alt="Event features" width="992" height="576"></p>
<p>The page works like the organization one (see <a href="https://larpmanager.com/tutorials/create-organization/#organization-features" target="_blank" rel="noopener"><em><strong>Create Organization</strong></em></a>). Some features need further settings, in <a href="https://larpmanager.com/redirect/event/manage/config/" target="_blank" rel="noopener"><strong>Event &gt; Configuration</strong></a>.</p>
<hr>
<h2>Event sessions</h2>
<p>An event can have multiple sessions (also called "runs" or "editions"), each with its own dates, registrations, and accounting, while sharing the main event configuration such as features, configurations, roles, tickets, forms, and other settings.</p>
<p>To create a new session of an existing event, go to <a href="https://larpmanager.com/redirect/manage/events/" target="_blank" rel="noopener"><strong>Organization &gt; Events</strong></a> and click on "New session".</p>
<p><img src="/static/tutorials/050_manage-events_04.webp" alt="New session form" width="1260" height="634"></p>
<p>Input the main <strong>Event</strong>, and the specific information of this new session.</p>
<hr>
<h2>Event template</h2>
<p>To simplify event creation, define Event Templates. When creating a new event, you can select a template to automatically import its features, roles, and configuration.</p>
<p>First, activate the <a href="https://larpmanager.com/redirect/manage/features/template/on/" target="_blank" rel="noopener"><strong>Template</strong></a> feature, then go to <a href="https://larpmanager.com/redirect/manage/template/" target="_blank" rel="noopener"><strong>Organization &gt; Template</strong></a>. Click on "New" to create a new one.</p>
<p><img src="/static/tutorials/050_manage-events_05.webp" alt="New template form" width="1260" height="636"></p>
<p>Select the <strong>Name</strong> of the template and the <strong>default features</strong> to activate for events created from it.</p>
<p>For each template, you can also set roles and configuration. Those settings are copied to all events created from it.</p>
<p><img src="/static/tutorials/050_manage-events_06.webp" alt="Templates list" width="992" height="336"></p>
<p><em>Those settings are copied to all events created from it.</em></p>
<hr>
<h2>Campaign</h2>
<p>By default, characters belong to a single event, meaning each event has its own independent set. To share characters across multiple events, enable the <a href="https://larpmanager.com/redirect/manage/features/campaign/on/" target="_blank" rel="noopener"><strong>Campaign</strong></a> feature. In <a href="https://larpmanager.com/redirect/event/manage/event/" target="_blank" rel="noopener"><strong>Event &gt; Event</strong></a>, there is a new field:</p>
<p><img src="/static/tutorials/050_manage-events_07.webp" alt="Parent campaign field" width="1260" height="137"></p>
<p>Here you can select a <strong>Campaign</strong>, i.e. a previous event that is used to link the new event. Events linked to the same Campaign will use the same character pool: any changes made to characters are reflected across all connected events. By designating one initial event and assigning it as the parent for subsequent events, you establish a Campaign structure with shared characters.</p>
<p><em>Note: If no other events exist, the Campaign field is not displayed.</em></p>
<p><em>Note: The events in the Campaign will also share features, and configurations. They will have different dates, locations, tickets, and options in the registration form.</em></p>
<hr>
<h2>Online events</h2>
<p><em>For events held online, where participants do not need to be members to attend.</em> Activate the <a href="https://larpmanager.com/redirect/event/manage/features/laog/on/" target="_blank" rel="noopener"><strong>LAOG</strong></a> feature on the event: the annual membership fee is not required, nor added to the registration fee, for that event.</p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/event-roles/" target="_blank" rel="noopener"><em><strong>Event Roles</strong></em></a>, <a href="https://larpmanager.com/tutorials/event-appearance/" target="_blank" rel="noopener"><em><strong>Event Appearance</strong></em></a>, <a href="https://larpmanager.com/tutorials/registrations/" target="_blank" rel="noopener"><em><strong>Registrations</strong></em></a>, <a href="https://larpmanager.com/tutorials/manage-ticket/" target="_blank" rel="noopener"><em><strong>Registration Ticket</strong></em></a></em></p>', 50);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (6, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Event Roles', 'event-roles', '<p>Event roles let you assign management permissions to collaborators for a specific event, without giving them access to the whole organization. This tutorial mirrors the organization roles system but scoped to a single event.</p>
<hr>
<h2>Event roles</h2>
<p>To manage roles and grant permissions to other users on the event''s functions, go to <a href="https://larpmanager.com/redirect/event/manage/roles/" target="_blank" rel="noopener"><strong>Event &gt; Roles</strong></a>.</p>
<p>A role named <strong>"Organizer"</strong> is automatically created and assigned to the user who created the event. By default, this role has all permissions.</p>
<p><img src="/static/tutorials/070_event-roles_01.webp" alt="Event roles" width="992" height="336"></p>
<p><em>(Note: You can only add users to a role if they have granted permission to share their data with your organization. If the organization is newly created, the list is empty. You can invite them to the role by clicking the envelope icon)</em></p>
<p>You can add users to an existing role by clicking the edit icon, or create a new role by clicking "Add new".</p>
<p>(<em>Note: A user can be assigned to multiple roles. Their permissions are the combined total of all assigned roles)</em></p>
<p><img src="/static/tutorials/070_event-roles_02.webp" alt="New event role" width="1260" height="571"></p>
<p>Enter the role name in "<strong>Name</strong>", select the users to assign in "<strong>Members</strong>", and check the management pages they should have access to.</p>
<p><em>Note: Additional permissions will become available as you activate new features.</em></p>
<hr>
<h2>Inviting new users</h2>
<p>To add someone who is not yet in the list, click the envelope icon on the role row and enter their email address. They receive an email with a link to accept the invitation; once they log in (or create an account) with that email address and agree to share their data with your organization, they are added to the role.</p>
<p>Pending invitations are shown under the role, until they are accepted.</p>
<p><em>Note: an invitation can be used only once, only by the email address it was sent to, and expires after some time.</em></p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/organization-roles/" target="_blank" rel="noopener"><em><strong>Organization Roles</strong></em></a>, <a href="https://larpmanager.com/tutorials/manage-events/" target="_blank" rel="noopener"><em><strong>Manage Events</strong></em></a></em></p>', 70);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (7, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Event Appearance', 'event-appearance', '<p>Each event can have its own visual identity, independent of the organization-wide settings. This section lets you set a cover image, background, fonts, and colors specific to that event.</p>
<h2>Event appearance</h2>
<p>To customize the appearance of an event, go to <a href="https://larpmanager.com/redirect/event/manage/appearance/" target="_blank" rel="noopener"><strong>Event &gt; Appearance</strong></a>.</p>
<p><img src="/static/tutorials/080_event-appearance_01.webp" alt="Event appearance" width="992" height="638"></p>
<p>Input the following data:</p>
<ul>
<li><strong>Cover image</strong>: An image displayed on the Organization homepage as the event''s cover.</li>
<li><strong>Custom Title Font</strong>: A font file (TTF or OTF) used for all page titles.</li>
</ul>
<p>If you select Halo (custom theme), additionally you can input:</p>
<ul>
<li><strong>Background Image</strong>: An image applied as a CSS <code>background-cover</code> on all event pages. Use an image with minimal detail and low color variation. Any size or format is accepted.</li>
<li><strong>Text Color</strong>: The color used for all text. Ensure good contrast with the background image.</li>
<li><strong>Background Color</strong>: The background color for text blocks. Ensure good contrast with both the text and background image.</li>
<li><strong>Link Color</strong>: The color used for all hyperlinks.</li>
<li><strong>Event CSS</strong>: Custom CSS code for the event. Contact support if you need the HTML structure for reference.</li>
</ul>
<p>These customizations apply to all pages of the Event and override any Organization-level customizations.</p>
<hr>
<h2>Customize texts</h2>
<p>You can also customize the texts that are used by LarpManager. To manage them, go to <a href="https://larpmanager.com/redirect/event/manage/texts/" target="_blank" rel="noopener"><strong>Event &gt; Texts</strong></a>.</p>
<p>You can edit an existing one, or add a new one by clicking on "Add new".</p>
<p><img src="/static/tutorials/080_event-appearance_02.webp" alt="New event text" width="1260" height="592"></p>
<p>Input the following data:</p>
<ul>
<li><strong>Text</strong>: The custom text content.</li>
<li><strong>Type</strong>: The text type.</li>
<li><strong>Language</strong>: The language in which the text is shown, based on the user''s profile setting.</li>
<li><strong>Default</strong>: Whether this version should be shown when no text exists for the user''s selected language.</li>
</ul>
<hr>
<p><em>Only one version per language is allowed for each text type.</em></p>
<p><em>Only one version can be set as default for each text type.</em></p>
<p><em>Note: Additional text types will become available as you activate new features.</em></p>
<hr>
<h2>Customize navigation</h2>
<p>You can customize the navigation buttons available to participants for the event by going to <a href="https://larpmanager.com/redirect/event/manage/buttons/" target="_blank" rel="noopener"><strong>Event &gt; Navigation</strong></a>.</p>
<p>You can edit an existing one, or add a new one clicking on "New".</p>
<p><img src="/static/tutorials/080_event-appearance_03.webp" alt="New navigation button" width="1260" height="342"></p>
<p>Input the following data:</p>
<ul>
<li><strong>Name:</strong> the name that will appear on the navigation bar;</li>
<li><strong>Tooltip:</strong> the text that will appear as the user hovers on the button;</li>
<li><strong>Link:</strong> the link where the button will redirect the user once pressed;</li>
<li><strong>Icon:</strong> the icon that is shown on the menu.</li>
</ul>
<p>Here''s an example:</p>
<p><img src="/static/tutorials/080_event-appearance_04.webp" alt="Navigation button in the event menu" width="271" height="200"></p>
<hr>
<h2>Customize gallery</h2>
<p>If the <a href="https://larpmanager.com/redirect/event/manage/features/character/on/" target="_blank" rel="noopener"><strong>Characters</strong></a> feature is enabled, a "Gallery" tab becomes available in the event, showing all registered participants along with their associated characters. In <a href="https://larpmanager.com/redirect/event/manage/config/gallery/" target="_blank" rel="noopener"><strong>Event &gt; Configuration &gt; Gallery</strong></a>, you can customize its visibility settings:</p>
<p><img src="/static/tutorials/080_event-appearance_05.webp" alt="Gallery configuration" width="983" height="482"></p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/organization-appearance/" target="_blank" rel="noopener"><em><strong>Organization Appearance</strong></em></a>, <a href="https://larpmanager.com/tutorials/manage-events/" target="_blank" rel="noopener"><em><strong>Manage Events</strong></em></a>, <a href="https://larpmanager.com/tutorials/characters/" target="_blank" rel="noopener"><em><strong>Characters</strong></em></a></em></p>', 80);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (8, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Promotion', 'promotion', '<p>To promote your events, you can automatically export your event information to Larp aggregators:</p>
<ul>
<li><a href="https://www.larpdatabase.com/" target="_blank" rel="noopener"><strong>LarpDatabase</strong></a> (ILDB): An international archive and search engine dedicated to Larp culture. The database contains organizations, events, authors, participants and many others to map and value the culture of LARP.</li>
<li><a href="https://larp-radar.com/" target="_blank" rel="noopener"><strong>LarpRadar</strong></a>: An event discovery platform dedicated to LARPs, featuring an interactive map and a detailed calendar. It allows participants to discover events nearby, connect with other participants, and access community reviews.</li>
</ul>
<hr>
<h2>Configuration</h2>
<p>As a first step, enable the <a href="https://larpmanager.com/redirect/manage/features/publisher/on/" target="_blank" rel="noopener"><strong>Promotion</strong></a> feature.</p>
<p>In <a href="https://larpmanager.com/redirect/manage/config/publication/" target="_blank" rel="noopener"><strong>Organization &gt; Configuration &gt; Promotion</strong></a>, configure the following values:</p>
<p><img src="/static/tutorials/085_promotion_01.webp" alt="Promotion configuration" width="983" height="509"></p>
<ul>
<li><strong>Publish staff:</strong> If checked, the list of staff members in each event role is shared as well;</li>
<li><strong>Publish players</strong>: If checked, the list of participants with their character is shared as well (the nickname is used, if set, to protect folk''s identities);</li>
<li><strong>ILDB - API key</strong>: Insert the token generated on ILDB: go to "Change profile" / "Create API Token". Make sure to mark all permissions.</li>
<li><strong>ILDB - Team ID</strong>: Insert the ID of your team / organization on ILDB. Can be found by looking at the url when accessing "Your organization", as the number after "https://www.larpdatabase.com/teams/".</li>
</ul>
<hr>
<h2>Event data</h2>
<p>In <a href="https://larpmanager.com/redirect/event/manage/promotion/" target="_blank" rel="noopener"><strong>Event &gt; Promotion</strong></a>, you can enter the information about your event to share:</p>
<p><img src="/static/tutorials/085_promotion_02.webp" alt="Event promotion data" width="992" height="616"></p>
<p>When you press "Confirm", the data is automatically updated and shared.</p>
<hr>
<h2>ILDB</h2>
<p>On LarpDatabase.com (ILDB), the event is created as <em>draft.</em> You can then review them and confirm their publication.</p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/manage-events/" target="_blank" rel="noopener"><em><strong>Manage Events</strong></em></a>, <a href="https://larpmanager.com/tutorials/event-appearance/" target="_blank" rel="noopener"><em><strong>Event Appearance</strong></em></a></em></p>', 85);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (9, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Registrations', 'registrations', '<p><a href="https://larpmanager.com/redirect/event/manage/registrations/" target="_blank" rel="noopener"><strong>Event &gt; Registrations</strong></a> is your central hub for tracking who has signed up for an event. From here you can review registration status, read registration question answers, manage payments, and handle cancellations.</p>
<h2>Manage registrations</h2>
<p>To view all participant registrations, head over to <a href="https://larpmanager.com/redirect/event/manage/registrations/" target="_blank" rel="noopener"><strong>Event &gt; Registrations</strong></a>.</p>
<p><img src="/static/tutorials/090_registrations_01.webp" alt="Registrations list" width="992" height="581"></p>
<hr>
<p>If you have defined registration questions, a button for each will appear under "Registration Questions". Clicking on it will display the answer submitted by each signed-up participant.</p>
<hr>
<p>By clicking on "Accounting", you can view a detailed breakdown of each registration''s financial status, including amount owed, amount paid, total registration fee, portion from the ticket, and portion from selected options.</p>
<hr>
<p>By clicking the edit icon, you can update the data for each registration. To add a new registration, click "New".</p>
<p>If the <a href="https://larpmanager.com/redirect/event/manage/features/character/on/" target="_blank" rel="noopener"><strong>Characters</strong></a> feature is active (see the <a href="https://larpmanager.com/tutorials/characters/" target="_blank" rel="noopener"><em><strong>Characters</strong></em></a> tutorial), you can assign a character by entering its name in the Character field.</p>
<p><img src="/static/tutorials/090_registrations_02.webp" alt="Registration with its character" width="1260" height="284"></p>
<hr>
<h2>Cancellations</h2>
<p>To cancel a registration from <a href="https://larpmanager.com/redirect/event/manage/registrations/" target="_blank" rel="noopener"><strong>Event &gt; Registrations</strong></a>, click the "Delete" icon. Participants will find the link to perform this action on their registration page.</p>
<p>You can manage the cancelled registrations in <a href="https://larpmanager.com/redirect/event/manage/cancellations/" target="_blank" rel="noopener"><strong>Event &gt; Cancellations</strong></a>:</p>
<p><img src="/static/tutorials/090_registrations_03.webp" alt="Cancelled registrations" width="992" height="250"></p>
<hr>
<h2>Additional tickets</h2>
<p>To allow participants to register tickets in addition to theirs, activate the <a href="https://larpmanager.com/redirect/event/manage/features/additional_tickets/on/" target="_blank" rel="noopener"><strong>Additional tickets</strong></a> feature.</p>
<p>On the registration page, a new field, <strong>Additional</strong>, is added, where participants choose how many extra tickets to reserve.</p>

<p>The additional tickets reserved are counted upon the maximum allowed ones, and if the ticket has a price, they are added to the participant''s registration fee.</p>
<hr>
<h2>Pre-registration</h2>
<p>To allow participants to pre-register to events of their interest, activate the <a href="https://larpmanager.com/redirect/manage/features/pre_register/on/" target="_blank" rel="noopener"><strong>Pre-registration</strong></a> feature.</p>
<p>Then, for the events that you want to have the pre-registration active, go to <a href="https://larpmanager.com/redirect/event/manage/event/" target="_blank" rel="noopener"><strong>Event &gt; Event</strong></a> and you find a new value for the Registration Status:</p>
<p><img src="/static/tutorials/090_registrations_05.webp" alt="Registration status set to pre-registration" width="1260" height="575"></p>
<p>Then in <a href="https://larpmanager.com/redirect/event/manage/pre_registrations/" target="_blank" rel="noopener"><strong>Event &gt; Pre-Registrations</strong></a> you find the total list of pre-registrations, and the link to provide to participants to perform the pre-registration.</p>
<hr>
<h2>Secret registration link</h2>
<p>If you wish to allow selected participants to sign up even when registrations are not publicly open, activate the <a href="https://larpmanager.com/redirect/event/manage/features/registration_secret/on/" target="_blank" rel="noopener"><strong>Secret link</strong></a> feature.</p>
<p>In <a href="https://larpmanager.com/redirect/event/manage/event/" target="_blank" rel="noopener"><strong>Event &gt; Event</strong></a>, you find a new field, <strong>Secret registration code</strong>.</p>

<p>The field is pre-filled with a randomly generated code; if you wish you can insert another code (only english letters and digits allowed, no spaces or symbols).</p>
<p>Finally, copy the link to share with the participants from <a href="https://larpmanager.com/redirect/event/manage/" target="_blank" rel="noopener"><strong>Event &gt; Dashboard</strong></a>.</p>
<p><img src="/static/tutorials/090_registrations_07.webp" alt="Secret registration link in the dashboard" width="325" height="189"></p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/manage-ticket/" target="_blank" rel="noopener"><em><strong>Registration Ticket</strong></em></a>, <a href="https://larpmanager.com/tutorials/registration-form/" target="_blank" rel="noopener"><em><strong>Registration Form</strong></em></a>, <a href="https://larpmanager.com/tutorials/registration-accounting/" target="_blank" rel="noopener"><em><strong>Registration Accounting</strong></em></a>, <a href="https://larpmanager.com/tutorials/checkin/" target="_blank" rel="noopener"><em><strong>Check-in</strong></em></a></em></p>', 90);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (10, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Registration Ticket', 'manage-ticket', '<p>Tickets define the participation tiers available for an event: each with its own name, price, and maximum number of spots. This tutorial explains how to create tickets and control when and how participants can select them.</p>
<h2>Manage tickets</h2>
<p>To manage the event''s registration tickets, go to <a href="https://larpmanager.com/redirect/event/manage/tickets/" target="_blank" rel="noopener"><strong>Event &gt; Tickets</strong></a>. Click on "New" to add a new ticket:</p>
<p><img src="/static/tutorials/100_manage-ticket_01.webp" alt="New ticket form" width="1260" height="716"></p>
<p>Input the following data:</p>
<ul>
<li><strong>Name:</strong> the name of the ticket;</li>
<li><strong>Details:</strong> a short description of the ticket;</li>
<li><strong>Price:</strong> the price of the ticket (shown in the currency defined in the Organization settings);</li>
<li><strong>Total availability:</strong> the maximum number of registrations available with this ticket;</li>
<li><strong>Visible:</strong> if the ticket is visible (and selectable) by the participants.</li>
</ul>
<hr>
<p>You can select different "tier" of tickets. To activate them, go to <a href="https://larpmanager.com/redirect/event/manage/config/tickets/" target="_blank" rel="noopener"><strong>Event &gt; Configuration &gt; Tickets</strong></a>.</p>
<p><img src="/static/tutorials/100_manage-ticket_02.webp" alt="Tickets configuration" width="983" height="579"></p>
<p>The ticket edit form has a new field, <strong>Tier</strong>:</p>
<p><img src="/static/tutorials/100_manage-ticket_03.webp" alt="Ticket tiers" width="1260" height="415"></p>
<p><em>Note: "<strong>Standard</strong>" is the default ticket tier for users / participants.</em> </p>
<p><em>Note: The maximum number of available spots defined in the event does not include Staff tickets.</em></p>
<hr>
<p>Here''s an example of the selection for the participants:</p>
<p><img src="/static/tutorials/100_manage-ticket_04.webp" alt="Ticket selection for participants" width="947" height="230"></p>
<hr>
<h2>Patron and reduced</h2>
<p>With this feature, you can enable <em>Reduced</em> tickets, where availability is dynamically based on the number of <em>Patron</em> tickets previously selected by participants. First, activate the <a href="https://larpmanager.com/redirect/event/manage/features/reduced/on/" target="_blank" rel="noopener"><strong>Patron and Reduced</strong></a> feature.</p>
<p>In <strong>Tier</strong> you find the two new types, <strong>Reduced</strong> and <strong>Patron</strong>.</p>

<p>In <a href="https://larpmanager.com/redirect/event/manage/config/reduced/" target="_blank" rel="noopener"><strong>Event &gt; Configuration &gt; Patron / Reduced</strong></a>, you can configure the ratio between the two tickets:</p>
<p><img src="/static/tutorials/100_manage-ticket_06.webp" alt="Patron and reduced configuration" width="983" height="247"></p>
<p>At any moment, LarpManager calculates the total number of available Reduced tickets by multiplying the number of purchased Patron tickets by the defined ratio, dividing the result by 10, and rounding down.</p>
<hr>
<h2>Reserve</h2>
<p>With this feature, you can enable "light" tickets, intended for a lighter experience, that works also as a "reserve" for the primary characters, if there is a dropout.</p>
<p>To use it, first activate the <a href="https://larpmanager.com/redirect/event/manage/features/filler/on/" target="_blank" rel="noopener"><strong>Reserve</strong></a> feature, then in <strong>Tier</strong> the new type <strong>Reserve</strong> is available.</p>

<p>Also in <a href="https://larpmanager.com/redirect/event/manage/event/" target="_blank" rel="noopener"><strong>Event &gt; Event</strong></a> you can set the total number of reserve spots in the <strong>Maximum reserves</strong> field.</p>

<p>When the number of registrations is below the <strong>Maximum participants,</strong> the <em>Reserve</em> ticket is not shown. Once the maximum is reached, all ticket types are disabled except for the <em>Reserve</em> tickets. When <em>Reserve</em> registrations also reach the defined <strong>Maximum reserves</strong>, registrations are closed.</p>
<hr>
<h2>Waiting list</h2>
<p>With this feature you can have "waiting list" tickets. Once a regular ticket spot is available due to dropout, they can be upgraded. First, activate the <a href="https://larpmanager.com/redirect/event/manage/features/waiting/on/" target="_blank" rel="noopener"><strong>Waiting list</strong></a> feature.</p>
<p>In <strong>Tier</strong> the new type <strong>Waiting</strong> is available.</p>

<p>Also in <a href="https://larpmanager.com/redirect/event/manage/event/" target="_blank" rel="noopener"><strong>Event &gt; Event</strong></a> you can set the total number of waiting list spots in the <strong>Maximum waiting list</strong> field.</p>

<p>When the number of registrations is below the <strong>Maximum participants</strong>, the <em>Waiting ticket</em> is not shown. Once the maximum is reached, all ticket types are disabled except for the <em>Waiting tickets</em>. When Waiting registrations also reach the <strong>Maximum Waiting List</strong>, registrations are closed.</p>
<hr>
<p>Note: If both <strong>Reserve</strong> and <strong>Waiting</strong> tickets are activated, the order is as follows:</p>
<p><em>Up to the Maximum participants:</em> all tickets are available, except Reserve and Waiting.<br><em>Between Participants and Reserve limits:</em> only Reserve tickets are available.<br><em>Between Reserve and Waiting limits:</em> only Waiting tickets are available.</p>
<hr>
<h2>Lottery</h2>
<p>With this feature you can have a "lottery" system, where participants first sign up to participate in the lottery, and some of them are randomly selected to upgrade to a full ticket. To use it, activate the <a href="https://larpmanager.com/redirect/event/manage/features/lottery/on/" target="_blank" rel="noopener"><strong>Lottery</strong></a> feature.</p>
<p>In <strong>Tier</strong> the new type <strong>Lottery</strong> is available.</p>

<p>In <a href="https://larpmanager.com/redirect/event/manage/config/lottery/" target="_blank" rel="noopener"><strong>Event &gt; Configuration &gt; Lottery</strong></a>, you can configure the number of tickets to draw, and the regular ticket to upgrade to:</p>
<p><img src="/static/tutorials/100_manage-ticket_12.webp" alt="Lottery configuration" width="983" height="319"></p>
<p>In <a href="https://larpmanager.com/redirect/event/manage/lottery/" target="_blank" rel="noopener"><strong>Event &gt; Lottery</strong></a>, you can perform the random selection. On first access, the extraction is executed and shown for confirmation. Upon confirmation, the selected tickets are upgraded.</p>
<hr>
<h2>New player tickets</h2>
<p><em>A ticket reserved to people who have never attended an event of your organization, for example at a reduced price.</em> To use it, activate the <a href="https://larpmanager.com/redirect/event/manage/features/new_player/on/" target="_blank" rel="noopener"><strong>New player</strong></a> feature.</p>
<p>When creating a ticket, a new tier, <strong>New player</strong>, is available. The ticket is shown only to users without previous registrations to your events; registrations as waiting list, staff or NPC do not count.</p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/registrations/" target="_blank" rel="noopener"><em><strong>Registrations</strong></em></a>, <a href="https://larpmanager.com/tutorials/registration-accounting/" target="_blank" rel="noopener"><em><strong>Registration Accounting</strong></em></a>, <a href="https://larpmanager.com/tutorials/casting/" target="_blank" rel="noopener"><em><strong>Casting</strong></em></a></em></p>', 100);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (11, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Registration Form', 'registration-form', '<p>Registration questions let you collect custom information from participants at registration time: multiple and single choice answers, long and shor text, and more. This tutorial shows how to create, configure, and order them.</p>
<h2>Manage questions</h2>
<p>To manage the event''s registration questions, go to <a href="https://larpmanager.com/redirect/event/manage/form/" target="_blank" rel="noopener"><strong>Event &gt; Form</strong></a>.</p>
<p>Those are questions that the participants can answer during registration.</p>
<p>You can edit the existing questions, or you can add a new one by clicking on "New".</p>
<p><img src="/static/tutorials/110_registration-form_01.webp" alt="New registration question" width="1260" height="604"></p>
<p>Input the following data:</p>
<ul>
<li><strong>Type:</strong> can be <em>Single choice</em>, <em>Multiple choice</em>, <em>Single-line text</em><em>, Multi-line text</em>, <em>Advanced text editor</em> (rendered as a WYSIWYG editor), <em>Likert scale, Ranking</em>;</li>
<li><strong>Name:</strong> the label that is shown for the question;</li>
<li><strong>Description:</strong> the text that is shown as help text under the question;</li>
<li><strong>Status:</strong> can be <em>Optional</em> (active but not required), <em>Mandatory</em> (active and required), <em>Disabled</em> (shown but not editable), <em>Hidden</em> (not shown)<em>.</em></li>
<li><strong>Maximum length:</strong> the maximum length of the text, or the maximum amount of choices.</li>
</ul>
<hr>
<p>Here''s an example of a<em> Single-line text:</em></p>
<p><img src="/static/tutorials/110_registration-form_02.webp" alt="Single-line text question" width="947" height="136"></p>
<hr>
<p>Here''s an example of a <em>Multi-line text:</em></p>
<p><img src="/static/tutorials/110_registration-form_03.webp" alt="Multi-line text question" width="947" height="220"></p>
<p>Here''s an example for Advanced Text Editor (click on "Show" to show it):</p>
<p><img src="/static/tutorials/110_registration-form_04.webp" alt="Advanced text editor question" width="947" height="361"></p>
<p>And here''s an example of the Likert scale:</p>
<p><img src="/static/tutorials/110_registration-form_05.webp" alt="Likert scale question" width="947" height="116"></p>
<p>And here''s an example of Ranking:</p>
<p><img src="/static/tutorials/110_registration-form_06x.webp" alt="Example of a ranking question" width="1393" height="476"></p>
<hr>
<h2>Manage options</h2>
<p>Fo <em>Single choice</em> and <em>Multiple choice</em> you also need to define the options. You find the list of the options, and the link to add a new one, directly when editing the question:</p>
<p><img src="/static/tutorials/110_registration-form_06.webp" alt="Options of a choice question" width="1260" height="322"></p>
<p>Input the following data:</p>
<ul>
<li><strong>Name:</strong> the text that is shown for this option;</li>
<li><strong>Description:</strong> an optional description (shown in the help text of the question);</li>
<li><strong>Price:</strong> the price that this option will add to the registration fee (if 0, it is not shown);</li>
<li><strong>Maximum:</strong> the maximum number of registrations with this option (if 0, there is no limit).</li>
</ul>
<hr>
<p>Here''s an example of <em>Single choice</em> and<em> Multiple choice</em> question:</p>
<p><img src="/static/tutorials/110_registration-form_07.webp" alt="Choice questions" width="947" height="519"></p>
<hr>
<p><em>If you want to reorder either questions or options, hold on the 6-points icon on the left.</em></p>
<hr>
<h2>Sections</h2>
<p>To organize the questions in the registration form in sections, first activate the <a href="https://larpmanager.com/redirect/event/manage/features/reg_que_sections/on/" target="_blank" rel="noopener"><strong>Sections</strong></a> feature.</p>
<p>In <a href="https://larpmanager.com/redirect/event/manage/sections/" target="_blank" rel="noopener"><strong>Event &gt; Sections</strong></a>, you can create the sections:</p>
<p><img src="/static/tutorials/110_registration-form_08.webp" alt="New section" width="1260" height="434"></p>
<p>Then, in the edit form of each question, choose its section in the <strong>Section</strong> field.</p>
<p>In the participant''s registration form, the sections are shown as collapsible parts (by clicking on the header, the section questions are shown or hidden).</p>
<p><img src="/static/tutorials/110_registration-form_10.webp" alt="Registration form section" width="947" height="616"></p>
<hr>
<h2>Additional configurations</h2>
<p>In <a href="https://larpmanager.com/redirect/event/manage/config/registrations/" target="_blank" rel="noopener"><strong>Event &gt; Configuration &gt; Registrations</strong></a>, you can find the following configurations:</p>
<p><img src="/static/tutorials/110_registration-form_11.webp" alt="Registrations configuration" width="983" height="983"></p>
<p>Here''s an explanation:</p>
<ul>
<li><strong>Disable grouping:</strong> By default, registrations are displayed in different tables given their status; when this configuration is enabled, they are instead shown in a single table;</li>
<li><strong>Allowed:</strong> When enabled, each registration question gets a field where you choose which staff members can see the participants'' answers to it.</li>
<li><strong>Hide Not Available:</strong> By default, options that have reached their selection limit appear disabled. If this option is enabled, they are hidden entirely.</li>
<li><strong>Faction Selection:</strong> Adds a "Factions" field to each registration question. If filled, the question is shown only to participants assigned a character from one of the selected factions.</li>
<li><strong>Ticket Selection:</strong> Adds a "Tickets" field to each registration question. If filled, the question is shown only to participants who selected one of the specified ticket types.</li>
<li><strong>Age Selection:</strong> Adds a "Minimum Age" field to each registration question. If set, the question is shown only to participants who meet or exceed the specified age.</li>
<li><strong>Disable cancellation</strong>: If enabled, participants cannot directly cancel their own registration; if they press than button, a request will instead be sent to the organizers, that can manually cancel it.</li>
<li><strong>Approval process:</strong> see next paragraph.</li>
</ul>
<h2>Approval process</h2>
<p>If the configuration is enabled in <a href="https://larpmanager.com/redirect/event/manage/config/registrations/" target="_blank" rel="noopener"><strong>Event &gt; Configuration &gt; Registrations</strong></a>, then participants cannot directly sign up to the event.</p>
<p>On registration page, a new participant will find this instead:</p>
<p><img src="/static/tutorials/110_registration-form_12.webp" alt="Signup request" width="992" height="399"></p>
<p>A new page is available, <a href="https://larpmanager.com/redirect/event/manage/registrations/requests/" target="_blank" rel="noopener"><strong>Event &gt; Requests</strong></a>. Here organizers can review the requests; if one is approved, then that participant is allowed to proceed with the normal registration form.</p>
<p><img src="/static/tutorials/110_registration-form_13.webp" alt="Signup requests to review" width="992" height="250"></p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/registrations/" target="_blank" rel="noopener"><em><strong>Registrations</strong></em></a>, <a href="https://larpmanager.com/tutorials/manage-ticket/" target="_blank" rel="noopener"><em><strong>Registration Ticket</strong></em></a>, <a href="https://larpmanager.com/tutorials/matchmaker/" target="_blank" rel="noopener"><em><strong>Matchmaker</strong></em></a>, <a href="https://larpmanager.com/tutorials/debrief/" target="_blank" rel="noopener"><em><strong>Debrief</strong></em></a></em></p>', 110);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (12, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Registration Accounting', 'registration-accounting', '<p>This tutorial covers the optional financial add-ons for the registration system: pay-what-you-want contributions, fixed installment plans, tokens, credits, and discount codes. Each is an independent feature you can activate selectively.</p>
<h2>Pay what you want</h2>
<p>To allow participant to add a free amount to their registration, activate the <a href="https://larpmanager.com/redirect/event/manage/features/pay_what_you_want/on/" target="_blank" rel="noopener"><strong>Pay what you want</strong></a> feature.</p>
<p>On the registration page, a new field, <strong>Pay what you want</strong>, is added, where participants can enter a free amount.</p>

<p>The indicated amount is added to the participant''s registration fee.</p>
<p>If you wish, you can customize the name and description of the field in <a href="https://larpmanager.com/redirect/event/manage/form/" target="_blank" rel="noopener"><strong>Event &gt; Form</strong></a>.</p>
<hr>
<h2>Fixed instalments</h2>
<p>With this feature, you can define multiple deadlines to split the payment of the registration fee into installments. First, activate the <a href="https://larpmanager.com/redirect/event/manage/features/reg_installments/on/" target="_blank" rel="noopener"><strong>Fixed instalments</strong></a> feature.</p>
<p>Go to <a href="https://larpmanager.com/redirect/event/manage/installments/" target="_blank" rel="noopener"><strong>Event &gt; Fixed instalments</strong></a>, and create a new payment deadline clicking on "New":</p>
<p><img src="/static/tutorials/130_registration-accounting_02.webp" alt="New fixed instalment" width="1260" height="514"></p>
<p>Define the following values:</p>
<ul>
<li><strong>Amount</strong>: The amount to be paid at this deadline. If set to 0 (typically for the final installment), LarpManager will request the remaining balance of the registration fee.</li>
<li><strong>Days Deadline</strong>: Number of days from the moment of registration.</li>
<li><strong>Date Deadline</strong>: A fixed calendar date for the deadline. <em>(Only one between Days Deadline and Date Deadline is allowed and required)</em></li>
<li><strong>Tickets</strong>: List of tickets the deadline applies to (Start typing in the input field to select).</li>
</ul>
<hr>
<p>Notes:</p>
<p><em>Defining both Days Deadline and Date Deadline is not allowed.</em></p>
<p><em>If no installments are defined for a ticket, the default payment deadline is 7 days from registration.</em></p>
<hr>
<h2>Dynamic rates</h2>
<p>With this feature you can divide the payment of a registration fee in dynamic rates (or quotas). First, activate the <a href="https://larpmanager.com/redirect/event/manage/features/reg_quotas/on/" target="_blank" rel="noopener"><strong>Dynamic rates</strong></a> feature.</p>
<p>Go to <a href="https://larpmanager.com/redirect/event/manage/quotas/" target="_blank" rel="noopener"><strong>Event &gt; Dynamic rates</strong></a>, and create a new quota option clicking on "New":</p>
<p>Define the following values:</p>
<ul>
<li><strong>Quotas</strong>: The number of installments into which the payment is divided (e.g., 1 for full payment, 2 for two installments, 3 for three installments, etc.).</li>
<li><strong>Days Available</strong>: The maximum number of days before the event when this option is available for new registrations. Set to 0 to make it always available.</li>
<li><strong>Surcharge</strong>: An optional additional amount applied to this quota option.</li>
</ul><hr>
<p><em>For each quota option, the total registration fee is divided equally by the number of quotas. The first installment is due 7 days after registration. Remaining installments are scheduled by dividing the time between registration and event start by the number of quotas.</em></p>
<p><em>Participants will select their preferred quota option at registration, from those available at that time.</em></p>
<p><img src="/static/tutorials/130_registration-accounting_03.webp" alt="New dynamic rate" width="1260" height="380"></p>
<p>Example: define 3 payment options; quotas 2 and 3 have day limits (to prevent multi-tranche payments for last-minute registrations), and quota 3 includes a surcharge to account for increased accounting workload.</p>
<p><img src="/static/tutorials/130_registration-accounting_04.webp" alt="Dynamic rates list" width="983" height="410"></p>
<p>Assuming a total registration fee of 100 and a registration 60 days before the event:</p>
<ul>
<li><strong>1 quota</strong>: 100 due 7 days after registration</li>
<li><strong>2 quotas</strong>: 50 due 7 days after registration, 50 due 30 days after registration</li>
<li><strong>3 quotas</strong>: 33 due 7 days after registration, 33 due 20 days, 34 due 40 days after registration</li>
</ul>
<hr>
<p><em><strong>Note:</strong> The quota options are applied to to all registrations and tickets.</em> </p>
<p><em>If you wish, you can customize the name and description of the field in <a href="https://larpmanager.com/redirect/event/manage/form/" target="_blank" rel="noopener"><strong>Event &gt; Form</strong></a>.</em> </p>
<hr>
<h2>Registration surcharges</h2>
<p>With this feature, a surcharge is automatically added to a registration if it is created after a defined deadline. First, activate the <a href="https://larpmanager.com/redirect/event/manage/features/reg_surcharges/on/" target="_blank" rel="noopener"><strong>Surcharge</strong></a> feature.</p>
<p>Go to <a href="https://larpmanager.com/redirect/event/manage/surcharges/" target="_blank" rel="noopener"><strong>Event &gt; Surcharges</strong></a>, and create a new surcharge option clicking on "New":</p>
<p><img src="/static/tutorials/130_registration-accounting_05.webp" alt="New surcharge" width="1260" height="259"></p>
<p>Indicate the <strong>Amount</strong> of the surcharge, and the deadline <strong>Date</strong>. The surcharge is added to all registrations created after the deadline.</p>
<hr>
<h2>Discount</h2>
<p>With this feature you can provide discount codes to the participants. First, activate the <a href="https://larpmanager.com/redirect/event/manage/features/discount/on/" target="_blank" rel="noopener"><strong>Discount</strong></a> feature.</p>
<p>Go to <a href="https://larpmanager.com/redirect/event/manage/discounts/" target="_blank" rel="noopener"><strong>Event &gt; Discounts</strong></a>, and create a new discount clicking on "New":</p>
<p><img src="/static/tutorials/130_registration-accounting_06.webp" alt="New discount" width="1260" height="716"></p>
<p>Define the following values:</p>
<ul>
<li><strong>Name</strong>: Internal name of the discount.</li>
<li><strong>Sessions</strong>: Sessions where the discount is active.</li>
<li><strong>Value</strong>: Amount deducted from the total registration fee.</li>
<li><strong>Max redeem</strong>: Maximum number of times this discount can be used.</li>
<li><strong>Code</strong>: Discount code participants must enter (customizable).</li>
<li><strong>Type</strong>: Type of discount - <em>Standard</em> or <em>Play Again</em> (usable only if the participant has already participated in another session of the same event).</li>
<li><strong>Visible</strong>: Whether the discount is visible and usable by participants.</li>
<li><strong>Only reg</strong>: If enabled, the discount can be used only during registration creation, not on later updates.</li>
</ul>
<hr>
<p>A field will appear in the registration form where participants can enter a discount code, which will then be reserved for 15 minutes.</p>
<p><img src="/static/tutorials/130_registration-accounting_07.webp" alt="Discount code field" width="947" height="230"></p>
<hr>
<h2>Gift</h2>
<p>With this feature, participants can reserve registrations, complete payment, and later assign them as gifts to other participants. First, activate the <a href="https://larpmanager.com/redirect/event/manage/features/gift/on/" target="_blank" rel="noopener"><strong>Gift</strong></a> feature.</p>
<p>A new checkbox, <strong>Giftable</strong>, is added to both tickets and registration questions.</p>

<p>Only Tickets and Questions marked as giftable will appear as options in the gift registration form.</p>
<p>Participants will now find a new page, "Gift", in the event menu.</p>
<p><img src="/static/tutorials/130_registration-accounting_09.webp" alt="Gift page" width="992" height="468"></p>
<p>By clicking "Add new", participants can create new registrations. These count toward ticket and option limits, allowing them to be booked. In <a href="https://larpmanager.com/redirect/event/manage/registrations/" target="_blank" rel="noopener"><strong>Event &gt; Registrations</strong></a>, they are marked with the gift icon.</p>

<p>When a gift registration is paid, a special link is generated. Another participant can access the link to claim the registration, provided they do not already have a registration for that session. Once claimed, the registration is no longer marked as "<em>gift</em>".</p>
<hr>
<h2>Bring a friend</h2>
<p><em>Reward participants who bring new people to your events.</em> To use it, activate the <a href="https://larpmanager.com/redirect/event/manage/features/bring_friend/on/" target="_blank" rel="noopener"><strong>Bring a friend</strong></a> feature.</p>
<p>In <a href="https://larpmanager.com/redirect/event/manage/config/bring_friend/" target="_blank" rel="noopener"><strong>Event &gt; Configuration &gt; Bring a friend</strong></a>, set the two discounts:</p>
<p><img src="/static/tutorials/900_sections_01.webp" alt="Bring a friend configuration" width="983" height="320"></p>
<ul>
<li><strong>Referrer Reward Discount</strong>: discount given to the participant whose code was used.</li>
<li><strong>Referred Friend Discount</strong>: discount given to the new participant who registers with the code.</li>
</ul>
<p>After registering, each participant receives by email a personal code to share. A friend enters it in the <strong>Code ''Bring a friend''</strong> field of the registration form, and both get their discount.</p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/payments/" target="_blank" rel="noopener"><em><strong>Payments</strong></em></a>, <a href="https://larpmanager.com/tutorials/accounting/" target="_blank" rel="noopener"><em><strong>Accounting</strong></em></a>, <a href="https://larpmanager.com/tutorials/manage-ticket/" target="_blank" rel="noopener"><em><strong>Registration Ticket</strong></em></a></em></p>', 130);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (13, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Payments', 'payments', '<p>The Payments feature enables online payment collection directly through the platform. When active, registrations with a non-zero fee start in a provisional state and are confirmed only after the first payment. This tutorial covers gateway configuration, payment status management, and refunds.</p>
<h2>Payments</h2>
<p>To receive payments from your participants, activate the <a href="https://larpmanager.com/redirect/manage/features/payment/on/" target="_blank" rel="noopener"><strong>Payments</strong></a> feature.</p>
<hr>
<p><em>Note: When this feature is active, and the participant has a non-zero registration fee, the registration is not immediately confirmed; it is instead provisional, and is confirmed only upon the first payment.</em></p>
<hr>
<p>You now need to configure the payment settings. LarpManager supports multiple payment gateways, each requiring its own specific configuration.</p>
<p>You will now find a new page, <a href="https://larpmanager.com/redirect/manage/methods/" target="_blank" rel="noopener"><strong>Organization &gt; Methods</strong></a>:</p>
<p><img src="/static/tutorials/150_payments_01.webp" alt="Payment methods" width="992" height="359"></p>
<p>Select the gateway you wish to activate. For each activated gateway, new fields will appear to input the required data specific to that gateway. Each gateway has its own set of fields, explained in its section.</p>
<p><img src="/static/tutorials/150_payments_02.webp" alt="Wire transfer settings" width="983" height="702"></p>
<p>For Fee, enter the percentage of the amount that is going to be witheld by the gateway. Enter the value as a number without the percentage symbol: for example, for a <em>1.5% fee</em>, input: <strong>1.5.</strong></p>
<hr>
<p>After registration, participants are automatically redirected to a page where they can select a payment method. Both the participant''s and the event''s accounting are updated automatically.</p>
<p>Note: Wire payment requires participants to upload a proof of payment, which must then be manually approved by the event staff from the pending payments list at the top of <a href="https://larpmanager.com/redirect/event/manage/payments/" target="_blank" rel="noopener"><strong>Event &gt; Payments</strong></a>.</p>
<hr>
<p>It will then be possible to review all received payments either in <a href="https://larpmanager.com/redirect/manage/payments/" target="_blank" rel="noopener"><strong>Organization &gt; Payments</strong></a>, or in <a href="https://larpmanager.com/redirect/event/manage/payments/" target="_blank" rel="noopener"><strong>Event &gt; Payments</strong></a>.</p>
<hr>
<h2>Additional configuration</h2>
<p>As an additional configuration, in <a href="https://larpmanager.com/redirect/manage/config/payment/" target="_blank" rel="noopener"><strong>Organization &gt; Configuration &gt; Payments</strong></a> you find:</p>
<p><img src="/static/tutorials/150_payments_03.webp" alt="Organization payment configuration" width="983" height="483"></p>
<ul>
<li><strong>Charge transaction fees to participant:</strong> If checked, the fees witheld by the payment gateway are added to the user. If the fee is 3%, and the total registration fee is 150&euro;, the user is asked to pay <strong>154.64&euro;</strong> (as that is the amount that minus 3% gives 150&euro;).</li>
<li><strong>Disable amount change:</strong> By default, participants can edit the payment amount (e.g., split &euro;100 into two &euro;50 payments). Enabling this option disables that flexibility.</li>
<li><strong>Unique Code:</strong> A unique code is added automatically to each registration''s payment description. For example, "Registration fee of Elena Ricci for Test Event" becomes "Registration fee of Elena Ricci for Test Event - hR04SlbZOPXFzFx". This code helps with automatic payment validation by uniquely identifying the registration.</li>
<li><strong>Require receipt for manual payments:</strong> If selected, when confirming the payment done with a wire payment, the user is also asked to upload a payment receipt.</li>
</ul>
<hr>
<p>And also, for each event, in <a href="https://larpmanager.com/redirect/event/manage/config/payment/" target="_blank" rel="noopener"><strong>Event &gt; Configuration &gt; Payments</strong></a> you find:</p>
<p><img src="/static/tutorials/150_payments_04.webp" alt="Event payment configuration" width="983" height="508"></p>
<ul>
<li><strong>Payment reminder:</strong> If fixed or dynamic rates are selected, LarpManager will treat all payments with a deadline earlier than the specified value as urgent and notify the user accordingly.</li>
<li><strong>Payment reference:</strong> By default, the payment justification is formatted like "<em>Registration fee of Elena Ricci for Test Event</em>". You can customize this by entering a template string; for example, inputting "Thanks {player_name} for your help!" will result in "<em>Thanks Elena Ricci for your help!</em>".</li>
<li><strong>Disable provisional registrations:</strong> By default, registrations are marked as "provisional" unless a payment is performed. If this option is enabled, no registration are marked provisional, and are immediately confirmed.</li>
</ul>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/registration-accounting/" target="_blank" rel="noopener"><em><strong>Registration Accounting</strong></em></a>, <a href="https://larpmanager.com/tutorials/accounting/" target="_blank" rel="noopener"><em><strong>Accounting</strong></em></a>, <a href="https://larpmanager.com/tutorials/membership/" target="_blank" rel="noopener"><em><strong>Membership</strong></em></a></em></p>', 150);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (14, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Characters', 'characters', '<p>Characters are the in-game personas that participants embody at your event. This tutorial covers how staff creates and manages them, how the character numbering and cross-reference system works, and how to control what participants can see.</p>
<h2>Manage characters</h2>
<p>To manage the event''s characters, first activate the <a href="https://larpmanager.com/redirect/event/manage/features/character/on/" target="_blank" rel="noopener"><strong>Characters</strong></a> feature, then go to <a href="https://larpmanager.com/redirect/event/manage/characters/" target="_blank" rel="noopener"><strong>Event &gt; Characters</strong></a>.</p>
<p>You can edit the existing characters, or you can add a new one by clicking on "Add new".</p>
<p><img src="/static/tutorials/170_characters_01.webp" alt="New character form" width="1260" height="384"></p>
<p>Input the following data:</p>
<ul>
<li><strong>Name:</strong> the name of the character;</li>
<li><strong>Presentation:</strong> a short description of the character, visible to all participants;</li>
<li><strong>Text:</strong> a long description of the character, visible only to the participant to which the character is assigned.</li>
</ul>
<p>(For <em>Presentation</em> and <em>Text</em> click on "Show" to display the input field).</p>
<hr>
<p>To define additional fields see the <a href="https://larpmanager.com/tutorials/character-form/" target="_blank" rel="noopener"><em><strong>Character Sheet</strong></em></a> tutorial.</p>
<hr>
<h2>Gallery and search</h2>
<p><em>Participants browse the event''s characters from two pages, linked in the event navigation bar: <strong>Gallery</strong> and <strong>Search</strong>.</em></p>
<ul>
<li><strong>Gallery</strong> shows the character portraits, each linking to the character''s page. Characters are grouped under their primary faction (see the <a href="https://larpmanager.com/tutorials/factions/" target="_blank" rel="noopener"><em><strong>Factions</strong></em></a> tutorial). At the bottom, under <strong>Registrants</strong>, it lists the participants that do not have a character yet (staff, NPC, collaborator, seller and waiting list tickets are excluded, as are provisional registrations).</li>
<li><strong>Search</strong> lets participants filter the characters and read their public information in one page. The buttons at the top open the filters:</li>
</ul><ul>
<li><strong>Instructions</strong>: how the filters work;</li>
<li><strong>Search</strong>: free text, matched on the character''s number, name, presentation, participant and groups;</li>
<li><strong>Status</strong>: show only characters already assigned to a participant;</li>
<li><strong>Factions</strong>: filter by faction (shown when the event has more than one faction);</li>
<li>one button for each character field with visibility <strong>Searchable</strong>, to filter by its options;</li>
<li><strong>Characters link</strong>: the list of all character names, each linking to its page.</li>
</ul>
<p>Click a filter value once to <em>include</em> it (characters in at least one included value are shown), and a second time to <em>exclude</em> it (characters in any excluded value are hidden).</p>
<p><img src="/static/tutorials/170_characters_17.webp" alt="Search with a faction filter" width="983" height="716"></p>
<hr>
<p>To make a character field available as a Search filter, set its <strong>Visibility</strong> to "Searchable" in <a href="https://larpmanager.com/redirect/event/manage/writing/form/" target="_blank" rel="noopener"><strong>Event &gt; Sheet</strong></a> (see the <a href="https://larpmanager.com/tutorials/character-form/" target="_blank" rel="noopener"><em><strong>Character Sheet</strong></em></a> tutorial).</p>
<p>To add an introduction at the top of the Search page, go to <a href="https://larpmanager.com/redirect/event/manage/texts/" target="_blank" rel="noopener"><strong>Event &gt; Texts</strong></a>, click "New" and select the type "Search".</p>
<hr>
<p>In <a href="https://larpmanager.com/redirect/event/manage/config/gallery/" target="_blank" rel="noopener"><strong>Event &gt; Configuration &gt; Gallery</strong></a> you can limit who sees the characters:</p>
<ul>
<li><strong>Require login</strong>: characters are hidden from visitors that are not logged in.</li>
<li><strong>Require registration</strong>: characters are hidden from users not registered to the event.</li>
<li><strong>Hide unassigned characters</strong>: characters without a participant are not shown in the gallery.</li>
<li><strong>Hide participants without a character</strong>: the Registrants list is not shown.</li>
</ul>
<p><em>Note: which character fields are shown in both pages depends on the visibility set in</em> <a href="https://larpmanager.com/redirect/event/manage/event/" target="_blank" rel="noopener"><strong>Event &gt; Event</strong></a><em>, see</em> <a href="https://larpmanager.com/tutorials/characters/#characters-configuration" target="_blank" rel="noopener"><em><strong>Characters configuration</strong></em></a><em> below.</em></p>
<hr>
<h2>Characters configuration</h2>
<p>In <a href="https://larpmanager.com/redirect/event/manage/config/writing/" target="_blank" rel="noopener"><strong>Event &gt; Configuration &gt; Characters</strong></a> you find those options:</p>
<p><img src="/static/tutorials/170_characters_02.webp" alt="Characters configuration" width="983" height="536"></p>
<ul>
<li><strong>Field visibility:</strong> If you want more fine-grained control over which fields are visible to the participant at each moment, click this option and then see the next section.</li>
<li><strong>Played characters:</strong> You can select the number of character the participants will play in the game (default 1).</li>
<li><strong>Disable Character Finder:</strong> If you don''t want the character finder, you can disable it here.</li>
<li><strong>Replacing Names</strong>: In the character fields, existing character names are automatically replaced by references like #&lt;number&gt;.</li>
<li><strong>Paste as Text</strong>: In the WYSIWYG editor, pasted content is stripped of formatting.</li>
<li><strong>Disable Auto Save</strong>: By default, writing elements are saved automatically while you edit them, so no work is lost, and you are warned if two users edit the same element at the same time. Enable this option to turn both off.</li>
<li><strong>External Access:</strong> If you want to allow any user to access the complete sheet of a character, enable this option. In the characters'' page, a key icon will appear next to the character''s name, with the link to share to allow to do so.</li>
<li><strong>Unimportant:</strong> Activates a special tracking of plots or relationships that are less important to the character.</li>
<li><strong>Check:</strong> If enabled, a new page is available in the event dashboard, allowing to check consistency of references between characters (see <a href="https://larpmanager.com/tutorials/character-references/#checking-references" target="_blank" rel="noopener"><em><strong>Checking references</strong></em></a> in the Character References tutorial below).</li>
<li><strong>Reading:</strong> If enabled, a new special page is available in the Event''s management, allowing staff to access characters with read-only access.</li>
</ul>
<hr>
<h2>Field visibility</h2>
<p>If in your event the character''s sheet are written by the staff, with this configuration you can control exactly what participants are able to see at any moment.</p>
<p>You can do it in <a href="https://larpmanager.com/redirect/event/manage/event/" target="_blank" rel="noopener"><strong>Event &gt; Event</strong></a>:</p>
<p><img src="/static/tutorials/170_characters_03.webp" alt="Character fields visible to players" width="1260" height="164"></p>
<p>The selected elements are shown to participants only if checked.</p>
<p><em>(Characters are visible only if Name is selected)</em></p>
<h2>References and PDF</h2>
<p>To mention other characters by their number in any text, and check that these references are consistent, see the <a href="https://larpmanager.com/tutorials/character-references/" target="_blank" rel="noopener"><em><strong>Character References</strong></em></a> tutorial.</p>
<p>To print character sheets and the character gallery as PDF, with your own layout, see the <a href="https://larpmanager.com/tutorials/pdf-generation/" target="_blank" rel="noopener"><em><strong>PDF Generation</strong></em></a> tutorial.</p>
<hr>
<h2>Single field edit</h2>
<p>You can edit a character''s field directly by double-clicking on it. This opens a popup allowing you to edit the field without opening the full character editor.</p>
<p><img src="/static/tutorials/170_characters_05.webp" alt="Popup to edit a single field" width="1901" height="985"></p>
<hr>
<h2>Relationships</h2>
<p>Allows staff to define inter-character relationships. To use it, activate the <a href="https://larpmanager.com/redirect/event/manage/features/relationships/on/" target="_blank" rel="noopener"><strong>Relationships</strong></a> feature.</p>
<p>At the end of the character edit form, you can now define relationships. At the end of the character edit form, you can select another character to add one:</p>
<p><img src="/static/tutorials/170_characters_09.webp" alt="Character relationships" width="1260" height="421"></p>
<p>The field labeled "<strong>Direct</strong>" is used to write the character''s relationship toward another. If the other character has a relationship defined toward this one, it will appear under "<strong>Inverse</strong>".</p>

<p><em>The list of relationships is shown to the participant at the end of the character''s page.</em> </p>
<hr>
<h2>Character customization</h2>
<p>With this feature, participants can customize some elements for the specific session they''ve signed up for. To use it, activate the <a href="https://larpmanager.com/redirect/event/manage/features/custom_character/on/" target="_blank" rel="noopener"><strong>Character customization</strong></a> feature.</p>
<p><em>Note: Customization applies only to the session where the participant is signed up. In events with multiple sessions, participants can customize their character independently for each session.</em></p>
<p>In <a href="https://larpmanager.com/redirect/event/manage/config/custom_character/" target="_blank" rel="noopener"><strong>Event &gt; Configuration &gt; Character customisation</strong></a>, you can select which fields are allowed for customization. Only the chosen fields are available for participants to edit during their character customization process.</p>
<p><img src="/static/tutorials/170_characters_11.webp" alt="Character customisation configuration" width="983" height="674"></p>
<p>On their assigned character, participants will find this button:</p>
<p><img src="/static/tutorials/170_characters_12.webp" alt="Customize entry in the character menu" width="266" height="86"></p>
<p>Clicking it opens the form where the selected customizable fields can be filled in by the participant.</p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/character-form/" target="_blank" rel="noopener"><em><strong>Character Sheet</strong></em></a>, <a href="https://larpmanager.com/tutorials/character-creation/" target="_blank" rel="noopener"><em><strong>Character Creation</strong></em></a>, <a href="https://larpmanager.com/tutorials/factions/" target="_blank" rel="noopener"><em><strong>Factions</strong></em></a>, <a href="https://larpmanager.com/tutorials/plots/" target="_blank" rel="noopener"><em><strong>Plots</strong></em></a></em></p>', 170);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (15, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Character References', 'character-references', '<p>Character references let you mention other characters in any text by their number instead of their name: names are always up to date, and participants can hover them to see who the character is. This tutorial explains the reference syntax, the tools to insert them, and how to check that they are consistent.</p>
<hr>
<h2>Enabling references</h2>
<p>References need character numbers: enable <strong>Number</strong> in <a href="https://larpmanager.com/redirect/event/manage/config/char_form/" target="_blank" rel="noopener"><strong>Event &gt; Configuration &gt; Character Sheet</strong></a> (see <a href="https://larpmanager.com/tutorials/character-form/#configurations" target="_blank" rel="noopener"><em><strong>Character Sheet</strong></em></a>). Each character gets a number, starting from 1, shown next to its name in <a href="https://larpmanager.com/redirect/event/manage/characters/" target="_blank" rel="noopener"><strong>Event &gt; Characters</strong></a>.</p>
<hr>
<h2>Writing a reference</h2>
<p>In any text (character, plot, faction, and so on), write the number of a character after one of these symbols:</p>
<ul>
<li><strong>#XX</strong>: a mutual relationship, where the other character knows about it (love, colleagues, rivals);</li>
<li><strong>@XX</strong>: a one-way relationship, where the other character does not know about it (secret hatred, unrequited love);</li>
<li><strong>^XX</strong>: only the name of the other character, with no relationship.</li>
</ul>
<p>For example, this text written for character #2:</p>
<p><img src="/static/tutorials/170_characters_04.webp" alt="Character reference in a text" width="1260" height="361"></p>
<p>is shown to the participant with the current name of character #1, which they can hover to see the character and its participant:</p>
<p><img src="/static/tutorials/175_character-references_02.webp" alt="Character reference shown as a popup to players" width="1663" height="956"></p>
<p>Since the name is read when the text is shown, it stays correct even if the character is renamed later, or if a participant sets a custom name.</p>
<hr>
<h2>Character finder</h2>
<p>While writing, type one of the symbols (#, @ or ^) to open a popup: type part of the character''s name, and its number is inserted for you.</p>
<p><img src="/static/tutorials/175_character-references_03.webp" alt="Popup to insert a character reference" width="1644" height="761"></p>
<p>Select a reference number in the text to see the name of that character:</p>
<p><img src="/static/tutorials/175_character-references_04.webp" alt="Character name shown for a highlighted reference" width="1280" height="667"></p>
<p>In <a href="https://larpmanager.com/redirect/event/manage/config/writing/" target="_blank" rel="noopener"><strong>Event &gt; Configuration &gt; Characters</strong></a> you can also set:</p>
<ul>
<li><strong>Disable character finder</strong>: turns off the popup, if the symbols get in the way of your writing;</li>
<li><strong>Replacing names</strong>: character names written in full in a text are replaced by their reference automatically.</li>
</ul>
<hr>
<h2>Checking references</h2>
<p>Enable <strong>Check</strong> in <a href="https://larpmanager.com/redirect/event/manage/config/writing/" target="_blank" rel="noopener"><strong>Event &gt; Configuration &gt; Characters</strong></a>, then open <a href="https://larpmanager.com/redirect/event/manage/check/" target="_blank" rel="noopener"><strong>Event &gt; Check</strong></a>. It scans all texts and reports inconsistent references: for example, if character #2 refers to character #1 with <code>#1</code> (a mutual relationship), but character #1 never mentions character #2.</p>
<p><img src="/static/tutorials/170_characters_15.webp" alt="Consistency check" width="992" height="616"></p>
<p>The same page reports the other writing problems it finds, such as missing or extra relationships with factions.</p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/characters/" target="_blank" rel="noopener"><em><strong>Characters</strong></em></a>, <a href="https://larpmanager.com/tutorials/character-form/" target="_blank" rel="noopener"><em><strong>Character Sheet</strong></em></a>, <a href="https://larpmanager.com/tutorials/plots/" target="_blank" rel="noopener"><em><strong>Plots</strong></em></a></em></p>', 175);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (16, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'PDF Generation', 'pdf-generation', '<p>PDF generation turns character sheets, the character gallery and participant profiles into printable PDF files, with your own layout: page size, margins, header and footer, background, fonts and colors. This tutorial explains the options, and suggests how to obtain common effects.</p>
<hr>
<h2>Activating PDF generation</h2>
<p>To use it, activate the <a href="https://larpmanager.com/redirect/event/manage/features/print_pdf/on/" target="_blank" rel="noopener"><strong>PDF generation</strong></a> feature. The PDF of each character sheet is regenerated automatically whenever the character is updated.</p>
<p>To let participants download their own sheet from their character page, select <strong>PDF</strong> among the elements shown to participants in <a href="https://larpmanager.com/redirect/event/manage/event/" target="_blank" rel="noopener"><strong>Event &gt; Event</strong></a>.</p>
<hr>
<h2>Downloads and test generation</h2>
<p>Go to <a href="https://larpmanager.com/redirect/event/manage/pdf/" target="_blank" rel="noopener"><strong>Event &gt; PDF</strong></a>:</p>
<p><img src="/static/tutorials/180_pdf-generation_01.webp" alt="PDF downloads and test generation" width="992" height="401"></p>
<p>At the top you can download:</p>
<ul>
<li><strong>Gallery Pdf</strong>: the portraits of all the characters (or <strong>Test gallery</strong> to preview it as a web page);</li>
<li><strong>PDF Profiles</strong>: the profiles of all the participants;</li>
<li><strong>Bulk download</strong>: a ZIP with the files you select (gallery, profiles, character sheets, faction sheets, handouts);</li>
<li><strong>All printable sheets</strong>: a ZIP with the sheets of all the characters, ready to print.</li>
</ul>
<p>Under "Try the sheet generation", select a character to generate its sheet:</p>
<ul>
<li><strong>Complete sheet</strong>: the full sheet, with your layout;</li>
<li><strong>Lightweight sheet</strong>: a simpler version, formatted automatically for easy reading and printing.</li>
</ul>
<p>The "(Test)" links show the sheet as a web page, which opens much faster than the PDF: use them while you adjust the layout.</p>
<hr>
<h2>Layout options</h2>
<p>Below, the PDF options are saved as soon as you change them, so you can try the result right away.</p>
<p><img src="/static/tutorials/180_pdf-generation_02.webp" alt="PDF options" width="983" height="916"></p>
<ul>
<li><strong>Page size</strong>: A4, A5 or Letter, each also in landscape.</li>
<li><strong>Page margin</strong>: empty space on each side of the page, in centimeters (for example 2 or 1.5).</li>
<li><strong>Header</strong>: shows on top of each page the name of the organization, of the character and of the event.</li>
<li><strong>Footer</strong>: shows on the bottom of each page the name of the event and the page number.</li>
<li><strong>Background image</strong>: an image stretched over the whole page (JPEG, PNG, GIF or WebP).</li>
<li><strong>Title font</strong> and <strong>Text font</strong>: font files (TTF or OTF) for the character name and titles, and for all the other text.</li>
<li><strong>Title size</strong> and <strong>Text size</strong>: in percent of the standard size (100 = standard).</li>
<li><strong>Title color</strong>, <strong>Text color</strong>, <strong>Link color</strong>, <strong>Highlight color</strong> (bold text) and <strong>Separator color</strong> (the lines under the header, over the footer and between sections).</li>
<li><strong>CSS</strong>: your own style rules, applied after all the options above (see below).</li>
</ul>
<p>Leave an option empty to keep the standard look. After changing the layout, click <strong>Regenerate (recreates all pdf: slow)</strong> at the bottom to rebuild all the existing PDFs (it can take a while).</p>
<p>For example, header, footer, a brown title color and a light separator color give this sheet:</p>
<p><img src="/static/tutorials/180_pdf-generation_03.webp" alt="Complete sheet with header, footer and colors" width="1280" height="568"></p>
<hr>
<h2>Suggested effects</h2>
<p>Most looks can be obtained with the options alone:</p>
<ul>
<li><em>Parchment or letter look</em>: upload a paper texture as <strong>Background image</strong>, a handwriting or calligraphy font as <strong>Title font</strong>, and a dark brown <strong>Title color</strong>. Keep the <strong>Page margin</strong> large enough (2-2.5 cm) so the text stays inside the paper edges of the image.</li>
<li><em>Themed sheet</em>: use the colors of your event for <strong>Title color</strong> and <strong>Separator color</strong>, and the event font as <strong>Title font</strong>, keeping a plain, readable <strong>Text font</strong>.</li>
<li><em>Booklet (A5)</em>: choose A5 as <strong>Page size</strong>, a smaller margin (1-1.5 cm), and a <strong>Text size</strong> around 90; enable <strong>Footer</strong> for the page numbers.</li>
<li><em>Printer friendly</em>: no background, black <strong>Text color</strong>, and a light <strong>Separator color</strong>, to save ink.</li>
</ul>
<p><em>Tip: for the background, use an image with the same proportions as the page (about 1:1.41 for A4 and A5), at least 1240 pixels wide, so it is not distorted or blurred.</em></p>
<hr>
<h2>Custom CSS</h2>
<p>For anything else, write your own rules in the <strong>CSS</strong> option. The main elements of the sheet are:</p>
<ul>
<li><code>#char_name</code>: the name of the character, at the top;</li>
<li><code>#char_present</code>: the presentation and the fields under the name;</li>
<li><code>h1</code>: the section titles (Plots, Factions, Relationships, and so on);</li>
<li><code>h2</code>: the titles inside the texts;</li>
<li><code>.plot</code>: the text of each plot;</li>
<li><code>#header_content</code> and <code>#footer_content</code>: the header and the footer.</li>
</ul>
<p>Some examples, to copy and adapt:</p>
<ul>
<li>Underline the titles inside the texts: <code>h2 { border-bottom: 1px solid #c9a36b; }</code></li>
<li>Start each section on a new page: <code>h1 { page-break-before: always; }</code></li>
<li>Keep a title on the same page as the text that follows: <code>h2 { -pdf-keep-with-next: true; }</code></li>
<li>Hide the presentation and fields: <code>#char_present { display: none; }</code></li>
<li>Justify the text: <code>p { text-align: justify; }</code></li>
</ul>
<p>To use your own images or fonts only in some places, first upload them in <a href="https://larpmanager.com/redirect/event/manage/utils/" target="_blank" rel="noopener"><strong>Event &gt; Utility</strong></a> (see <a href="https://larpmanager.com/tutorials/event-tools/#hosting-files" target="_blank" rel="noopener"><em><strong>Event Tools</strong></em></a>), then write their code between two <code>#</code>: it is replaced with the address of the file. For example, with a font uploaded with code <code>quill</code>:</p>
<p><code>@font-face { font-family: quill; src: url(''#quill#''); } #char_name { font-family: quill; }</code></p>
<p>Rules written in the <strong>CSS</strong> option always win over the options above. To define the page yourself (size, margins, frames for header and footer), write your own <code>@page</code> rule: the options fill in only what your rule does not define. For example:</p>
<p><code>@page { size: A4; @frame content_frame { margin: 2cm; } }</code></p>
<p><em>Note: the PDF is produced with xhtml2pdf, which supports only part of CSS (no flexbox or grid, for example). For all the supported properties, see the <a href="https://xhtml2pdf.readthedocs.io/en/latest/format_html.html" target="_blank" rel="noopener">xhtml2pdf documentation</a>.</em></p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/characters/" target="_blank" rel="noopener"><em><strong>Characters</strong></em></a>, <a href="https://larpmanager.com/tutorials/writing-extras/" target="_blank" rel="noopener"><em><strong>Writing Extras</strong></em></a>, <a href="https://larpmanager.com/tutorials/event-tools/" target="_blank" rel="noopener"><em><strong>Event Tools</strong></em></a></em></p>', 180);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (17, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Character Sheet', 'character-form', '<p>Character fields let you add custom attributes to characters beyond the defaults: group affiliation, status, mana, or any other value you need to track. This tutorial shows how to create, order, and configure them.</p>
<h2>Manage fields</h2>
<p>You can add any number of character fields, to track characteristics of them, such belonging to a group, special status or the amount of their mana. To manage the character fields, go to <a href="https://larpmanager.com/redirect/event/manage/writing/form/" target="_blank" rel="noopener"><strong>Event &gt; Sheet</strong></a>.</p>
<p>You can edit existing fields or add a new one by clicking "New".</p>
<p><img src="/static/tutorials/190_character-form_01.webp" alt="New character field" width="1260" height="716"></p>
<p>Input the following data:</p>
<ul>
<li><strong>Type:</strong> can be <em>Single choice</em>, <em>Multiple choice</em>, <em>Single-line text</em><em>, Multi-line text</em>, <em>Advanced Text Editor</em> (rendered as a WYSIWYG editor)</li>
<li><strong>Name:</strong> the label that is shown for the question;</li>
<li><strong>Description:</strong> the text that is shown as help text under the question;</li>
<li><strong>Visibility:</strong> can be <em>Searcheable</em> (shown as filter in gallery and search tabs), <em>Public</em> (visible by all participants), <em>Private</em> (visibile only by the assigned participant), <em>Hidden</em> (visible only to the staff).</li>
<li><strong>Printable:</strong> whether the field should be included in the PDF output.</li>
</ul>
<hr>
<p>If the <a href="https://larpmanager.com/redirect/event/manage/features/user_character/on/" target="_blank" rel="noopener"><strong>Character creation</strong></a> feature is active (see the <a href="https://larpmanager.com/tutorials/character-creation/" target="_blank" rel="noopener"><em><strong>Character Creation</strong></em></a> tutorial), an additional field will appear, specifying how the field should be handled when the participant edits or creates their character:</p>
<p><img src="/static/tutorials/190_character-form_02.webp" alt="Field status for character creation" width="1260" height="160"></p>
<ul>
<li><strong>Status:</strong> can be Optional (active but not required), Mandatory (active and required), Disabled (shown but not editable), Hidden (not shown in the form).</li>
<li><strong>Name</strong>: Text shown for this option.</li>
<li><strong>Description</strong>: Optional help text displayed under the question.</li>
</ul>
<hr>
<p><em>If you want to reorder either questions or options, click and drag on the leftmost icon.</em></p>
<hr>
<h2>Configurations</h2>
<p>In <a href="https://larpmanager.com/redirect/event/manage/config/char_form/" target="_blank" rel="noopener"><strong>Event &gt; Configuration &gt; Character Sheet</strong></a>, you find four options:</p>
<p><img src="/static/tutorials/190_character-form_04.webp" alt="Character sheet configuration" width="983" height="1174"></p>
<ul>
<li><strong>Hide Not Available</strong>: When enabled, character options that are not available due to restrictions are hidden entirely instead of shown as disabled. If disabled, unavailable options are visible but not selectable.</li>
<li><strong>Maximum Available</strong>: When enabled, option to character fields can be limited (see <a href="https://larpmanager.com/tutorials/character-form/#maximum-available">Maximum Available</a> below).</li>
<li><strong>Ticket Selection</strong>: Adds a field to restricts an option''s availability to characters assigned to participants who selected specific tickets. If no tickets are set, the option is available for all.</li>
<li><strong>Requirements</strong>: Adds a field to restricts option availability based on other selected options. Requires all fields listed (<em>AND</em>) and at least one of the specified options within each field (<em>OR</em>). Applies to both Single and Multiple choice fields.</li>
<li><strong>Title</strong>: If enabled, a special field "title" is available (see <a href="https://larpmanager.com/tutorials/character-form/#title" target="_blank" rel="noopener"><em><strong>Title</strong></em></a> below), and it''s content is shown together with the character''s name in the gallery.</li>
<li><strong>Concept</strong>: If enabled, a special field "Concept" is available, never shown to participants, and shown with the character''s name when searching then in organizer forms.</li>
<li><strong>Number</strong>: If enabled, each character is assigned an unique numerical ID; see the <a href="https://larpmanager.com/tutorials/character-references/" target="_blank" rel="noopener"><em><strong>Character References</strong></em></a> tutorial.</li>
<li><strong>Cover image:</strong> If enabled, a cover image can be uploaded for each character (see <a href="https://larpmanager.com/tutorials/character-form/#cover" target="_blank" rel="noopener"><em><strong>Cover</strong></em></a> below), shown in the gallery until the character is assigned to a participant.</li>
<li><strong>File</strong>: If enabled, in the character sheet there is available a special "file" field, useful for uploading PDFs, images or other files.</li>
<li><strong>Hide</strong>: If enabled, each character will have an "Hide" field, with which it can be hidden from participants.</li>
<li><strong>Locked</strong>: If enabled, each character gets a <strong>Locked</strong> checkbox; when it is checked, the private fields of that character are not shown to the assigned participant.</li>
<li><strong>Assignment</strong>: If enabled, each will have an "Assigned" field (see <a href="https://larpmanager.com/tutorials/character-form/#assigned" target="_blank" rel="noopener"><em><strong>Assigned</strong></em></a> below), where a staff member can be selected as the assigned author for that character.</li>
</ul>
<h2>Maximum available</h2>
<p><em>Limit how many characters can choose an option, for example a faction or class.</em></p>
<p>In <a href="https://larpmanager.com/redirect/event/manage/writing/form/" target="_blank" rel="noopener"><strong>Event &gt; Sheet</strong></a>, open a single or multiple choice field. Set the <strong>Maximum</strong> column of an option to the number of characters that can choose it. Leave it empty or 0 for no limit.</p>
<p><img src="/static/tutorials/190_character-form_11.webp" alt="Options with the maximum number of characters" width="1260" height="322"></p>
<p><em>Please note that each session / event has it own spots, and only characters assigned to a participant of the session take a spot.</em></p>
<p>Participants see the remaining spots next to the option, for example "Available 2". When no spots are left, the option is disabled.</p>
<hr>
<p><em>Note: if a participant tries to play a character whose option has no spots left, the assignment is refused.</em></p>
<p><em>Note: organizers can still assign the character from <a href="https://larpmanager.com/redirect/event/manage/registrations/" target="_blank" rel="noopener"><strong>Event &gt; Registrations</strong></a> or with the <a href="https://larpmanager.com/tutorials/casting/" target="_blank" rel="noopener"><em><strong>Casting</strong></em></a> algorithm. A warning shows which options exceed their maximum.</em></p>
<hr>
<h2>Title</h2>
<p><em>Used to add a short 2-3 word title to characters.</em> A new field, <strong>Title</strong>, is added to the character form.</p>
<p>The title will appear in the gallery next to the character''s name.</p>
<p><img src="/static/tutorials/190_character-form_06.webp" alt="Character title in the gallery" width="209" height="200"></p>
<hr>
<h2>Cover</h2>
<p>Allows customization of the character''s cover image (before assignment to a participant). A new field, <strong>Cover</strong>, is added to the character form.</p>
<p>The cover image is displayed in the gallery.</p>
<hr>
<h2>Assigned</h2>
<p>Tracks which staff member is responsible for a writing element (character, faction, etc). A new field, <strong>Assigned</strong>, is added to the character form.</p>
<p><em>The member list is drawn from users with a staff role in the event.</em></p>
<hr>
<h2>Progress</h2>
<p>This field is used to track the writing progress of a writing element (example: draft, review, approved, etc). To use it, activate the <a href="https://larpmanager.com/redirect/event/manage/features/progress/on/" target="_blank" rel="noopener"><strong>Progress</strong></a> feature.</p>
<p>Go to <a href="https://larpmanager.com/redirect/event/manage/progress_steps/" target="_blank" rel="noopener"><strong>Event &gt; Progress</strong></a>, and add new progress steps clicking on "Add".</p>
<p>A new field, <strong>Progress</strong>, is added to the character form.</p>
<p><em>If both <strong>Progress</strong> and <strong>Assigned</strong> are active, a summary appears mapping assigned characters to progress.</em></p>
<p><img src="/static/tutorials/190_character-form_10.webp" alt="Progress and assignment views" width="807" height="78"></p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/characters/" target="_blank" rel="noopener"><em><strong>Characters</strong></em></a>, <a href="https://larpmanager.com/tutorials/character-creation/" target="_blank" rel="noopener"><em><strong>Character Creation</strong></em></a>, <a href="https://larpmanager.com/tutorials/xp/" target="_blank" rel="noopener"><em><strong>Experience Points</strong></em></a></em></p>', 190);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (18, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Character Creation', 'character-creation', '<p>With the character creation feature, participants can create and edit their own characters directly on the platform. This tutorial explains how to configure the maximum character limit, the approval workflow, and what the creation flow looks like from the participant''s perspective.</p>
<h2>Character creation</h2>
<p>With this feature, characters can be created and edited by the participants. To use it, activate the <a href="https://larpmanager.com/redirect/event/manage/features/user_character/on/" target="_blank" rel="noopener"><strong>Character creation</strong></a> feature.</p>
<p>In <a href="https://larpmanager.com/redirect/event/manage/config/user_character/" target="_blank" rel="noopener"><strong>Event &gt; Configuration &gt; Character creation</strong></a>, these options are available:</p>
<p><img src="/static/tutorials/200_character-creation_01.webp" alt="Character creation configuration" width="983" height="295"></p>
<hr>
<h3>Maximum Number</h3>
<p>The <strong>Maximum Number</strong> option sets the limit of characters a participant can create:</p>
<p>If set to <strong>0</strong>, the participant cannot create characters but can edit characters created by staff and assigned to them.</p>
<p>If set to a value greater than <strong>0</strong>, and the participant is signed up and currently has fewer characters than the limit, they are prompted to create a new character.</p>
<p><img src="/static/tutorials/200_character-creation_02.webp" alt="Prompt to create a character" width="518" height="62"></p>
<hr>
<p>After a character is created, new links are added to the sidebar to open the character page or edit it:</p>
<p><img src="/static/tutorials/200_character-creation_03.webp" alt="Character entries in the menu" width="266" height="86"></p>
<p><em>Note: When a character is created by the participant, it is automatically assigned to them for that event.</em></p>
<p><em>Note: If the <strong>Campaign</strong> feature is active, and the participant created a character in the parent event, signing up to a new event will automatically assign that character to them in the new event as well.</em></p>
<hr>
<h2>Approval</h2>
<p>You can setup a character approval process, requiring each character to be submitted by the participant and approved by staff before joining.</p>
<p>Check the <strong>Approval</strong> option; a <strong>Status</strong> field is added when editing characters in <a href="https://larpmanager.com/redirect/event/manage/characters/" target="_blank" rel="noopener"><strong>Event &gt; Characters</strong></a>.</p>

<p>The possible values are:</p>
<ul>
<li><strong>Creation</strong>: Character has been created.</li>
<li><strong>Proposed</strong>: Participant has submitted the character for staff approval.</li>
<li><strong>Review</strong>: Staff has requested changes.</li>
<li><strong>Approved</strong>: Character has been approved.</li>
</ul>
<hr>
<p>On the participant''s character form, <em>only if the character is in status Creation</em>, there is this link available:</p>
<p><img src="/static/tutorials/200_character-creation_05.webp" alt="Prompt to propose the character" width="693" height="62"></p>
<p>If confirmed, the character moves to <strong>Proposed.</strong></p>
<hr>
<p><em>Characters appear in the gallery only when <strong>Approved</strong>.</em></p>
<p><em>Custom texts for each status change can be defined in <a href="https://larpmanager.com/redirect/event/manage/texts/" target="_blank" rel="noopener"><strong>Event &gt; Texts</strong></a>, by selecting the appropriate type.</em></p>
<hr>
<p>Additionally, each character field in <a href="https://larpmanager.com/redirect/event/manage/writing/form/" target="_blank" rel="noopener"><strong>Event &gt; Sheet</strong></a> can be configured to be editable only in selected stages:</p>
<p><img src="/static/tutorials/200_character-creation_06.webp" alt="Stages in which a field is editable" width="1260" height="95"></p>
<p><em><strong>Important</strong>: This feature is designed for <strong>single-session</strong> events. For multi-session events (where a character is played by different participants in different sessions), use <a href="https://larpmanager.com/tutorials/characters/#character-customization" target="_blank" rel="noopener"><em><strong>Character Customization</strong></em></a> instead.</em></p>
<hr>
<h2>Active / inactive characters</h2>
<p><em>This feature is only available when the <a href="https://larpmanager.com/redirect/manage/features/campaign/on/" target="_blank" rel="noopener"><strong>Campaign</strong></a> feature is active.</em></p>
<p>In a campaign, a character may become permanently retired, killed, or otherwise unable to continue. You can reflect this by marking them as <strong>Inactive</strong>.</p>
<p>To do so, open the character''s edit form from <a href="https://larpmanager.com/redirect/event/manage/characters/" target="_blank" rel="noopener"><strong>Event &gt; Characters</strong></a>. When Campaign is active, an <strong>Active</strong> checkbox will appear.</p>

<p>By default, all characters are <strong>Active</strong>. Uncheck the box to mark the character as <strong>Inactive:</strong> </p>
<ul>
<li>The character can no longer be manually or automatically assigned to a participant (assignments for events that have not yet started are automatically deleted)</li>
<li>Inactive characters are not counted toward the participant''s maximum character limit. This allows the participant to create or receive a new character without hitting the cap.</li>
</ul>
<hr>
<p>In <a href="https://larpmanager.com/redirect/event/manage/characters/" target="_blank" rel="noopener"><strong>Event &gt; Characters</strong></a>, an <strong>Active</strong> column is shown (toggle it from the column selector). A checkmark indicates the character is active; no checkmark means inactive.</p>
<p>Similarly, from the participant''s side, the <strong>Characters</strong> page groups campaign characters by campaign and shows an <strong>Active</strong> column. A checkmark means the character is still in play; no checkmark means the character is retired.</p>
<p><em>Note: Inactive characters remain visible, so their character sheet and game history is maintained.</em> </p>
<hr>
<h2>Player relationships</h2>
<p>This feature allows participants to write relationships between their character and others. To use it, activate the <a href="https://larpmanager.com/redirect/event/manage/features/player_relationships/on/" target="_blank" rel="noopener"><strong>Player relationships</strong></a> feature.</p>
<p>A <strong>"Relationship"</strong> button is added on the user''s side:</p>
<p><img src="/static/tutorials/200_character-creation_08.webp" alt="Relationships entry in the character menu" width="266" height="121"></p>
<p>Clicking <strong>"New"</strong> opens the relationship form.</p>
<p><img src="/static/tutorials/200_character-creation_09.webp" alt="New relationship form" width="992" height="688"></p>
<p><em>Relationships are listed at the end of the character''s page.</em></p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/characters/" target="_blank" rel="noopener"><em><strong>Characters</strong></em></a>, <a href="https://larpmanager.com/tutorials/character-form/" target="_blank" rel="noopener"><em><strong>Character Sheet</strong></em></a>, <a href="https://larpmanager.com/tutorials/casting/" target="_blank" rel="noopener"><em><strong>Casting</strong></em></a></em></p>', 200);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (19, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Character Inventory', 'character-inventory', '<p>The <a href="https://larpmanager.com/redirect/event/manage/features/inventory/on/" target="_blank" rel="noopener"><strong>Character inventory</strong></a> feature lets you assign and track resources, such as currencies, materials, or consumables, to characters. Staff can define resource types, create inventories, add resources from the NPC bank, and track every transfer. Participants can view their inventory on their character sheet and transfer resources to other characters at any moment.</p>
<h2>Setup: pool types</h2>
<p>Before creating inventories, define the types of resources characters can hold. To do this, go to <a href="https://larpmanager.com/redirect/event/manage/ci/pool_types/" target="_blank" rel="noopener"><strong>Event &gt; Pool Types</strong></a> and click "Add" to create a new resource type.</p>
<p>Set as <strong>Name</strong> the name of the resource (e.g. "Money", "Weapons", "Reagents").</p>
<p><em>Note: all pool types you define here will appear as separate balance rows in every inventory.</em></p>
<hr>
<h2>Inventories</h2>
<p>Go to <a href="https://larpmanager.com/redirect/event/manage/ci/inventory/" target="_blank" rel="noopener"><strong>Event &gt; Character Inventory</strong></a> to see all inventories for the event. A character can own multiple inventories, and an inventory can be shared by multiple characters.</p>
<p><em>Note that a personal inventory for each character is created automatically for each character. It is named &lt;Character Name&gt;''s Personal Storage and is assigned to that character as its sole owner. This means you do not need to create individual inventories manually for every character, as they are provisioned automatically.</em></p>
<p>To create a new Inventory (for example for a bank or a guild), click "New". Define the following values:</p>
<ul>
<li><strong>Name:</strong> a label for the inventory.</li>
<li><strong>Owners:</strong> one or more characters that have access to this inventory.</li>
</ul>
<hr>
<h2>Viewing and managing an inventory</h2>
<p>From <a href="https://larpmanager.com/redirect/event/manage/ci/inventory/" target="_blank" rel="noopener"><strong>Event &gt; Character Inventory</strong></a>, click the view icon next to an inventory to open its detail page.</p>
<p>The first section is <strong>Currencies &amp; Materials,</strong> with a row for each pool type with the current balance. Staff can add resources directly from the NPC bank by entering an amount and clicking "Add from NPC". A <strong>Reason</strong> field is available to record why the resources were added. The source inventory must have enough resources (transfers that exceed the available balance are rejected).</p>
<p><em>Note: Staff can transfer from any inventory to any other inventory, or from/to the NPC bank. Participants can transfer only from inventories they own, and cannot transfer to or from the NPC bank.</em></p>
<p><em>Note: "NPC" in the transfer log means the event''s resource bank; it represents resources entering or leaving the game economy.</em></p>
<p><img src="/static/tutorials/202_character-inventory_01.webp" alt="Inventory balances and transfers" width="992" height="615"></p>
<p>The second section is <strong>Transfer Log:</strong> a full history of every transfer involving this inventory, showing the time, the staff member or participant who performed the transfer, the source and target inventories, the resource type, the amount, and the reason.</p>
<p><img src="/static/tutorials/202_character-inventory_02.webp" alt="Transfer log" width="983" height="273"></p>
<hr>
<h2>Participant view</h2>
<p>On the participant''s character sheet, an <strong>Inventories</strong> section appears listing all inventories owned by that character. Each inventory card shows the name and the current balance of every resource type, with a link to the inventory detail page.</p>
<p><em>Participants can open the detail page to view their transfer history and send resources to other characters'' inventories.</em></p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/characters/" target="_blank" rel="noopener"><em><strong>Characters</strong></em></a>, <a href="https://larpmanager.com/tutorials/xp/" target="_blank" rel="noopener"><em><strong>Experience Points</strong></em></a></em></p>', 202);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (20, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Experience Points', 'xp', '<p>The <a href="https://larpmanager.com/redirect/event/manage/features/experience/on/" target="_blank" rel="noopener"><strong>Experience points</strong></a> feature lets you assign XP to characters and allow participants to spend it on abilities and skills. This tutorial explains how to configure the XP system, manage ability trees, and handle participant-driven selection.</p>
<h2>Abilities</h2>
<p>With the feature active, first define the type of abilities in <a href="https://larpmanager.com/redirect/event/manage/experience/ability_types/" target="_blank" rel="noopener"><strong>Event &gt; Ability type</strong></a>, and click on "Add" to input a new type of ability.</p>
<p>Go to <a href="https://larpmanager.com/redirect/event/manage/experience/abilities/" target="_blank" rel="noopener"><strong>Event &gt; Abilities</strong></a>, and click on "Add" to input a new ability:</p>
<p><img src="/static/tutorials/205_xp_01.webp" alt="New ability" width="1260" height="1357"></p>
<ul>
<li><strong>Name</strong>: Name of the ability;</li>
<li><strong>Type</strong>: The associated ability type;</li>
<li><strong>Cost</strong>: XP cost to acquire the ability (If the cost is 0, the ability is automatically given to the characters).</li>
<li><strong>Description</strong>: Explanation of what the ability does;</li>
<li><strong>Visible: </strong>If the ability is visible to all characters to be obtained. If not, you can choose a list of characters that will have access to it.</li>
<li><strong>Pre-requisites:</strong> List of other abilities that a character is required to have for this ability to be available;</li>
<li><strong>Requirements</strong>: List of character options (see the <a href="https://larpmanager.com/tutorials/character-form/#manage-fields" target="_blank" rel="noopener"><em><strong>Character Sheet</strong></em></a> tutorial) that a character is required to have for this ability to be available;</li>
<li><strong>Characters</strong>: List of characters to assign this ability to.</li>
</ul>
<hr>
<h2>Awards</h2>
<p>To give experience points to characters, go to <a href="https://larpmanager.com/redirect/event/manage/experience/awards/" target="_blank" rel="noopener"><strong>Event &gt; Awards</strong></a>, and click on "Add":</p>
<p><img src="/static/tutorials/205_xp_02.webp" alt="New award" width="1260" height="604"></p>
<p>Input the name for the award, the amount of experience points to give, and the list of characters to select.</p>
<p>You can also directly load characters from all participants that participated in the event:</p>
<p><img src="/static/tutorials/205_xp_03.webp" alt="Load characters into an award" width="992" height="301"></p>
<hr>
<p><em>(Abilities and awards for each character can be selected also in the characters''s edit form)</em></p>
<hr>
<h2>Configurations</h2>
<p>In <a href="https://larpmanager.com/redirect/event/manage/config/experience/" target="_blank" rel="noopener"><strong>Event &gt; Configuration &gt; Experience points</strong></a>, these options are available:</p>
<p><img src="/static/tutorials/205_xp_04.webp" alt="Experience points configuration" width="983" height="1201"></p>
<ul>
<li><strong>Player selection</strong>: allows participants to add abilities themselves to their characters, see <a href="https://larpmanager.com/tutorials/xp/#player-selection" target="_blank" rel="noopener"><em><strong>Player Selection</strong></em></a> below.</li>
<li><strong>Undo period:</strong> Grace period to allow participants to change their idea on chosen ability, removing them and getting back its XP cost. (default is 0).</li>
<li><strong>Initial experience points:</strong> Value of experience points added by default to all characters.</li>
<li><strong>Ability templates:</strong> see <a href="https://larpmanager.com/tutorials/xp/#templates" target="_blank" rel="noopener"><em><strong>Templates</strong></em></a> below.</li>
<li><strong>Rules</strong>: see <a href="https://larpmanager.com/tutorials/xp/#rules" target="_blank" rel="noopener"><em><strong>Rules</strong></em></a> below.</li>
<li><strong>Modifiers</strong>: see <a href="https://larpmanager.com/tutorials/xp/#modifiers" target="_blank" rel="noopener"><em><strong>Modifiers</strong></em></a> below.</li>
<li><strong>Criteria</strong>: see <a href="https://larpmanager.com/tutorials/xp/#criterions" target="_blank" rel="noopener"><em><strong>Criterions</strong></em></a> below.</li>
<li><strong>Exclusive groups</strong>: see <a href="https://larpmanager.com/tutorials/xp/#exclusive-groups" target="_blank" rel="noopener"><em><strong>Exclusive groups</strong></em></a> below.</li>
<li><strong>Auto buy:</strong> enforce automatic buy of all abilities available if there are available XP on a character.</li>
<li><strong>Disable free abilities:</strong> by default, character automatically acquire abilities with 0 cost. With this configuration, this is disabled.</li>
<li><strong>Multiple systems</strong>: see <a href="https://larpmanager.com/tutorials/xp/#system" target="_blank" rel="noopener"><em><strong>System</strong></em></a> below.</li>
</ul>
<hr>
<h2>Player selection</h2>
<p>If <strong>Player Selection</strong> is checked, participants will see a new page on their character page:</p>
<p><img src="/static/tutorials/205_xp_05.webp" alt="Abilities entry in the character menu" width="266" height="86"></p>
<p>Where they can obtain new abilities, provided they have sufficient XP and meet all prerequisites:</p>
<p><img src="/static/tutorials/205_xp_06.webp" alt="Obtain a new ability" width="992" height="629"></p>
<p>If you have set a value of <strong>Undo Period</strong>, participants can cancel a newly acquired ability for that number of hours:</p>
<p><img src="/static/tutorials/205_xp_07b.webp" alt="Owned abilities with undo" width="983" height="355"></p>
<p>When defining new abilities, you find a new checkbox, <strong>Visible</strong>.</p>
<p>Participants can obtain only abilities that:</p>
<ul>
<li>are visible;</li>
<li>have all the required pre-requisites (AND between pre-requisite abilities);</li>
<li>match the indicated character options (AND between character fields, OR within each character field);</li>
<li>are not blocked by an exclusive group (see <a href="https://larpmanager.com/tutorials/xp/#exclusive-groups" target="_blank" rel="noopener"><em><strong>Exclusive groups</strong></em></a> below).</li>
</ul>
<p>If the approval process of the <a href="https://larpmanager.com/redirect/event/manage/features/user_character/on/" target="_blank" rel="noopener"><strong>Character creation</strong></a> feature is active (see the <a href="https://larpmanager.com/tutorials/character-creation/" target="_blank" rel="noopener"><em><strong>Character Creation</strong></em></a> tutorial), the ability form shows a new checkbox, <strong>Creation only</strong>. Participants can obtain these abilities only until their character is approved.</p>
<p><img src="/static/tutorials/205_xp_12.webp" alt="Creation only and exclusive group notes on the abilities" width="983" height="382"></p>
<p><em>Note: abilities already obtained stay on the character after approval. Staff can always assign any ability.</em></p>
<hr>
<h2>Rules</h2>
<p>You can also configure custom character fields whose value is auto-computed based on the character''s abilities; for example, <em><strong>hit points</strong></em><em>.</em> To configure them, first enable <em>Rules</em> in <a href="https://larpmanager.com/redirect/event/manage/config/experience/" target="_blank" rel="noopener"><strong>Event &gt; Configuration &gt; Experience points</strong></a>, then go to <a href="https://larpmanager.com/redirect/event/manage/writing/form/" target="_blank" rel="noopener"><strong>Event &gt; Sheet</strong></a> and create a new character field with type "<strong>Computed</strong>" (this field is not editable by staff or the participant, as it''s value is automatically computed):</p>
<p><img src="/static/tutorials/205_xp_09.webp" alt="Computed field type" width="1260" height="346"></p>
<p>Go to <a href="https://larpmanager.com/redirect/event/manage/experience/rules/" target="_blank" rel="noopener"><strong>Event &gt; Rules</strong></a> to define how this new field should be computed:</p>
<p><img src="/static/tutorials/205_xp_10.webp" alt="New rule" width="1260" height="435"></p>
<p>Set as values:</p>
<ul>
<li><strong>Abilities</strong>: The rule is applied for all characters with at least one of the abilities. If no abilities are selected, the rule is applied to <em>all</em> character. (Please note that the rule is applied only one time; if you want separate effects for different abilities, add new rules for them).</li>
<li><strong>Field</strong>: The character field whose value is updated.</li>
<li><strong>Operation</strong>: Either addition, subtraction, multiplication, division.</li>
<li><strong>Amount</strong>: The value of the operation.</li>
</ul>
<hr>
<h2>Modifiers</h2>
<p>You can define alternative costs for abilities, based on whether the character has already learned certain abilities or meets specific character conditions, for example:</p>
<ul>
<li>Assign <em>default skills for a class</em> by setting their cost to 0, so all characters of that class automatically gain them.</li>
<li>Reduce the cost of a skill for a class, meaning it''s easier for them to obtain;</li>
<li>Block <em>certain skills</em> by assigning a prohibitive cost (e.g., 999) if the character has already learned conflicting abilities or belongs to a restricted class.</li>
</ul>
<hr>
<p><em><strong>Note: If multiple modifiers apply to the same ability, only the first one in the defined order takes effect.</strong></em></p>
<hr>
<p>To manage them, first enable them in <a href="https://larpmanager.com/redirect/event/manage/config/experience/" target="_blank" rel="noopener"><strong>Event &gt; Configuration &gt; Experience points</strong></a>, then go to <a href="https://larpmanager.com/redirect/event/manage/experience/modifiers/" target="_blank" rel="noopener"><strong>Event &gt; Modifiers</strong></a> to define how this new rule should be applied:</p>
<p><img src="/static/tutorials/205_xp_11.webp" alt="New modifier" width="1260" height="637"></p>
<p>Set as values:</p>
<ul>
<li><strong>Abilities</strong>: The modifier is applied to all the selected abilities.</li>
<li><strong>Cost</strong>: The new cost to apply.</li>
<li><strong>Pre-requisites</strong>: The modifier is applied if the character has learnt all of the selected pre-requisite abilities.</li>
<li><strong>Requirements</strong>: The modifier is applied if the character has all the selected options (see <a href="https://larpmanager.com/tutorials/character-form/#manage-fields" target="_blank" rel="noopener"><em><strong>Manage fields</strong></em></a> in the Character Sheet tutorial).</li>
</ul>
<hr>
<h2>Criterions</h2>
<p>You can define conditions that alters the amount of experience points for a character, given any combination of character options, or even pre-requisite abilities. For example, a specific race that starts with less experience points, or a specific combination of abilities that conveys an experience bonus.</p>
<p>To configure them, enable them in <a href="https://larpmanager.com/redirect/event/manage/config/experience/" target="_blank" rel="noopener"><strong>Event &gt; Configuration &gt; Experience points</strong></a>, then go to <a href="https://larpmanager.com/redirect/event/manage/experience/criterions/" target="_blank" rel="noopener"><strong>Event &gt; Criteria</strong></a>.</p>
<hr>
<h2>Exclusive groups</h2>
<p>You can limit how many abilities of a set a character can obtain. For example, only one fighting style among three, or at most two magic schools.</p>
<p>To configure them, enable them in <a href="https://larpmanager.com/redirect/event/manage/config/experience/" target="_blank" rel="noopener"><strong>Event &gt; Configuration &gt; Experience points</strong></a>, then go to <a href="https://larpmanager.com/redirect/event/manage/experience/exclusives/" target="_blank" rel="noopener"><strong>Event &gt; Exclusive groups</strong></a> and click "New".</p>
<p>Define the following values:</p>
<ul>
<li><strong>Name</strong>: name of the group, shown to participants.</li>
<li><strong>Abilities</strong>: the abilities that belong to the group.</li>
<li><strong>Maximum</strong>: how many abilities of the group a character can obtain.</li>
</ul>
<p>Once a character reaches the maximum, the other abilities of the group no longer appear among the ones participants can obtain. If participants cancel an ability during the <strong>Undo Period</strong>, the group frees up again.</p>
<p><em>Note: the limit also applies to automatic purchase and to abilities with cost 0, but not to abilities assigned by staff.</em></p>
<hr>
<h2>System</h2>
<p>LarpManager automatically creates one system for experience points (with name "XP"). You can manage multiple systems, each one with their dedicated abilities and deliveries.</p>
<p>To configure them, enable them in <a href="https://larpmanager.com/redirect/event/manage/config/experience/" target="_blank" rel="noopener"><strong>Event &gt; Configuration &gt; Experience points</strong></a>, then go to <a href="https://larpmanager.com/redirect/event/manage/experience/systems/" target="_blank" rel="noopener"><strong>Event &gt; Systems</strong></a>.</p>
<hr>
<h2>Templates</h2>
<p>If you have a lot of similar abilities, you can set up the Template. If in a ability you set a template, will use its description; so if you set up many abilities with the same template, they will all share the same description, while having different costs and requirements.</p>
<p>To configure them, enable them in <a href="https://larpmanager.com/redirect/event/manage/config/experience/" target="_blank" rel="noopener"><strong>Event &gt; Configuration &gt; Experience points</strong></a>, then go to <a href="https://larpmanager.com/redirect/event/manage/experience/ability_templates/" target="_blank" rel="noopener"><strong>Event &gt; Ability Templates</strong></a>.</p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/characters/" target="_blank" rel="noopener"><em><strong>Characters</strong></em></a>, <a href="https://larpmanager.com/tutorials/character-form/" target="_blank" rel="noopener"><em><strong>Character Sheet</strong></em></a>, <a href="https://larpmanager.com/tutorials/checkin/" target="_blank" rel="noopener"><em><strong>Check-in</strong></em></a>, <a href="https://larpmanager.com/tutorials/debrief/" target="_blank" rel="noopener"><em><strong>Debrief</strong></em></a></em></p>', 205);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (21, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Factions', 'factions', '<p>Factions let you group characters into named in-game organizations: nations, guilds, classes, or secret societies. This tutorial covers the three faction types and explains how they affect the character gallery and character sheets.</p>
<h2>Manage factions</h2>
<p>To group the characters in factions, activate the <a href="https://larpmanager.com/redirect/event/manage/features/faction/on/" target="_blank" rel="noopener"><strong>Factions</strong></a> feature.</p>
<p>In <a href="https://larpmanager.com/redirect/event/manage/factions/" target="_blank" rel="noopener"><strong>Event &gt; Factions</strong></a>, click on "New" to create a new faction:</p>
<p><img src="/static/tutorials/210_factions_01.webp" alt="New faction form" width="1260" height="951"></p>
<p><strong>Type:</strong> There are three: <em>Primary (</em>Used for main grouping in the gallery, such as nation, core affiliation), <em>Transversal (</em>Cross-grouping across primary faction, such as class, race, profession), <em>Secret (</em>Hidden faction, visible only to assigned characters, used for secret plots)</p>
<ul>
<li><strong>Name:</strong> Public name of the faction</li>
<li><strong>Presentation:</strong> Public description of the faction</li>
<li><strong>Text:</strong> Private description, visible only to participants in the faction</li>
<li><strong>Characters:</strong> List of characters assigned to this faction</li>
</ul>
<hr>
<p><em>A character can be assigned to only one "Primary" faction.</em></p>
<hr>
<p>In the character gallery, characters are grouped under their primary faction:</p>
<p><img src="/static/tutorials/210_factions_05.webp" alt="Gallery grouped by faction" width="983" height="610"></p>
<p>To show the factions to participants, toggle the visibility in <a href="https://larpmanager.com/redirect/event/manage/event/" target="_blank" rel="noopener"><strong>Event &gt; Event</strong></a>:</p>
<p><img src="/static/tutorials/210_factions_02.webp" alt="Faction fields visible to players" width="1260" height="164"></p>
<hr>
<p>If the <a href="https://larpmanager.com/redirect/event/manage/features/user_character/on/" target="_blank" rel="noopener"><strong>Character creation</strong></a> feature is active (see the <a href="https://larpmanager.com/tutorials/character-creation/" target="_blank" rel="noopener"><em><strong>Character Creation</strong></em></a> tutorial), a new checkbox, <strong>Selectable</strong>, is added to the faction form.</p>

<p>Participants can select this faction in the <strong>Faction</strong> field when creating or editing their character.</p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/characters/" target="_blank" rel="noopener"><em><strong>Characters</strong></em></a>, <a href="https://larpmanager.com/tutorials/guilds/" target="_blank" rel="noopener"><em><strong>Guilds</strong></em></a>, <a href="https://larpmanager.com/tutorials/casting/" target="_blank" rel="noopener"><em><strong>Casting</strong></em></a></em></p>', 210);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (22, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Ensemble', 'ensemble', '<p>This tutorial presents Ensemble, a tool that helps players learn all the characters of the event before it starts, with printable cards, a booklet and a mobile-friendly list.</p>
<hr>
<h2>What is Ensemble?</h2>
<p>Ensemble facilitates an accessible presentation of characters and a quick way to learn them. It provides organizers and players with a very flexible tool and intuitive interface for presenting, sorting and categorizing characters. Remembering them is made easy, social and fun through a deck of flash cards, a booklet as well as an online database. There is no need for layout skills, Ensemble lets you print the cards and booklet with all layout done, and you don''t need an app to access the characters from your phone.</p>
<p>Ensemble is suitable for all kinds of larps, from small chamber larps where the organizer presents the players with pre-written characters and fixed relations, up to and including huge sandbox games where the players write their characters and group affiliations themselves.</p>
<p><img src="/static/tutorials/215_ensemble_01.webp" alt="Printed character cards and booklet" width="698" height="415"></p>
<hr>
<h2>Why Ensemble?</h2>
<p>So many of the larps we play portray very close-knit communities, be it a village, a spaceship, a military unit, a prison camp or a school class. You will typically have close relationships with a few other characters, and maybe learn about a couple more, but the feeling that you really ought to know all of them intimately lingers.</p>
<p>Through Ensemble the players can realistically be expected to arrive at the site already knowing most of the other characters. This means less onsite time has to be allocated for character and group presentation workshops. Players will be more familiar with the social structure of the larp and feel less stress about "who is who", they will feel more immersed and can more easily play with everyone instead of just the players they know the best. Basically, the players will have a better game.</p>
<p><img src="/static/tutorials/215_ensemble_02.webp" alt="How Ensemble works" width="935" height="625"></p>
<hr>
<h2>How to use</h2>
<p>Once you activate the <a href="https://larpmanager.com/redirect/event/manage/features/ensemble/on/" target="_blank" rel="noopener"><strong>Ensemble</strong></a> feature, the user interface will show the link to the dedicated page:</p>
<p><img src="/static/tutorials/215_ensemble_03.webp" alt="Ensemble entry in the event menu" width="266" height="121"></p>
<p>In it, there are three views available: <strong>Book</strong> (to show all the characters in a booklet format), <strong>Cards</strong> (to show / print the characters in the cards format), <strong>Compact list</strong> (to show the characters in list format).</p>
<p>Once the feature is active, in the Factions edit page it will be possible to choose a color; the card of a character will show at the top the colors of the factions assigned.</p>
<p><em>(Many thanks to Janusz Maxe and Lars Nordbeck for sharing their work!)</em></p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/characters/" target="_blank" rel="noopener"><em><strong>Characters</strong></em></a>, <a href="https://larpmanager.com/tutorials/factions/" target="_blank" rel="noopener"><em><strong>Factions</strong></em></a></em></p>', 215);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (23, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Guilds', 'guilds', '<p>Guilds are groups of characters created and managed by the participants themselves: a thieves'' guild, a band of mercenaries, a secret circle. This tutorial explains how participants create guilds and invite other characters, and what organizers can see and configure.</p>
<hr>
<h2>Activating guilds</h2>
<p>To use it, activate the <a href="https://larpmanager.com/redirect/event/manage/features/guild/on/" target="_blank" rel="noopener"><strong>Guilds</strong></a> feature. It requires the <strong>Characters</strong> feature (see the <a href="https://larpmanager.com/tutorials/characters/" target="_blank" rel="noopener"><em><strong>Characters</strong></em></a> tutorial).</p>
<p>In <a href="https://larpmanager.com/redirect/event/manage/config/guild/" target="_blank" rel="noopener"><strong>Event &gt; Configuration &gt; Guilds</strong></a> you can set two limits:</p>
<p><img src="/static/tutorials/217_guilds_01.webp" alt="Guilds configuration" width="983" height="320"></p>
<ul>
<li><strong>Maximum number</strong>: how many guilds participants can create in the event (0 = no limit).</li>
<li><strong>Maximum members</strong>: how many accepted members each guild can have (0 = no limit).</li>
</ul>
<hr>
<h2>Creating a guild</h2>
<p>Participants find a new entry, <strong>Guilds</strong>, in the event menu:</p>
<p><img src="/static/tutorials/217_guilds_02.webp" alt="Guilds entry in the event menu" width="258" height="43"></p>
<p>The page lists the guilds of the event with their members, and has the links to create a new guild and to see pending invites:</p>
<p><img src="/static/tutorials/217_guilds_03.webp" alt="Guild list for participants" width="992" height="486"></p>
<p>Any participant with a character can create a guild, until the maximum number is reached. In the creation form they choose which of their characters founds the guild (and becomes its first admin), then set:</p>
<p><img src="/static/tutorials/217_guilds_04.webp" alt="Create a guild" width="992" height="656"></p>
<ul>
<li><strong>Name</strong>, <strong>Presentation</strong> (visible to everyone) and <strong>Text</strong> (visible to members only).</li>
<li><strong>Guild cover</strong>: the guild logo.</li>
<li><strong>Secret</strong>: if checked, the guild is not shown in the guild list or in the gallery; only its members see it.</li>
</ul>
<hr>
<h2>Members and roles</h2>
<p>The guild page shows its presentation and members. Admins are marked with a star.</p>
<p><img src="/static/tutorials/217_guilds_05.webp" alt="Guild page for its admin" width="992" height="1477"></p>
<p>Guild admins can:</p>
<ul>
<li><strong>Invite</strong> a character playing in the event, from the invite box at the bottom of the page;</li>
<li><strong>Promote to admin</strong> a member, or <strong>Remove admin</strong> from an admin;</li>
<li><strong>Remove from guild</strong> a member;</li>
<li><strong>Edit</strong> the guild details.</li>
</ul>
<p>Invited participants find the invite in <strong>My pending invites</strong>, where they can accept or decline it:</p>
<p><img src="/static/tutorials/217_guilds_06.webp" alt="Pending guild invites" width="992" height="406"></p>
<p>The guild admins are notified by email when an invite is accepted or declined. A member can leave the guild at any time; the last admin must promote another member before leaving.</p>
<p><em>Note: invites can only be accepted while the guild is below its maximum number of members.</em></p>
<hr>
<h2>Guilds in the gallery</h2>
<p>Non-secret guilds are shown in the character gallery, each with its members:</p>
<p><img src="/static/tutorials/217_guilds_07.webp" alt="Guild in the character gallery" width="983" height="313"></p>
<hr>
<h2>Managing guilds</h2>
<p>Organizers can see and edit every guild, including the secret ones, in <a href="https://larpmanager.com/redirect/event/manage/guilds/" target="_blank" rel="noopener"><strong>Event &gt; Guilds</strong></a>:</p>
<p><img src="/static/tutorials/217_guilds_08.webp" alt="Guilds for the organizers" width="992" height="336"></p>
<p>To add custom fields to guilds, go to <a href="https://larpmanager.com/redirect/event/manage/writing/guild/form/" target="_blank" rel="noopener"><strong>Event &gt; Sheet</strong></a> (see the <a href="https://larpmanager.com/tutorials/character-form/" target="_blank" rel="noopener"><em><strong>Character Sheet</strong></em></a> tutorial).</p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/factions/" target="_blank" rel="noopener"><em><strong>Factions</strong></em></a>, <a href="https://larpmanager.com/tutorials/characters/" target="_blank" rel="noopener"><em><strong>Characters</strong></em></a></em></p>', 217);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (24, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Plots', 'plots', '<p>Plots are storylines that involve several characters: each plot has a shared text, and a personal role for every character in it. This tutorial explains how to create plots, assign characters to them, and what participants see.</p>
<hr>
<h2>Creating plots</h2>
<p>To manage storylines that span across multiple characters, enable the <a href="https://larpmanager.com/redirect/event/manage/features/plot/on/" target="_blank" rel="noopener"><strong>Plots</strong></a> feature.</p>
<p>Then, in <a href="https://larpmanager.com/redirect/event/manage/plots/" target="_blank" rel="noopener"><strong>Event &gt; Plots</strong></a>, click on "New" to create a new one:</p>
<p><img src="/static/tutorials/220_plots_01.webp" alt="New plot form" width="1260" height="807"></p>
<ul>
<li><strong>Name</strong>: name of the plot, visible to the characters involved.</li>
<li><strong>Concept</strong>: internal notes for the staff, not visible to participants.</li>
<li><strong>Text</strong>: the shared storyline, shown to all the characters involved.</li>
<li><strong>Characters</strong>: the characters taking part in the storyline. When you add a character, a new row appears where you write the personal role of that character:</li>
</ul>
<p><img src="/static/tutorials/220_plots_02.webp" alt="Plot with a character role" width="1260" height="744"></p>
<hr>
<h2>Roles in the character form</h2>
<p>You can also edit the role of a character in a plot from the character edit page:</p>
<p><img src="/static/tutorials/220_plots_03.webp" alt="Plot role in the character form" width="1260" height="440"></p>
<hr>
<h2>Participant view</h2>
<p>Once the character is assigned to a participant, the text of each plot and the personal role are shown in the character page:</p>
<p><img src="/static/tutorials/220_plots_04.webp" alt="Plot shown in the character sheet" width="983" height="194"></p>

<hr>
<h2>Plot list and statistics</h2>
<p><a href="https://larpmanager.com/redirect/event/manage/plots/" target="_blank" rel="noopener"><strong>Event &gt; Plots</strong></a> lists all the plots of the event. Use the buttons above the table to show more columns, such as the characters involved and their number.</p>
<p>In <a href="https://larpmanager.com/redirect/event/manage/config/writing/" target="_blank" rel="noopener"><strong>Event &gt; Configuration &gt; Characters</strong></a>, enable <strong>Unimportant</strong> to mark minor roles: start the personal role text with <code>$unimportant</code>, and a new column counts only the important characters of each plot. The marker is never shown to participants.</p>
<hr>
<h2>Custom fields and tracking</h2>
<p>You can add custom fields to plots in <a href="https://larpmanager.com/redirect/event/manage/writing/plot/form/" target="_blank" rel="noopener"><strong>Event &gt; Sheet</strong></a>, as for characters (see <a href="https://larpmanager.com/tutorials/character-form/" target="_blank" rel="noopener"><em><strong>Character Sheet</strong></em></a>). There you can also add the <strong>Progress</strong> and <strong>Assigned</strong> fields, to track the writing status of each plot and the staff member responsible for it.</p>
<hr>
<h2>Visibility</h2>
<p>Plots are shown to a participant only once a character is assigned to them. If you control which elements participants can see, select <strong>Plots</strong> among the elements shown in <a href="https://larpmanager.com/redirect/event/manage/event/" target="_blank" rel="noopener"><strong>Event &gt; Event</strong></a> (see <a href="https://larpmanager.com/tutorials/characters/#characters-configuration" target="_blank" rel="noopener"><em><strong>Characters</strong></em></a>).</p>
<p>To read all the plots and characters of the event in one place, use <a href="https://larpmanager.com/redirect/event/manage/reading/" target="_blank" rel="noopener"><strong>Event &gt; Reading</strong></a>.</p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/characters/" target="_blank" rel="noopener"><em><strong>Characters</strong></em></a>, <a href="https://larpmanager.com/tutorials/factions/" target="_blank" rel="noopener"><em><strong>Factions</strong></em></a>, <a href="https://larpmanager.com/tutorials/writing-extras/" target="_blank" rel="noopener"><em><strong>Writing Extras</strong></em></a></em></p>', 220);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (25, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Writing Extras', 'writing-extras', '<p>Besides characters, plots and factions, LarpManager can manage other writing elements for your event: prologues, handouts, speed larp scenes and workshops. This tutorial covers each of them.</p>
<hr>
<h2>Prologues</h2>
<p><em>Short introductory texts, one for each act or moment of the event, given to the characters involved.</em> To use it, activate the <a href="https://larpmanager.com/redirect/event/manage/features/prologue/on/" target="_blank" rel="noopener"><strong>Prologues</strong></a> feature.</p>
<p>First create at least one prologue type (for example "Act I") in <a href="https://larpmanager.com/redirect/event/manage/prologue_types/" target="_blank" rel="noopener"><strong>Event &gt; Prologue types</strong></a>:</p>
<p><img src="/static/tutorials/223_writing-extras_01.webp" alt="New prologue type" width="1260" height="97"></p>
<p>Then create the prologues in <a href="https://larpmanager.com/redirect/event/manage/prologues/" target="_blank" rel="noopener"><strong>Event &gt; Prologues</strong></a>:</p>
<p><img src="/static/tutorials/223_writing-extras_02.webp" alt="New prologue" width="1260" height="716"></p>
<ul>
<li><strong>Typ</strong>: the prologue type.</li>
<li><strong>Name</strong>: name of the prologue.</li>
<li><strong>Text</strong>: the prologue itself.</li>
<li><strong>Characters</strong>: the characters who receive it.</li>
</ul>
<p>Participants read their prologues in their character page.</p>
<hr>
<h2>Handouts</h2>
<p><em>Documents about a plot or the lore, printed as PDF with your own layout.</em> To use it, activate the <a href="https://larpmanager.com/redirect/event/manage/features/handout/on/" target="_blank" rel="noopener"><strong>Handout</strong></a> feature.</p>
<p>First create a handout model in <a href="https://larpmanager.com/redirect/event/manage/handout_templates/" target="_blank" rel="noopener"><strong>Event &gt; Handout Models</strong></a>: its <strong>CSS</strong> defines the page layout (size, margins, background). The instructions shown in the form explain the options.</p>
<p><img src="/static/tutorials/223_writing-extras_03.webp" alt="New handout model" width="1260" height="262"></p>
<p>Then create the handouts in <a href="https://larpmanager.com/redirect/event/manage/handouts/" target="_blank" rel="noopener"><strong>Event &gt; Handouts</strong></a>, choosing their model:</p>
<p><img src="/static/tutorials/223_writing-extras_04.webp" alt="New handout" width="1260" height="302"></p>
<p>From the list you can download each handout as a PDF, ready to print.</p>
<hr>
<h2>Speed larp</h2>
<p><em>Short scenes played before the event, to let participants get to know their characters.</em> To use it, activate the <a href="https://larpmanager.com/redirect/event/manage/features/speedlarp/on/" target="_blank" rel="noopener"><strong>Speed Larp</strong></a> feature.</p>
<p>Go to <a href="https://larpmanager.com/redirect/event/manage/speedlarps/" target="_blank" rel="noopener"><strong>Event &gt; Speed larp</strong></a> and click "New":</p>
<p><img src="/static/tutorials/223_writing-extras_05.webp" alt="New speed larp scene" width="1260" height="716"></p>
<ul>
<li><strong>Name</strong>: name of the scene.</li>
<li><strong>Text</strong>: the scene description.</li>
<li><strong>Typ</strong>: the round of the scene: scenes of the same round are played at the same time.</li>
<li><strong>Station</strong>: where the scene takes place.</li>
<li><strong>Characters</strong>: the characters in the scene.</li>
</ul>
<p>Participants see their scenes in their character page. If the <strong>Check</strong> option is enabled, <a href="https://larpmanager.com/redirect/event/manage/check/" target="_blank" rel="noopener"><strong>Event &gt; Check</strong></a> reports characters placed in two scenes of the same round, or missing from a round.</p>
<hr>
<h2>Workshops</h2>
<p><em>Quiz-style questions that participants answer before the event, to check they know the rules or the setting.</em> To use it, activate the <a href="https://larpmanager.com/redirect/event/manage/features/workshop/on/" target="_blank" rel="noopener"><strong>Workshop</strong></a> feature.</p>
<p>Create the modules in <a href="https://larpmanager.com/redirect/event/manage/workshops/modules/" target="_blank" rel="noopener"><strong>Event &gt; Modules</strong></a>, then their questions in <a href="https://larpmanager.com/redirect/event/manage/workshops/questions/" target="_blank" rel="noopener"><strong>Event &gt; Questions</strong></a> and the possible answers, marking the correct ones, in <a href="https://larpmanager.com/redirect/event/manage/workshops/options/" target="_blank" rel="noopener"><strong>Event &gt; Answers</strong></a>:</p>
<p><img src="/static/tutorials/223_writing-extras_06.webp" alt="New workshop module" width="1260" height="164"></p>
<p>Participants find a new entry, <strong>Workshop</strong>, in the event menu. <a href="https://larpmanager.com/redirect/event/manage/workshops/" target="_blank" rel="noopener"><strong>Event &gt; Workshops</strong></a> shows which participants have not yet completed all the modules in the last year.</p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/plots/" target="_blank" rel="noopener"><em><strong>Plots</strong></em></a>, <a href="https://larpmanager.com/tutorials/characters/" target="_blank" rel="noopener"><em><strong>Characters</strong></em></a>, <a href="https://larpmanager.com/tutorials/event-tools/" target="_blank" rel="noopener"><em><strong>Event Tools</strong></em></a></em></p>', 223);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (26, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Matchmaker', 'matchmaker', '<p>The matchmaker collects what each participant would like to play, before characters are assigned: the kind of role, the factions they prefer, how much intrigue or combat they want. This tutorial explains how to set up the matchmaker questions and review the answers.</p>
<hr>
<h2>Activating matchmaker</h2>
<p>To use it, activate the <a href="https://larpmanager.com/redirect/event/manage/features/matchmaker/on/" target="_blank" rel="noopener"><strong>Matchmaker</strong></a> feature.</p>
<p>A new page, <a href="https://larpmanager.com/redirect/event/manage/matchmaker/" target="_blank" rel="noopener"><strong>Event &gt; Matchmaker answers</strong></a>, becomes available in the event dashboard, and a new form type, <strong>Matchmaker</strong>, is added to <a href="https://larpmanager.com/redirect/event/manage/form/matchmaker/" target="_blank" rel="noopener"><strong>Event &gt; Form</strong></a>.</p>
<hr>
<h2>Matchmaker questions</h2>
<p>Go to <a href="https://larpmanager.com/redirect/event/manage/form/matchmaker/" target="_blank" rel="noopener"><strong>Event &gt; Form</strong></a> and select <strong>Matchmaker</strong> next to "Configure form". Click "New" to add a question.</p>
<p><img src="/static/tutorials/225_matchmaker_01.webp" alt="Matchmaker questions in the form page" width="992" height="563"></p>
<p>Matchmaker questions work like the questions of the registration form: single-line and multi-line text, single and multiple choice, and Likert scale (see the <a href="https://larpmanager.com/tutorials/registration-form/" target="_blank" rel="noopener"><em><strong>Registration Form</strong></em></a> tutorial).</p>
<p>A question of type <strong>Faction preference</strong> is created automatically: participants drag the factions of the event into their order of preference. This type is available only in the matchmaker form, once.</p>
<hr>
<h2>Participant view</h2>
<p>Every participant with a confirmed registration finds a new entry, <strong>Matchmaker</strong>, in the event menu:</p>
<p><img src="/static/tutorials/225_matchmaker_02.webp" alt="Matchmaker entry in the event menu" width="258" height="43"></p>
<p>The page shows the matchmaker questions. Answers are kept as a draft while the participant types, and are submitted by clicking "Save". Participants can come back later to change their answers.</p>
<p><img src="/static/tutorials/225_matchmaker_03.webp" alt="Matchmaker form for participants" width="992" height="824"></p>
<hr>
<h2>Reviewing the answers</h2>
<p>Go to <a href="https://larpmanager.com/redirect/event/manage/matchmaker/" target="_blank" rel="noopener"><strong>Event &gt; Matchmaker answers</strong></a>. The table lists every participant who answered, with a column for each question; faction preferences are shown as a ranked list.</p>
<p><img src="/static/tutorials/225_matchmaker_04.webp" alt="Matchmaker answers" width="992" height="432"></p>
<p>Below the table, each Likert scale question has a chart with the number of participants for each value:</p>
<p><img src="/static/tutorials/225_matchmaker_05.webp" alt="Distribution of a rating question" width="983" height="260"></p>
<p>Use these answers to write or assign the characters; for an assignment based on character preferences, see the <a href="https://larpmanager.com/tutorials/casting/" target="_blank" rel="noopener"><em><strong>Casting</strong></em></a> tutorial.</p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/casting/" target="_blank" rel="noopener"><em><strong>Casting</strong></em></a>, <a href="https://larpmanager.com/tutorials/registration-form/" target="_blank" rel="noopener"><em><strong>Registration Form</strong></em></a>, <a href="https://larpmanager.com/tutorials/factions/" target="_blank" rel="noopener"><em><strong>Factions</strong></em></a></em></p>', 225);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (27, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Casting', 'casting', '<p>The <em><strong>Casting</strong></em> feature lets participants express preferences for which characters they would like to play, then runs an algorithm to assign characters automatically based on those preferences. This tutorial covers setup, the participant preference flow, and how to run and review the assignment.</p>
<h2>Casting algorithm</h2>
<p>To manage participant preferences on characters and perform assignment with an algorithm, activate the <a href="https://larpmanager.com/redirect/event/manage/features/casting/on/" target="_blank" rel="noopener"><strong>Casting algorithm</strong></a> feature.</p>
<p>In <a href="https://larpmanager.com/redirect/event/manage/config/casting/" target="_blank" rel="noopener"><strong>Event &gt; Configuration &gt; Casting</strong></a>, set those values:</p>
<p><img src="/static/tutorials/230_casting_01.webp" alt="Casting configuration" width="983" height="680"></p>
<p><img src="/static/tutorials/230_casting_02.webp" alt="Casting priorities and visibility" width="983" height="567"></p>
<hr>
<p>When a participant is signed up and has fewer assigned characters than the <strong>Assignments</strong> value, an additional navigation bar button will appear, allowing them to request or select more characters.</p>
<p><img src="/static/tutorials/230_casting_03.webp" alt="Character preferences for participants" width="992" height="716"></p>
<p>For each preference, the participant first selects a faction on the left, then a character on the right.</p>
<p>Once the number of preferences entered is between the defined <strong>Minimum Preferences</strong> and <strong>Maximum Preferences</strong>, they can be submitted.</p>
<p><em>Participants may update their preferences at any time before the character assignment.</em></p>
<hr>
<p>Recommended number of preferences:</p>
<ul>
<li><strong>3 - 4</strong> if the event has fewer than 30 characters</li>
<li><strong>5 - 6</strong> if between 30 and 50 characters</li>
<li><strong>7 - 8</strong> if more than 50 characters</li>
</ul><hr>
<p>If <strong>Show Statistics</strong> is checked, each unassigned character will display a graph showing how many participants have selected them as a preference.</p>
<p><img src="/static/tutorials/230_casting_04.webp" alt="Preference statistics on a character" width="992" height="576"></p>
<hr>
<h2>Casting</h2>
<p>When ready to assign characters, go to <a href="https://larpmanager.com/redirect/event/manage/casting/" target="_blank" rel="noopener"><strong>Event &gt; Casting</strong></a>.</p>
<p>At the top of the page, you''ll see a summary indicating if any participants have not submitted preferences or if any characters have received no preferences.</p>
<p><em>Note: The number of characters available for assignment is calculated as all characters minus those that received no preferences. If this number exceeds the number of participants who submitted preferences, the algorithm will fail.</em></p>
<hr>
<p>You can select the list of ticket types, and the status of payment. If you have activated the Factions, you''ll also find a selection on the characters to make available for assignment:</p>
<p><img src="/static/tutorials/230_casting_05.webp" alt="Casting filters" width="992" height="378"></p>
<p>The list of participant preference is shown in the middle of the page:</p>
<p><img src="/static/tutorials/230_casting_06.webp" alt="Participant preferences" width="983" height="623"></p>
<p>The first column contains a selector to choose which participants to include in the assignment.<br>The second column shows the assignment priority based on the ticket selected by the participant.<br>The following columns display the list of each participant''s character preferences.</p>
<hr>
<p>By default, all preferences are active in the algorithm (<strong>YES</strong>). You can block a preference by clicking it, changing it to <strong>NO</strong>, which excludes it from consideration. Clicking again will reactivate it.</p>

<hr>
<p>Clicking <strong>"Start Algorithm"</strong> runs a simulation of the assignment based on the current participant selections, preferences, and configuration data.</p>
<p><img src="/static/tutorials/230_casting_08.webp" alt="Start the algorithm" width="983" height="68"></p>
<p>At then end of the page, you''ll see the results of the simulation:</p>
<p><img src="/static/tutorials/230_casting_09.webp" alt="Proposed assignment" width="983" height="137"></p>
<p>Review the simulation results carefully. When confirmed, click <strong>"Upload"</strong> to finalize and assign the characters.</p>
<hr>
<p>If <strong>"Field for exclusions"</strong> is selected, an additional field will appear in the participant''s preferences, allowing them to explicitly exclude certain themes.</p>
<p><img src="/static/tutorials/230_casting_10.webp" alt="Elements to avoid" width="947" height="99"></p>
<p>This information will then be shown in the casting list, under the column "Avoid".</p>

<p>To make an informed decision on which character preferences to block for each participant, use the available data and distribution indicators.</p>
<hr>
<p>For the algorithm to find a solution, preferences must be reasonably distributed among characters. If too many participants select the same few characters, the algorithm may fail.</p>
<p>In such cases, set a value for <strong>"Additional Preferences"</strong> in the configuration. This will assign each participant a random set of preferences from characters who received none, improving feasibility - but may result in some participants being assigned characters they did not choose.</p>
<hr>
<h2>Priority</h2>
<p>You can assign a priority to each ticket type, giving participants with certain tickets a higher chance of receiving their preferred characters.</p>
<p>A new <strong>Casting priority</strong> field is now available in the ticket edit form.</p>

<p>If you can additionally tweak how the algorithm favours participants that:</p>
<ul>
<li>Signed up earlier (<strong>Registration Priority</strong> option)</li>
<li>Paid in full earlier (<strong>Payment Priority</strong> option)</li>
</ul>
<p>Both this options can be set: 0 (default disabled, not taken into consideration), 1 (normal priority), 10 (strong priority)</p>
<hr>
<h2>Mirror</h2>
<p>If you want participants to select preferences while keeping characters secret, use the <strong>Mirror</strong> feature.</p>
<p>When this option is enabled, a new field, <strong>Mirror</strong>, appears on the character edit form, allowing you to define the mirrored version of the character that is shown to participants instead of the actual character.</p>

<p>Example: in your game, the baker is secretly the killer, but you want to hide this from participants. First create the public-facing character <strong>"The Baker"</strong>, and then create another character <strong>"The Killer"</strong>, and in its Mirror field, select <strong>"The Baker"</strong>.</p>
<p>Participants who want to play the antagonist will submit preferences for <strong>"The Killer"</strong>. If the casting algorithm assigns a participant to <strong>"The Killer"</strong>, they will actually be assigned <strong>"The Baker"</strong>.</p>
<p><em>Direct preferences for <strong>"The Baker"</strong> are ignored, preventing the character from being assigned to participants who did not explicitly choose to play the secret role.</em></p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/matchmaker/" target="_blank" rel="noopener"><em><strong>Matchmaker</strong></em></a>, <a href="https://larpmanager.com/tutorials/quests/" target="_blank" rel="noopener"><em><strong>Quests and Traits</strong></em></a>, <a href="https://larpmanager.com/tutorials/characters/" target="_blank" rel="noopener"><em><strong>Characters</strong></em></a>, <a href="https://larpmanager.com/tutorials/manage-ticket/" target="_blank" rel="noopener"><em><strong>Registration Ticket</strong></em></a></em></p>', 230);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (28, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Quests and Traits', 'quests', '<p>Quests and traits let you write parts of character sheets as reusable pieces, which participants can choose and which are then assigned to characters. This tutorial explains the three concepts, how to create them, and how they are assigned.</p>
<hr>
<h2>Key concepts</h2>
<p>To use them, activate the <a href="https://larpmanager.com/redirect/event/manage/features/questbuilder/on/" target="_blank" rel="noopener"><strong>Quests and Traits</strong></a> feature. There are three key concepts:</p>
<ul>
<li><strong>Trait</strong>: a single text element assigned to a character. Each trait belongs to a quest (e.g., roles in a heist: <em>Mind, Muscle, Face</em>).</li>
<li><strong>Quest</strong>: a collection of traits sharing a common theme (e.g., <em>Heist</em>). Each quest belongs to a quest type.</li>
<li><strong>Quest type</strong>: a grouping of quests within the same category (e.g., <em>Past Occupations</em>).</li>
</ul>
<p><em>Each character can have at most one trait for each quest type.</em></p>
<hr>
<h2>Creating quest types, quests and traits</h2>
<p>To create a quest type, go to <a href="https://larpmanager.com/redirect/event/manage/quest_types/" target="_blank" rel="noopener"><strong>Event &gt; Quest type</strong></a> and click "New":</p>
<p><img src="/static/tutorials/240_quests_01.webp" alt="New quest type" width="1260" height="222"></p>
<p>To create a quest, go to <a href="https://larpmanager.com/redirect/event/manage/quests/" target="_blank" rel="noopener"><strong>Event &gt; Quest</strong></a> and click "New":</p>
<p><img src="/static/tutorials/240_quests_02.webp" alt="New quest" width="1260" height="466"></p>
<ul>
<li><strong>Type</strong>: the quest type;</li>
<li><strong>Name</strong>: name of the quest;</li>
<li><strong>Presentation</strong>: shown to all participants;</li>
<li><strong>Text</strong>: visible only to characters assigned a trait of this quest.</li>
</ul>
<p>To create a trait, go to <a href="https://larpmanager.com/redirect/event/manage/traits/" target="_blank" rel="noopener"><strong>Event &gt; Traits</strong></a> and click "New":</p>
<p><img src="/static/tutorials/240_quests_03.webp" alt="New trait" width="1260" height="466"></p>
<ul>
<li><strong>Quest</strong>: the quest of the trait;</li>
<li><strong>Name</strong>: name of the trait;</li>
<li><strong>Presentation</strong>: shown to all participants;</li>
<li><strong>Text</strong>: visible only to characters assigned this trait.</li>
</ul>
<hr>
<h2>Referencing other traits</h2>
<p>When writing a trait, you can reference other traits with their number, in the format <code>#&lt;Number&gt;</code>. Once the traits are assigned, the reference is replaced with the name of the character who received that trait.</p>
<p>For example, if the <strong>Muscle</strong> trait has number 2, writing <code>#2</code> in the <strong>Mind</strong> trait shows the participant with the Mind trait the name of the character with the Muscle trait.</p>
<hr>
<h2>Participant view</h2>
<p>Participants find a new entry, <strong>Quest</strong>, in the event menu, listing the quests:</p>
<p><img src="/static/tutorials/240_quests_04.webp" alt="Quests for participants" width="992" height="361"></p>
<p>Clicking a quest shows its presentation and traits:</p>
<p><img src="/static/tutorials/240_quests_05.webp" alt="Quest with its traits" width="992" height="579"></p>
<hr>
<h2>Assigning traits</h2>
<p>If the <a href="https://larpmanager.com/redirect/event/manage/features/casting/on/" target="_blank" rel="noopener"><strong>Casting algorithm</strong></a> feature is active (see the <a href="https://larpmanager.com/tutorials/casting/" target="_blank" rel="noopener"><em><strong>Casting</strong></em></a> tutorial), participants choose the traits they prefer for each quest type:</p>
<p><img src="/static/tutorials/240_quests_06.webp" alt="Trait preferences" width="992" height="656"></p>
<p>You then assign them in <a href="https://larpmanager.com/redirect/event/manage/casting/" target="_blank" rel="noopener"><strong>Event &gt; Casting</strong></a>, selecting the quest type at the top:</p>
<p><img src="/static/tutorials/240_quests_07.webp" alt="Trait preferences for the organizers" width="983" height="623"></p>
<p>You can also assign a trait directly when editing a registration in <a href="https://larpmanager.com/redirect/event/manage/registrations/" target="_blank" rel="noopener"><strong>Event &gt; Registrations</strong></a>:</p>
<p><img src="/static/tutorials/240_quests_08.webp" alt="Assign a trait from the registration" width="1260" height="307"></p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/casting/" target="_blank" rel="noopener"><em><strong>Casting</strong></em></a>, <a href="https://larpmanager.com/tutorials/characters/" target="_blank" rel="noopener"><em><strong>Characters</strong></em></a></em></p>', 240);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (29, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Deadlines', 'deadlines', '<p>The Deadlines feature lists the participants who are late on a registration step, such as paying, completing their profile or sending their casting preferences, and emails the organizers a periodic summary. The Reminder feature sends automatic emails to the participants themselves. This tutorial covers both.</p>
<hr>
<h2>Activating deadlines</h2>
<p>Activate the <a href="https://larpmanager.com/redirect/manage/features/deadlines/on/" target="_blank" rel="noopener"><strong>Deadlines</strong></a> feature. It applies to every event of the organization.</p>
<p>In <a href="https://larpmanager.com/redirect/manage/config/deadlines/" target="_blank" rel="noopener"><strong>Organization &gt; Configuration &gt; Deadline</strong></a>, set the following values:</p>
<p><img src="/static/tutorials/250_deadlines_01.webp" alt="Deadline configuration" width="983" height="344"></p>
<ul>
<li><strong>Tolerance</strong>: number of days of delay after which a participant is marked for cancellation (default 30 days).</li>
<li><strong>Frequency</strong>: how often, in days, the organizers of each event receive an email summary of the missed deadlines. Leave it empty to send no summary.</li>
</ul>
<hr>
<h2>Reviewing missed deadlines</h2>
<p>For each event, go to <a href="https://larpmanager.com/redirect/event/manage/deadlines/" target="_blank" rel="noopener"><strong>Event &gt; Deadlines</strong></a>. Each row groups the participants with the same problem:</p>
<p><img src="/static/tutorials/250_deadlines_02.webp" alt="Missed deadlines of the event" width="992" height="521"></p>
<ul>
<li><strong>Problem</strong>: the missed deadline.</li>
<li><strong>Action</strong>: what to do, with a link to the page the participants need to complete. Copy it and send it to them.</li>
<li><strong>Number</strong>: how many participants are affected.</li>
<li><strong>Names</strong> and <strong>Email</strong>: who they are and how to contact them.</li>
</ul>
<p>Rows starting with "Cancellation for" list the participants who exceeded the <strong>Tolerance</strong>. LarpManager never cancels a registration by itself: review them and cancel the registrations manually from <a href="https://larpmanager.com/redirect/event/manage/registrations/" target="_blank" rel="noopener"><strong>Event &gt; Registrations</strong></a>.</p>
<p>To check all upcoming sessions at once, go to <a href="https://larpmanager.com/redirect/manage/deadlines/" target="_blank" rel="noopener"><strong>Organization &gt; Deadlines</strong></a>. It shows the same table for every session, one below the other.</p>
<hr>
<h2>Monitored deadlines</h2>
<p>Only confirmed registrations are checked: cancelled registrations and waiting-list tickets are skipped. The checks depend on the active features:</p>
<ul>
<li><strong>Delay in payment</strong>: a payment deadline has passed and the amount is still due. Deadlines come from fixed instalments or dynamic rates (see the <a href="https://larpmanager.com/tutorials/registration-accounting/" target="_blank" rel="noopener"><em><strong>Registration Accounting</strong></em></a> tutorial). Past the tolerance, it becomes a cancellation. Requires the <a href="https://larpmanager.com/redirect/manage/features/payment/on/" target="_blank" rel="noopener"><strong>Payments</strong></a> feature.</li>
<li><strong>Delay in profile</strong>: the user has not completed the personal data in their profile. It becomes a cancellation when the session starts within the tolerance days. Checked only when Membership is not active.</li>
<li><strong>Membership registration overdue</strong>: the user has not submitted the membership request. It becomes a cancellation when the registration is older than the tolerance days. Requires the <a href="https://larpmanager.com/redirect/manage/features/membership/on/" target="_blank" rel="noopener"><strong>Membership</strong></a> feature.</li>
<li><strong>Delay in yearly membership fee</strong>: the user is an accepted member, but has not paid the annual fee for the year of the session. It becomes a cancellation when the session starts within the tolerance days. Requires the <strong>Membership</strong> feature with an annual fee set.</li>
<li><strong>Missing casting preferences</strong>: the participant has neither sent the casting preferences nor received a character. Requires the <a href="https://larpmanager.com/redirect/event/manage/features/casting/on/" target="_blank" rel="noopener"><strong>Casting algorithm</strong></a> feature.</li>
<li><strong>Character not yet created</strong> and <strong>Character not yet confirmed</strong>: the participant has created fewer characters than required, or has characters still waiting for approval. Requires the <a href="https://larpmanager.com/redirect/event/manage/features/user_character/on/" target="_blank" rel="noopener"><strong>Character creation</strong></a> feature.</li>
<li><strong>Debrief not yet compiled</strong>: after the session ends, the participant has not answered the debrief questions. Requires the <a href="https://larpmanager.com/redirect/event/manage/features/debrief/on/" target="_blank" rel="noopener"><strong>Debrief</strong></a> feature.</li>
</ul>
<p><em>Note: the casting, character and debrief checks skip staff and NPC tickets. The membership and profile checks also cover the users with an event role, even when they are not registered.</em></p>
<hr>
<h2>Organizer summary</h2>
<p>When <strong>Frequency</strong> is set, LarpManager emails the event organizers a summary with the same rows as <a href="https://larpmanager.com/redirect/event/manage/deadlines/" target="_blank" rel="noopener"><strong>Event &gt; Deadlines</strong></a>. For example, with a frequency of 7 days, the summary arrives once a week until the session starts.</p>
<p>The summary is not sent when no deadline is missed, on public holidays, or once the session ended more than a week ago.</p>
<hr>
<h2>Reminders</h2>
<p>To send automatic reminders to the participants, activate the <a href="https://larpmanager.com/redirect/manage/features/remind/on/" target="_blank" rel="noopener"><strong>Reminder</strong></a> feature.</p>
<p>In <a href="https://larpmanager.com/redirect/manage/config/remind/" target="_blank" rel="noopener"><strong>Organization &gt; Configuration &gt; Reminder</strong></a>, set the following values:</p>
<p><img src="/static/tutorials/250_deadlines_03.webp" alt="Reminder configuration" width="983" height="295"></p>
<ul>
<li><strong>Frequency</strong>: how often, in days, each participant receives a reminder, counted from the registration date (default 5 days).</li>
<li><strong>Public Holidays</strong>: if checked, reminders are also sent on public holidays.</li>
</ul>
<p>Each participant receives a reminder for every step still missing:</p>
<ul>
<li><strong>Membership request reminder email</strong>: the membership request has not been submitted (with Membership active).</li>
<li><strong>Membership fee reminder email</strong>: the annual fee has not been paid, and no fee payment is waiting for approval (with Membership active).</li>
<li><strong>Profile completion reminder email</strong>: the personal data in the profile are incomplete.</li>
<li><strong>Character creation reminder email</strong>: the character has not been created or approved yet (with Character creation active).</li>
<li><strong>Payment reminder email</strong>: a payment deadline is close, and no payment is waiting for approval.</li>
</ul>
<p>A payment deadline counts as close when it falls within the days set in <strong>Payment reminder</strong>, in <a href="https://larpmanager.com/redirect/event/manage/config/payment/" target="_blank" rel="noopener"><strong>Event &gt; Configuration &gt; Payments</strong></a> (default 30 days).</p>
<p><em>Note: reminders stop 3 days before the session starts, and are never sent to waiting-list tickets.</em></p>
<hr>
<h2>Customizing reminder texts</h2>
<p>Every reminder has a default text. To replace it, go to <a href="https://larpmanager.com/redirect/manage/texts/" target="_blank" rel="noopener"><strong>Organization &gt; Texts</strong></a>, click "New" and pick the reminder in <strong>Type</strong>, using the names listed above:</p>
<p><img src="/static/tutorials/250_deadlines_04.webp" alt="Reminder text types" width="1260" height="988"></p>
<p>Write the text, select the <strong>Language</strong>, and save. Add one text per language used by your participants.</p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/registration-accounting/" target="_blank" rel="noopener"><em><strong>Registration Accounting</strong></em></a>, <a href="https://larpmanager.com/tutorials/membership/" target="_blank" rel="noopener"><em><strong>Membership</strong></em></a>, <a href="https://larpmanager.com/tutorials/character-creation/" target="_blank" rel="noopener"><em><strong>Character Creation</strong></em></a>, <a href="https://larpmanager.com/tutorials/manage-mails/" target="_blank" rel="noopener"><em><strong>Mail Settings</strong></em></a></em></p>', 250);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (30, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Users', 'users', '<p>This tutorial covers the features for managing participants and users. It explains how to handle in-platform help requests from participants, give the safety and diet teams access to sensitive participant data, enable private messaging between users, manage your newsletter contacts, and allow users to create and operate delegated accounts on behalf of others.</p>
<h2>Help</h2>
<p>To manage participant help requests directly in the platform, activate the <a href="https://larpmanager.com/redirect/manage/features/help/on/" target="_blank" rel="noopener"><strong>Help</strong></a> feature.</p>
<p>Participants will now see a "Need help?" link at the bottom of every page in the interface.</p>

<p>Clicking on "Need help" will open a new page:</p>
<p><img src="/static/tutorials/260_users_02.webp" alt="Help request form" width="992" height="785"></p>
<p>Below they will also see the full list of messages and replies from the staff:</p>
<p><img src="/static/tutorials/260_users_03.webp" alt="Previous help requests" width="983" height="845"></p>
<hr>
<p>To answer, you can use either <a href="https://larpmanager.com/redirect/event/manage/questions/" target="_blank" rel="noopener"><strong>Event &gt; Questions</strong></a> for each event, or <a href="https://larpmanager.com/redirect/manage/questions/" target="_blank" rel="noopener"><strong>Organization &gt; Questions</strong></a> for all of them:</p>
<p><img src="/static/tutorials/260_users_04.webp" alt="Help requests to answer" width="992" height="366"></p>
<p>You can aswer them, or close them if no further actions are needed.</p>
<hr>
<h2>Safety</h2>
<p>If you have selected the "Safety" field in <a href="https://larpmanager.com/redirect/manage/profile/" target="_blank" rel="noopener"><strong>Organization &gt; Profile</strong></a> (see <a href="https://larpmanager.com/tutorials/player-information/#organization-profile" target="_blank" rel="noopener"><em><strong>Organization profile</strong></em></a> in the Personal Data tutorial), a new page <a href="https://larpmanager.com/redirect/event/manage/safety/" target="_blank" rel="noopener"><strong>Event &gt; Safety</strong></a> is available for each event:</p>
<p><img src="/static/tutorials/260_users_05.webp" alt="Safety information" width="992" height="513"></p>
<p>This page can then be shared only with the safety team, so that only they can access this sensitive information.</p>
<hr>
<h2>Diet</h2>
<p>If you have selected the "Diet" field in <a href="https://larpmanager.com/redirect/manage/profile/" target="_blank" rel="noopener"><strong>Organization &gt; Profile</strong></a> (see <a href="https://larpmanager.com/tutorials/player-information/#organization-profile" target="_blank" rel="noopener"><em><strong>Organization profile</strong></em></a> in the Personal Data tutorial), a new page <a href="https://larpmanager.com/redirect/event/manage/diet/" target="_blank" rel="noopener"><strong>Event &gt; Diet</strong></a> is available for each event:</p>
<p><img src="/static/tutorials/260_users_06.webp" alt="Diet information" width="992" height="690"></p>
<p>This page can then be shared only with the food team, so that only they can access this sensitive information.</p>
<hr>
<h2>Chat</h2>
<p>To allow users to safely message each other through the platform, activate the <a href="https://larpmanager.com/redirect/manage/features/chat/on/" target="_blank" rel="noopener"><strong>Chat</strong></a> feature.</p>
<p>In each user profile (reachable clicking of the user in the event gallery), a new link is available:</p>
<p><img src="/static/tutorials/260_users_07.webp" alt="Public profile with the chat link" width="992" height="436"></p>
<p>Clicking on it, another user can send a private message.</p>
<p><em>Note: the messages are directly sent to the user''s emails, without exposing them to the other user.</em></p>
<hr>
<h2>Neswletter</h2>
<p>To manage the list of emails of users that have given permission to share their data with your organization, activate the <a href="https://larpmanager.com/redirect/manage/features/newsletter/on/" target="_blank" rel="noopener"><strong>Newsletter</strong></a> feature.</p>
<p>In <a href="https://larpmanager.com/redirect/manage/newsletter/" target="_blank" rel="noopener"><strong>Organization &gt; Newsletter</strong></a>, you find them, categorized by the preference they have expressed, and their language:</p>
<p><img src="/static/tutorials/260_users_08.webp" alt="Newsletter lists" width="992" height="435"></p>
<p><em>Note: please respect the user''s newsletter subscription preferences when sending messages.</em></p>
<hr>
<h2>Delegated users</h2>
<p>To allow users to manage delegated accounts (for example for friends or for children), activate the <a href="https://larpmanager.com/redirect/manage/features/delegated_members/on/" target="_blank" rel="noopener"><strong>Delegated accounts</strong></a> feature.</p>
<p>Users will now see a new option, "Delegated users", in the user menu.</p>

<p>Going in that link will show a page to manage delegated users:</p>
<p><img src="/static/tutorials/260_users_10.webp" alt="Delegated accounts" width="992" height="552"></p>
<p>They can now create new delegated users; or clicking on "Login", to access the platform with that account, performing registrations, o</p>
<hr>
<p><em>Note: delegated users may later be upgraded to stand-alone users by submitting a request to the platform administrators.</em></p>
<hr>
<h2>Badges</h2>
<p><em>Award badges to users, and show them in a public leaderboard.</em> To use it, activate the <a href="https://larpmanager.com/redirect/manage/features/badge/on/" target="_blank" rel="noopener"><strong>Badge</strong></a> feature.</p>
<p>Go to <a href="https://larpmanager.com/redirect/manage/badges/" target="_blank" rel="noopener"><strong>Organization &gt; Badges</strong></a> and click "New":</p>
<p><img src="/static/tutorials/900_sections_04.webp" alt="New badge" width="1260" height="716"></p>
<ul>
<li><strong>Name</strong>: short name of the badge (with its international version).</li>
<li><strong>Description</strong>: what the badge rewards (with its international version).</li>
<li><strong>Code</strong>: internal code, without spaces or symbols.</li>
<li><strong>Img</strong>: the badge image.</li>
</ul>
<p>Assign the badge to users from its edit page. Users see their badges in their profile, and everyone can see the leaderboard.</p>
<hr>
<h2>Vote</h2>
<p><em>Let members elect the executive committee of your organization online.</em> To use it, activate the <a href="https://larpmanager.com/redirect/manage/features/vote/on/" target="_blank" rel="noopener"><strong>Vote</strong></a> feature.</p>
<p>In <a href="https://larpmanager.com/redirect/manage/config/vote/" target="_blank" rel="noopener"><strong>Organization &gt; Configuration &gt; Voting</strong></a>, set:</p>
<p><img src="/static/tutorials/900_sections_05.webp" alt="Voting configuration" width="983" height="550"></p>
<ul>
<li><strong>Active</strong>: if checked, members can vote.</li>
<li><strong>Candidates</strong>: the users standing for election.</li>
<li><strong>Minimum votes</strong>: the minimum number of candidates each member must choose.</li>
<li><strong>Maximum votes</strong>: the maximum number of candidates each member can choose.</li>
</ul>
<p>While voting is active, members find a link to the vote page in their profile. The results are shown in <a href="https://larpmanager.com/redirect/manage/vote/" target="_blank" rel="noopener"><strong>Organization &gt; Vote</strong></a>.</p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/user-flags/" target="_blank" rel="noopener"><em><strong>User Flags</strong></em></a>, <a href="https://larpmanager.com/tutorials/player-information/" target="_blank" rel="noopener"><em><strong>Personal Data</strong></em></a>, <a href="https://larpmanager.com/tutorials/membership/" target="_blank" rel="noopener"><em><strong>Membership</strong></em></a></em></p>', 260);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (31, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'User Flags', 'user-flags', '<p>User flags are custom yes/no markers that organizers set on users: signed the code of conduct, qualified first aider, volunteer this year. This tutorial explains how to define the flags, set them for each user, and where they are shown.</p>
<hr>
<h2>Activating user flags</h2>
<p>In <a href="https://larpmanager.com/redirect/manage/config/users/" target="_blank" rel="noopener"><strong>Organization &gt; Configuration &gt; Users</strong></a>, enable <strong>User flags</strong>:</p>
<p><img src="/static/tutorials/265_user-flags_01.webp" alt="User flags configuration" width="983" height="292"></p>
<p>Two new pages become available in the organization dashboard: <a href="https://larpmanager.com/redirect/manage/member_flags/" target="_blank" rel="noopener"><strong>Organization &gt; Flags types</strong></a> and <a href="https://larpmanager.com/redirect/manage/members_flags/" target="_blank" rel="noopener"><strong>Organization &gt; User flags</strong></a>.</p>
<hr>
<h2>Flag types</h2>
<p>Go to <a href="https://larpmanager.com/redirect/manage/member_flags/" target="_blank" rel="noopener"><strong>Organization &gt; Flags types</strong></a> and click "New" to define a flag:</p>
<p><img src="/static/tutorials/265_user-flags_02.webp" alt="New user flag" width="1260" height="363"></p>
<ul>
<li><strong>Name</strong>: short name, shown as column header.</li>
<li><strong>Description</strong>: shown as a tooltip on the column header.</li>
<li><strong>Annual</strong>: if enabled, the flag resets every calendar year instead of staying permanent (useful for yearly checks, like a volunteer shift). It cannot be changed after the flag is created.</li>
</ul>
<p><img src="/static/tutorials/265_user-flags_03.webp" alt="Flag types" width="992" height="430"></p>
<hr>
<h2>Setting the flags</h2>
<p>Go to <a href="https://larpmanager.com/redirect/manage/members_flags/" target="_blank" rel="noopener"><strong>Organization &gt; User flags</strong></a>. The table shows every user of the organization, with a column for each flag; use the column filters to find, for example, the users missing a flag.</p>
<p><img src="/static/tutorials/265_user-flags_04.webp" alt="User flags of each user" width="992" height="483"></p>
<p>Click the edit icon on a row to change the flags of that user, then click "Save":</p>
<p><img src="/static/tutorials/265_user-flags_05.webp" alt="Edit the flags of a user" width="916" height="556"></p>
<hr>
<h2>Where flags are shown</h2>
<p>The flags of a user are shown to organizers when they open the participant details from the eye icon in <a href="https://larpmanager.com/redirect/event/manage/registrations/" target="_blank" rel="noopener"><strong>Event &gt; Registrations</strong></a>, and in the pending payments to approve:</p>
<p><img src="/static/tutorials/265_user-flags_06.webp" alt="User flags in the registration details" width="916" height="556"></p>
<p><em>Note: flags are visible only to organizers; users never see them.</em></p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/users/" target="_blank" rel="noopener"><em><strong>Users</strong></em></a>, <a href="https://larpmanager.com/tutorials/membership/" target="_blank" rel="noopener"><em><strong>Membership</strong></em></a></em></p>', 265);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (32, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Membership', 'membership', '<p>The Membership feature implements a formal onboarding process for your organization''s members. Only approved members can pay and participate in the organization''s event. New participants are prompted to download a membership request document pre-filled with their data, sign it, and upload the signed copy for staff approval.</p>
<p>You can also require payment of an annual membership fee, and track the status of every member directly from the registrations of each event.</p>
<h2>Membership</h2>
<p>To implement a formal approval process for members registering for an event, activate the <a href="https://larpmanager.com/redirect/manage/features/membership/on/" target="_blank" rel="noopener"><strong>Membership</strong></a> feature.</p>
<p>Set the values in <a href="https://larpmanager.com/redirect/manage/config/membership/" target="_blank" rel="noopener"><strong>Organization &gt; Configuration &gt; Members</strong></a>:</p>
<p><img src="/static/tutorials/270_membership_01.webp" alt="Membership configuration" width="983" height="585"></p>
<ul>
<li><strong>Age:</strong> Minimum age required for individuals to be eligible as members (can be blank).</li>
<li><strong>Annual Fee:</strong> The yearly membership fee that each member must pay, calculated from the start of the membership year (can be left empty if not present). Participating in any event in a membership year requires the payment of the membership fee; if not paid, it is added to the first payment of event registration for that year.</li>
<li><strong>Start Day:</strong> The calendar day on which the membership year officially begins. Format: DD-MM (e.g., 01-01 for January 1st).</li>
<li><strong>Standalone Payment Window:</strong> Normally users are able to pay the membership fee only if they are signed up for an event in the current membership year. If you wish to allow them a window of time where they can pay the membership fee anyway, set the value here (can be blank).</li>
</ul><hr>
<h2>Membership request template</h2>
<p>You need to set up the membership document template text. Go to <a href="https://larpmanager.com/redirect/manage/texts/" target="_blank" rel="noopener"><strong>Organization &gt; Texts</strong></a>, and you find a new text type:</p>
<p><img src="/static/tutorials/270_membership_02.webp" alt="Membership request template" width="1260" height="837"></p>
<p>Define the template for the membership request document in this field. An example could be:</p>
<hr>
<p><em>I, the undersigned {{ member.surname }} {{ member.name }}, born on {{ member.birth_date }} in {{ member.birth_place }}, residing at {{ member.get_residence }}, holding {{ member.get_document_type_display }} no. {{ member.document }}, phone {{ member.phone_contact }}, email {{ member.user.email }}, hereby request the Board of Directors to be admitted as a member of the Association.</em></p>
<hr>
<p>When an user signs up for their first event of the Organization, the request document will automatically populated with the user''s data. Users will then download the PDF document, only sign it, and upload the signed copy.</p>
<p><img src="/static/tutorials/270_membership_03.webp" alt="Membership request for participants" width="992" height="841"></p>
<hr>
<p>After a confirmation page, the request is then sent to the Board.</p>

<hr>
<p>To review members, go to <a href="https://larpmanager.com/redirect/manage/membership/" target="_blank" rel="noopener"><strong>Organization &gt; Members</strong></a>. The new requests are at the top of the list:</p>
<p><img src="/static/tutorials/270_membership_05.webp" alt="Membership requests to review" width="992" height="536"></p>
<p>Clicking on "Request", you open a page where you can either <strong>Approve</strong> the request, and the user is accepted as new member. At the bottom, you can also <strong>Reject</strong> it (if for example the documentation is not correct). The user will then be able to submit a new request.</p>
<p><img src="/static/tutorials/270_membership_06.webp" alt="Review a membership request" width="992" height="536"></p>
<hr>
<h2>Membership fee</h2>
<p>If you''ve selected a value for the yearly membership fee, each participant of event in the current year is prompted to pay it.</p>
<p>In <a href="https://larpmanager.com/redirect/manage/membership/" target="_blank" rel="noopener"><strong>Organization &gt; Members</strong></a> you can review the users that have already paid it, or you can approve the payments done by wire / freeform.</p>
<p>You can also upload the membership documents for a member, or the receipt of the payment of their membership fee, with the "Upload membership document" and "Upload membership fee" buttons at the top of the list.</p>

<hr>
<p>In <a href="https://larpmanager.com/redirect/event/manage/registrations/" target="_blank" rel="noopener"><strong>Event &gt; Registrations</strong></a> of each event, you''ll also find a column with the membership status:</p>
<p><img src="/static/tutorials/270_membership_08.webp" alt="Membership status in the registrations" width="983" height="301"></p>
<p>The values are:</p>
<ul>
<li><strong>Inactive (E)</strong>: no membership data yet;</li>
<li><strong>Inactive (J)</strong>: the user has agreed to share their data, but has not uploaded a membership request (first step);</li>
<li><strong>Inactive (U)</strong>: the user has uploaded the request, but has not confirmed it (second step);</li>
<li><strong>Review</strong>: the user has confirmed the request, which is waiting for your approval (third step);</li>
<li><strong>Accepted</strong>: the user is a member;</li>
<li><strong>Removed</strong>: the member status has been revoked.</li>
</ul>
<hr>
<h2>Membership deadlines</h2>
<p>If you have also activated the <strong>Deadlines</strong> feature, in <a href="https://larpmanager.com/redirect/manage/deadlines/" target="_blank" rel="noopener"><strong>Organization &gt; Deadlines</strong></a> you find a recap on the users that have not yet submitted the membership request (or paid the annual membership fee, if a values has been set):</p>
<p><img src="/static/tutorials/270_membership_09.webp" alt="Membership deadlines" width="992" height="367"></p>
<h2>Additional texts</h2>
<p>In <a href="https://larpmanager.com/redirect/manage/texts/" target="_blank" rel="noopener"><strong>Organization &gt; Texts</strong></a>, three more text types become available when Membership is active:</p>
<ul>
<li><strong>Association Statute:</strong> Optional text shown at the bottom of the membership page, <em>to already-accepted members</em>. Use it to display the association statute or any information relevant to full members.</li>
<li><strong>Membership request reminder email:</strong> Body of the automated reminder email sent to registered participants who have not yet completed their membership request. If left blank, a built-in default message is used, which includes a direct link to the membership application page.</li>
<li><strong>Membership fee reminder email:</strong> Body of the automated reminder email sent to registered participants who have not yet paid the annual membership fee. If left blank, a built-in default message is used, which includes a link to the payment page and a note about the insurance requirement.</li>
</ul><p><em>Note: the reminder emails are sent automatically by the daily automation task. To configure when they are triggered, see the <a href="https://larpmanager.com/tutorials/deadlines/" target="_blank" rel="noopener"><em><strong>Deadlines</strong></em></a> tutorial.</em></p>
<hr>
<h2>Member detail</h2>
<p>From <a href="https://larpmanager.com/redirect/manage/membership/" target="_blank" rel="noopener"><strong>Organization &gt; Members</strong></a>, clicking on a member''s name opens their detail page. From there you can access two sub-sections:</p>
<ul>
<li><strong>Registrations:</strong> List of all event registrations for that member within the association, with costs and payment status.</li>
<li><strong>Accounting</strong>: Full payment and accounting history for that member within the association (payments, tokens, credits, discounts).</li>
<li><strong>Membership</strong>: Membership status, uploaded request and document, card number and newsletter preference.</li>
</ul>
<hr>
<h2>Membership registry</h2>
<p><a href="https://larpmanager.com/redirect/manage/registry/" target="_blank" rel="noopener"><strong>Organization &gt; Registry</strong></a> lists all accepted members who have been assigned a card number, ordered by card number. It is designed to serve as the official membership register of the association.</p>
<p>To access it, you need the <strong>Registry</strong> permission enabled in <a href="https://larpmanager.com/redirect/manage/roles/" target="_blank" rel="noopener"><strong>Organization &gt; Roles</strong></a>.</p>
<hr>
<h2>Enrollment list</h2>
<p><a href="https://larpmanager.com/redirect/manage/enrolment/" target="_blank" rel="noopener"><strong>Organization &gt; Insurance Data</strong></a> shows the list of members who have paid the annual membership fee for the current year, together with their card number and enrollment date. This list is useful if you have an insurance based on the yearly payment of the membership fee.</p>
<p>To access it, you need the <strong>Insurance Data</strong> permission enabled in <a href="https://larpmanager.com/redirect/manage/roles/" target="_blank" rel="noopener"><strong>Organization &gt; Roles</strong></a>.</p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/users/" target="_blank" rel="noopener"><em><strong>Users</strong></em></a>, <a href="https://larpmanager.com/tutorials/user-flags/" target="_blank" rel="noopener"><em><strong>User Flags</strong></em></a>, <a href="https://larpmanager.com/tutorials/deadlines/" target="_blank" rel="noopener"><em><strong>Deadlines</strong></em></a>, <a href="https://larpmanager.com/tutorials/payments/" target="_blank" rel="noopener"><em><strong>Payments</strong></em></a></em></p>', 270);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (33, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Accounting', 'accounting', '<p>The platform tracks the financial side of every registration automatically. This tutorial covers the accounting views available to participants (personal balance and registration fees) and to organizers (global balance, per-event breakdown, and individual accounting management).</p>
<h2>User accounting</h2>
<p>Each user can access their personal accounting from the "Accounting" entry of the user menu.</p>

<p>This page summarizes any pending payments, if present, and the accounting status of all their registrations.</p>
<p><img src="/static/tutorials/300_accounting_02.webp" alt="Personal accounting" width="992" height="716"></p>
<hr>
<h2>Organization accounting</h2>
<p>To view an overview of the organization''s accounting, go to <a href="https://larpmanager.com/redirect/manage/accounting/" target="_blank" rel="noopener"><strong>Organization &gt; Accounting</strong></a>.</p>
<p><img src="/static/tutorials/300_accounting_03.webp" alt="Organization accounting" width="992" height="716"></p>
<hr>
<p>At the top, you''ll see the<strong> Global Balance</strong>. This reflects the organization''s positive operating margin, based solely on the budgets of events marked as "Completed."</p>
<p>If Tokens or Credits are enabled, this balance assumes that all of them have already been used or refunded.</p>
<p>This is a virtual balance, indicating the available margin for planning organizational expenses.</p>
<hr>
<p>Below that is the <strong>Overall Balance</strong>. This represents the actual amount that should be held across the organization''s bank and financial accounts. To align this with your real financial status when you start using LarpManager, record an Inflow (see below) with the current amount held.</p>
<hr>
<p><em>Note: Additional summary rows will appear if you activate more Accounting features.</em></p>
<hr>
<h2>Event accounting</h2>
<p>To view an overview of an event''s accounting, go to <a href="https://larpmanager.com/redirect/event/manage/accounting/" target="_blank" rel="noopener"><strong>Event &gt; Accounting</strong></a>.</p>
<p><img src="/static/tutorials/300_accounting_04.webp" alt="Event accounting" width="992" height="716"></p>
<p>This overview allows you to monitor actual versus expected income, track payment methods, and calculate net event profitability.</p>
<p>Below you find a breakdown of each accounting type.</p>
<hr>
<h2>Donation</h2>
<p>To allow users to perform voluntary donations to the organization, activate the <a href="https://larpmanager.com/redirect/manage/features/donate/on/" target="_blank" rel="noopener"><strong>Donation</strong></a> feature.</p>
<p>Users can now find a Donate section on their accounting page.</p>
<p><img src="/static/tutorials/300_accounting_05.webp" alt="Donation section of the accounting page" width="947" height="133"></p>
<p>Following their link they can perform the donation, that is recorded as an organization inflow.</p>
<hr>
<h2>Tokens</h2>
<p>To use tokens, activate the <a href="https://larpmanager.com/redirect/manage/features/tokens/on/" target="_blank" rel="noopener"><strong>Tokens</strong></a> feature. Each user will have an associated <em>token balance</em>. The primary function of tokens is to automatically reduce the registration fee when a user signs up for an event - one token per unit of the organization''s configured currency (e.g., 1 token per &euro;1).</p>
<p>LarpManager handles token accounting automatically. This allows the organization to reward participants or collaborators by granting tokens, which they can then use to lower the cost of future event registrations.</p>
<p>To issue tokens to a user, you can add them from <a href="https://larpmanager.com/redirect/event/manage/tokens/" target="_blank" rel="noopener"><strong>Event &gt; Tokens</strong></a> (in which case they are counted as event expenses) or from <a href="https://larpmanager.com/redirect/manage/tokens/" target="_blank" rel="noopener"><strong>Organization &gt; Tokens</strong></a> (in which case they are counted as organizational expenses).</p>
<p>You can also customize the display names in <a href="https://larpmanager.com/redirect/manage/config/tokens/" target="_blank" rel="noopener"><strong>Organization &gt; Configuration &gt; Tokens</strong></a>; the list with the total amounts of tokens for all users is available in <a href="https://larpmanager.com/redirect/manage/accounting/" target="_blank" rel="noopener"><strong>Organization &gt; Accounting</strong></a>.</p>
<hr>
<h2>Credits</h2>
<p>To use credits, activate the <a href="https://larpmanager.com/redirect/manage/features/credits/on/" target="_blank" rel="noopener"><strong>Credits</strong></a> feature. They function similarly to tokens but with a key difference: they represent a real debt the organization owes to the user. Unlike tokens, credits can either be used to reduce event registration fees or be refunded upon request (see below: <em><strong>Refunds</strong></em>).</p>
<p>They can also be used to reimburse collaborators who have incurred expenses while organizing events (see below: <em><strong>Expenses</strong></em>).</p>
<p>To issue credits to a user, you can add them from <a href="https://larpmanager.com/redirect/event/manage/credits/" target="_blank" rel="noopener"><strong>Event &gt; Credits</strong></a> (in which case they are counted as event expenses) or from <a href="https://larpmanager.com/redirect/manage/credits/" target="_blank" rel="noopener"><strong>Organization &gt; Credits</strong></a> (in which case they are counted as organizational expenses).</p>
<p>You can also customize the display names used in <a href="https://larpmanager.com/redirect/manage/config/credits/" target="_blank" rel="noopener"><strong>Organization &gt; Configuration &gt; Credits</strong></a>; the list with the total amounts of credits for all users is available in <a href="https://larpmanager.com/redirect/manage/accounting/" target="_blank" rel="noopener"><strong>Organization &gt; Accounting</strong></a>.</p>
<hr>
<h2>Expenses</h2>
<p>To allow collaborators to upload receipts for event-related expenses and receive reimbursement in Credits, enable the <a href="https://larpmanager.com/redirect/manage/features/expense/on/" target="_blank" rel="noopener"><strong>Expenses</strong></a> feature.</p>
<p>Each staff member can upload these receipts from <a href="https://larpmanager.com/redirect/event/manage/upload_expenses/" target="_blank" rel="noopener"><strong>Event &gt; Upload Expenses</strong></a> by clicking on "New":</p>
<p><img src="/static/tutorials/300_accounting_06.webp" alt="Upload an expense" width="1260" height="378"></p>
<p>Expenses can then be reviewed in <a href="https://larpmanager.com/redirect/event/manage/expenses/" target="_blank" rel="noopener"><strong>Event &gt; Expenses</strong></a>, or globally in <a href="https://larpmanager.com/redirect/manage/expenses/" target="_blank" rel="noopener"><strong>Organization &gt; Expenses</strong></a>:</p>
<p><img src="/static/tutorials/300_accounting_07.webp" alt="Expenses to review" width="992" height="570"></p>
<p>Once approved, an equal amount of <em><strong>Credits</strong></em> is issued to the user.</p>
<hr>
<h2>Collections</h2>
<p>To allow users to start pooled collections to give a gift to another user, enable the <a href="https://larpmanager.com/redirect/manage/features/collection/on/" target="_blank" rel="noopener"><strong>Collections</strong></a> feature.</p>
<p>Users can now find a Collection section on their accounting page:</p>
<p><img src="/static/tutorials/300_accounting_08.webp" alt="Collection section of the accounting page" width="947" height="133"></p>
<p>When a collection is created, a shareable link is provided for inviting other friends to contribute:</p>
<p><img src="/static/tutorials/300_accounting_09.webp" alt="Collection page" width="992" height="409"></p>
<p>When a collection is closed, the amount can be issued as <em><strong>Credits</strong></em> to the recipient from <a href="https://larpmanager.com/redirect/manage/collections/" target="_blank" rel="noopener"><strong>Organization &gt; Collections</strong></a>.</p>
<hr>
<h2>Refunds</h2>
<p>To allow users to request a refund for accumulated <em><strong>Credits</strong></em>, enable the <a href="https://larpmanager.com/redirect/manage/features/refund/on/" target="_blank" rel="noopener"><strong>Refunds</strong></a> feature.</p>
<p>Users can now find a Refund section on their accounting page:</p>
<p><img src="/static/tutorials/300_accounting_10.webp" alt="Credits section of the accounting page" width="947" height="104"></p>
<p>You can then review the requests in the Organization''s Refunds page:</p>
<p><img src="/static/tutorials/300_accounting_11.webp" alt="Refund requests" width="992" height="508"></p>
<p>After completing the payout, click "Done" to mark the refund as reimbursed.</p>
<hr>
<h2>Inflows</h2>
<p>To manage inflows of money beyond participant registration fees, enable the <a href="https://larpmanager.com/redirect/manage/features/inflow/on/" target="_blank" rel="noopener"><strong>Inflows</strong></a> feature.</p>
<p>Inflows can be added either in <a href="https://larpmanager.com/redirect/event/manage/inflows/" target="_blank" rel="noopener"><strong>Event &gt; Inflows</strong></a>, or in <a href="https://larpmanager.com/redirect/manage/inflows/" target="_blank" rel="noopener"><strong>Organization &gt; Inflows</strong></a>:</p>
<p><img src="/static/tutorials/300_accounting_12.webp" alt="New inflow" width="1260" height="461"></p>
<hr>
<h2>Outflows</h2>
<p>To manage outflows of money paid through the organization''s financial accounts, enable the <a href="https://larpmanager.com/redirect/manage/features/outflow/on/" target="_blank" rel="noopener"><strong>Outflows</strong></a> feature.</p>
<p>Outflows can be added either in <a href="https://larpmanager.com/redirect/event/manage/outflows/" target="_blank" rel="noopener"><strong>Event &gt; Outflows</strong></a>, or in <a href="https://larpmanager.com/redirect/manage/outflows/" target="_blank" rel="noopener"><strong>Organization &gt; Outflows</strong></a>:</p>
<p><img src="/static/tutorials/300_accounting_13.webp" alt="New outflow" width="1260" height="581"></p>
<hr>
<h2>Taxes</h2>
<p>To automatically calculate taxes due on received payments, activate the <a href="https://larpmanager.com/redirect/manage/features/vat/on/" target="_blank" rel="noopener"><strong>Taxes</strong></a> feature.</p>
<p>Set the taxes percentage in <a href="https://larpmanager.com/redirect/manage/config/vat/" target="_blank" rel="noopener"><strong>Organization &gt; Configuration &gt; VAT</strong></a>:</p>
<p><img src="/static/tutorials/300_accounting_14.webp" alt="VAT configuration" width="983" height="320"></p>
<p>The taxes due amount is displayed in <a href="https://larpmanager.com/redirect/manage/payments/" target="_blank" rel="noopener"><strong>Organization &gt; Payments</strong></a>:</p>
<p><img src="/static/tutorials/300_accounting_15.webp" alt="Payments with VAT" width="992" height="536"></p>
<hr>
<h2>Verification payments</h2>
<p>In the payment processing system, bank transfers are manually approved by organizers. As an additional verification measure to confirm the arrival of funds, enable the <a href="https://larpmanager.com/redirect/manage/features/verification/on/" target="_blank" rel="noopener"><strong>Verification payments</strong></a> feature.</p>
<p>Now <a href="https://larpmanager.com/redirect/manage/verification/" target="_blank" rel="noopener"><strong>Organization &gt; Verification</strong></a> displays all received bank transfers that have not yet been verified:</p>
<p><img src="/static/tutorials/300_accounting_16.webp" alt="Payment verification" width="992" height="551"></p>
<p>You can upload a CSV file to verify payments in bulk. This payment list can be obtained from your bank or equivalent provider; it must have the payment amount as the first column and the bank transfer reference as the second.</p>
<p><em>(The unique code automatically added by LarpManager to outgoing payments helps identify them during this verification phase)</em></p>
<hr>
<h2>Organization tax</h2>
<p>To automatically set aside a portion of an event''s revenue as organizational self-funding, enable the <a href="https://larpmanager.com/redirect/manage/features/organization_tax/on/" target="_blank" rel="noopener"><strong>Organizational fee</strong></a> feature.</p>
<p>Set the organization tax percentage in <a href="https://larpmanager.com/redirect/manage/config/organization_tax/" target="_blank" rel="noopener"><strong>Organization &gt; Configuration &gt; Organizational fee</strong></a>:</p>
<p><img src="/static/tutorials/300_accounting_17.webp" alt="Organizational fee configuration" width="983" height="223"></p>
<p>In <a href="https://larpmanager.com/redirect/event/manage/accounting/" target="_blank" rel="noopener"><strong>Event &gt; Accounting</strong></a>, a new entry is added for the organization tax calculated amount:</p>
<p><img src="/static/tutorials/300_accounting_18.webp" alt="Event accounting with the organizational fee" width="992" height="376"></p>
<hr>
<h2>Treasurer</h2>
<p><em>Send payment confirmations to your treasurers, instead of to the organizers of each event.</em> To use it, activate the <a href="https://larpmanager.com/redirect/manage/features/treasurer/on/" target="_blank" rel="noopener"><strong>Treasurer</strong></a> feature.</p>
<p>In <a href="https://larpmanager.com/redirect/manage/config/treasurer/" target="_blank" rel="noopener"><strong>Organization &gt; Configuration &gt; Treasury</strong></a>, select the users in <strong>Appointees</strong>; they receive the payment confirmation emails for all events.</p>
<p><img src="/static/tutorials/900_sections_02.webp" alt="Treasury appointees" width="983" height="213"></p>
<hr>
<h2>Accounting tracking</h2>
<p><em>Keep a daily history of your finances.</em> To use it, activate the <a href="https://larpmanager.com/redirect/manage/features/record_acc/on/" target="_blank" rel="noopener"><strong>Accounting tracking</strong></a> feature.</p>
<p>Every day, LarpManager records the financial status of the organization and of each event. The trend graphs are shown in <a href="https://larpmanager.com/redirect/manage/accounting/record/" target="_blank" rel="noopener"><strong>Organization &gt; Historical</strong></a>.</p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/payments/" target="_blank" rel="noopener"><em><strong>Payments</strong></em></a>, <a href="https://larpmanager.com/tutorials/registration-accounting/" target="_blank" rel="noopener"><em><strong>Registration Accounting</strong></em></a>, <a href="https://larpmanager.com/tutorials/italian-associations/" target="_blank" rel="noopener"><em><strong>Italian Associations</strong></em></a></em></p>', 300);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (34, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Check-in', 'checkin', '<p>This tutorial explains how to use Check-in to mark participants as present on-site by scanning their QR code, even without an internet connection. Use it whenever you need a fast, paperless accreditation desk at your event.</p>
<hr>
<h2>Activating check-in</h2>
<p>To use it, activate the <a href="https://larpmanager.com/redirect/event/manage/features/checkin/on/" target="_blank" rel="noopener"><strong>Check-in</strong></a> feature.</p>
<p>A new page, <a href="https://larpmanager.com/redirect/event/manage/checkin/" target="_blank" rel="noopener"><strong>Event &gt; Check-in</strong></a>, becomes available in the event dashboard.</p>
<p><em>Note: to let other staff members use it, assign them the <strong>Check-in</strong> permission in <a href="https://larpmanager.com/redirect/event/manage/roles/" target="_blank" rel="noopener"><strong>Event &gt; Roles</strong></a>.</em></p>
<hr>
<h2>Participant QR code</h2>
<p>Once the feature is active, every participant receives a personal QR code, linked to their registration:</p>
<ul>
<li>It is shown on the event page, next to their registration status.</li>
<li>It is attached as an image to the registration confirmation email (and to the update emails).</li>
</ul>
<p><img src="/static/tutorials/400_checkin_02.webp" alt="Check-in QR code on the event page" width="625" height="340"></p>
<p>Ask participants to bring the code on their phone or printed. The code does not change if the registration is edited.</p>
<hr>
<h2>Check-in page</h2>
<p>Go to <a href="https://larpmanager.com/redirect/event/manage/checkin/" target="_blank" rel="noopener"><strong>Event &gt; Check-in</strong></a>.</p>
<p><img src="/static/tutorials/400_checkin_03.webp" alt="Check-in page" width="992" height="978"></p>
<p>The page lists all active registrations of the event (cancelled registrations and pending registration requests are excluded), with these columns:</p>
<ul>
<li><strong>Participant</strong>: name of the participant.</li>
<li><strong>Character</strong>: assigned characters (with their number, if character numbers are enabled).</li>
<li><strong>Payment</strong>: "Paid" if the registration fee is fully paid, otherwise "Outstanding".</li>
<li><strong>Present</strong>: whether the participant has already been checked in.</li>
</ul>
<p>Use the search box to filter the list by participant or character name.</p>
<p>Click the info icon at the start of a row to open the participant details: ticket, faction, answers to the registration form, and the fields of their character sheet.</p>
<p>At the bottom of the page, a summary shows the number of participants <strong>Present</strong>, <strong>Not scanned</strong>, and the <strong>Total</strong>.</p>
<p><em>Note: the payment status is shown for information only; it does not prevent the check-in.</em></p>
<hr>
<h2>Scanning a QR code</h2>
<p>Click on <strong>Scan QR code</strong>, and allow the browser to use the camera. Point the camera at the participant''s QR code.</p>
<p><img src="/static/tutorials/400_checkin_04.webp" alt="QR code scanner after a scan" width="452" height="466"></p>
<p>When the code is recognized, the participant is immediately marked as present, and the popup shows "Checked in:" followed by their name. You can keep scanning other codes without closing the popup.</p>
<ul>
<li>If the code does not belong to this event, the message "Unknown QR code for this event." is shown.</li>
<li>If a participant is scanned twice, the time of the first check-in is kept.</li>
</ul>
<hr>
<h2>Manual check-in</h2>
<p>If a participant cannot show their QR code (lost phone, no battery), find them with the search box in <a href="https://larpmanager.com/redirect/event/manage/checkin/" target="_blank" rel="noopener"><strong>Event &gt; Check-in</strong></a>, then click <strong>Sign in</strong> on their row, and confirm.</p>
<p><img src="/static/tutorials/400_checkin_05.webp" alt="Manual check-in confirmation" width="416" height="316"></p>
<hr>
<h2>Offline mode</h2>
<p>The whole participant list is downloaded when the page is opened, so the page keeps working if the device loses connectivity (common at outdoor or remote venues).</p>
<p>At the top of the page, an indicator shows whether you are <strong>Online</strong> or <strong>Offline</strong>. While offline, scans and manual check-ins are applied to the list immediately and saved in the browser; the counter <strong>Pending sync</strong> shows how many are waiting to be sent.</p>
<p><img src="/static/tutorials/400_checkin_06.webp" alt="Offline mode with pending check-ins" width="983" height="68"></p>
<p>As soon as the connection is restored, pending check-ins are sent automatically, keeping their original scan time.</p>
<p><em>Note: open the page while you still have a connection, and use the same device and browser until all pending check-ins are synced. Do not clear the browser data before that.</em></p>
<hr>
<h2>Experience points for attendance</h2>
<p><em>This requires the <a href="https://larpmanager.com/redirect/event/manage/features/experience/on/" target="_blank" rel="noopener"><strong>Experience points</strong></a> feature to also be active (see the <a href="https://larpmanager.com/tutorials/xp/" target="_blank" rel="noopener"><em><strong>Experience Points</strong></em></a> tutorial).</em></p>
<p>To give experience points only to the characters of participants that actually attended, go to <a href="https://larpmanager.com/redirect/event/manage/experience/awards/" target="_blank" rel="noopener"><strong>Event &gt; Awards</strong></a>, open the <strong>Load characters</strong> menu and select <strong>From checked-in participants</strong>.</p>
<p><img src="/static/tutorials/400_checkin_07.webp" alt="Load characters from checked-in participants" width="992" height="367"></p>
<p>The new award form is pre-filled with the characters of all checked-in participants; set the amount of points and save.</p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/registrations/" target="_blank" rel="noopener"><em><strong>Registrations</strong></em></a>, <a href="https://larpmanager.com/tutorials/xp/" target="_blank" rel="noopener"><em><strong>Experience Points</strong></em></a>, <a href="https://larpmanager.com/tutorials/event-tools/" target="_blank" rel="noopener"><em><strong>Event Tools</strong></em></a></em></p>', 400);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (35, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Debrief', 'debrief', '<p>This tutorial explains how to collect feedback from participants after the event with a debrief form, and how to review their answers. Use it to learn what worked, what to improve, and whether participants want to come back.</p>
<hr>
<h2>Activating debrief</h2>
<p>To use it, activate the <a href="https://larpmanager.com/redirect/event/manage/features/debrief/on/" target="_blank" rel="noopener"><strong>Debrief</strong></a> feature.</p>
<p>A new page, <a href="https://larpmanager.com/redirect/event/manage/debrief/" target="_blank" rel="noopener"><strong>Event &gt; Debrief answers</strong></a>, becomes available in the event dashboard, and a new form type, <strong>Debrief</strong>, is added to <a href="https://larpmanager.com/redirect/event/manage/form/debrief/" target="_blank" rel="noopener"><strong>Event &gt; Form</strong></a>.</p>
<hr>
<h2>Debrief questions</h2>
<p>Go to <a href="https://larpmanager.com/redirect/event/manage/form/debrief/" target="_blank" rel="noopener"><strong>Event &gt; Form</strong></a> and select <strong>Debrief</strong> next to "Configure form". Click "New" to add a question.</p>
<p><img src="/static/tutorials/410_debrief_01.webp" alt="Debrief questions in the form page" width="992" height="563"></p>
<p>Debrief questions work like the questions of the registration form: you can use single-line and multi-line text, single and multiple choice, and Likert scale questions, each with a name, a description and a status (see the <a href="https://larpmanager.com/tutorials/registration-form/" target="_blank" rel="noopener"><em><strong>Registration Form</strong></em></a> tutorial).</p>
<p><em>Tip: a Likert scale question (for example an overall rating from 1 to 5) gives you a chart of the answers; a multi-line question collects free comments.</em></p>
<hr>
<h2>Participant view</h2>
<p>Every participant with a confirmed registration finds a new entry, <strong>Debrief</strong>, in the event menu:</p>
<p><img src="/static/tutorials/410_debrief_02.webp" alt="Debrief entry in the event menu" width="258" height="43"></p>
<p>The page shows the debrief questions. Answers are kept as a draft while the participant types, and are submitted by clicking "Save". Participants can come back later to change their answers.</p>
<p><img src="/static/tutorials/410_debrief_03.webp" alt="Debrief form for participants" width="992" height="769"></p>
<p><em>Note: participants without a registration, or with a registration request still pending, are asked to register first.</em></p>
<hr>
<h2>Reviewing the answers</h2>
<p>Go to <a href="https://larpmanager.com/redirect/event/manage/debrief/" target="_blank" rel="noopener"><strong>Event &gt; Debrief answers</strong></a>. The table lists every participant who answered at least one question, with a column for each question; use the search and the column filters to find specific answers.</p>
<p><img src="/static/tutorials/410_debrief_04.webp" alt="Debrief answers" width="992" height="400"></p>
<p>Below the table, each Likert scale question has a chart with the number of participants for each value:</p>
<p><img src="/static/tutorials/410_debrief_05.webp" alt="Distribution of a rating question" width="983" height="260"></p>
<hr>
<h2>Reminding participants</h2>
<p><em>This requires the <a href="https://larpmanager.com/redirect/manage/features/deadlines/on/" target="_blank" rel="noopener"><strong>Deadlines</strong></a> feature to also be active (see the <a href="https://larpmanager.com/tutorials/deadlines/" target="_blank" rel="noopener"><em><strong>Deadlines</strong></em></a> tutorial).</em></p>
<p>Once the session is over, <a href="https://larpmanager.com/redirect/event/manage/deadlines/" target="_blank" rel="noopener"><strong>Event &gt; Deadlines</strong></a> lists the participants who have not filled the debrief yet, with their emails and a link to the debrief page to send them:</p>
<p><img src="/static/tutorials/410_debrief_06.webp" alt="Participants who did not fill the debrief" width="983" height="143"></p>
<hr>
<h2>Experience points for feedback</h2>
<p><em>This requires the <a href="https://larpmanager.com/redirect/event/manage/features/experience/on/" target="_blank" rel="noopener"><strong>Experience points</strong></a> feature to also be active (see the <a href="https://larpmanager.com/tutorials/xp/" target="_blank" rel="noopener"><em><strong>Experience Points</strong></em></a> tutorial).</em></p>
<p>To reward the participants who filled the debrief, go to <a href="https://larpmanager.com/redirect/event/manage/experience/awards/" target="_blank" rel="noopener"><strong>Event &gt; Awards</strong></a>, open the <strong>Load characters</strong> menu and select <strong>From participants who filled the debrief</strong>.</p>
<p><img src="/static/tutorials/410_debrief_07.webp" alt="Load characters of participants who filled the debrief" width="992" height="367"></p>
<p>The new award form is pre-filled with the characters of those participants; set the amount of points and save.</p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/registration-form/" target="_blank" rel="noopener"><em><strong>Registration Form</strong></em></a>, <a href="https://larpmanager.com/tutorials/xp/" target="_blank" rel="noopener"><em><strong>Experience Points</strong></em></a>, <a href="https://larpmanager.com/tutorials/deadlines/" target="_blank" rel="noopener"><em><strong>Deadlines</strong></em></a></em></p>', 410);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (36, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Event Tools', 'event-tools', '<p>This tutorial covers smaller tools that help the staff before and during the event: tracking problems and milestones, hosting files, sharing protected media, and copying elements from another event.</p>
<hr>
<h2>Problems</h2>
<p><em>A ticket system to log and follow issues during the event.</em> To use it, activate the <a href="https://larpmanager.com/redirect/event/manage/features/problems/on/" target="_blank" rel="noopener"><strong>Problems</strong></a> feature.</p>
<p>Go to <a href="https://larpmanager.com/redirect/event/manage/problems/" target="_blank" rel="noopener"><strong>Event &gt; Problems</strong></a> and click "New":</p>
<p><img src="/static/tutorials/415_event-tools_01.webp" alt="New problem" width="1260" height="716"></p>
<ul>
<li><strong>Severity</strong>: from 1 - RED (most serious) to 4 - GREEN.</li>
<li><strong>Status</strong>: OPEN, WORKING or CLOSED.</li>
<li><strong>Where</strong>: where the problem happened.</li>
<li><strong>When</strong>: when it happened.</li>
<li><strong>What</strong>: what happened.</li>
<li><strong>Who</strong>: who is involved.</li>
</ul>
<p>Staff members can add comments and take charge of a problem until it is closed.</p>
<hr>
<h2>Milestones</h2>
<p><em>Track the preparation of the event with deadlines and owners.</em> To use it, activate the <a href="https://larpmanager.com/redirect/event/manage/features/milestones/on/" target="_blank" rel="noopener"><strong>Milestones</strong></a> feature.</p>
<p>Go to <a href="https://larpmanager.com/redirect/event/manage/milestones/" target="_blank" rel="noopener"><strong>Event &gt; Milestones</strong></a> and click "New":</p>
<p><img src="/static/tutorials/415_event-tools_02.webp" alt="New milestone" width="1260" height="507"></p>
<ul>
<li><strong>Name</strong>: what must be done.</li>
<li><strong>Status</strong>: To Do, In Progress or Completed.</li>
<li><strong>Description</strong>: details.</li>
<li><strong>Deadline</strong>: when it must be done.</li>
<li><strong>Assigned to</strong>: the staff member responsible.</li>
</ul>
<hr>
<h2>Hosting files</h2>
<p><em>Upload files to LarpManager and share them with a link.</em> To use it, activate the <a href="https://larpmanager.com/redirect/event/manage/features/utils/on/" target="_blank" rel="noopener"><strong>Utility</strong></a> feature.</p>
<p>Go to <a href="https://larpmanager.com/redirect/event/manage/utils/" target="_blank" rel="noopener"><strong>Event &gt; Utility</strong></a> and click "New":</p>
<p><img src="/static/tutorials/415_event-tools_03.webp" alt="New hosted file" width="1260" height="256"></p>
<p>Each file gets a link, based on its <strong>Cod</strong>, that you can share with the staff or with participants. It is also useful to host the background images of PDF sheets and handouts.</p>
<hr>
<h2>One-time content</h2>
<p><em>Stream a video or audio file through links that work only once.</em> To use it, activate the <a href="https://larpmanager.com/redirect/event/manage/features/onetime_content/on/" target="_blank" rel="noopener"><strong>One-Time Content</strong></a> feature.</p>
<p>Upload the file in <a href="https://larpmanager.com/redirect/event/manage/onetimes/content/" target="_blank" rel="noopener"><strong>Event &gt; Content</strong></a>:</p>
<p><img src="/static/tutorials/415_event-tools_04.webp" alt="New one-time content" width="1260" height="563"></p>
<ul>
<li><strong>Content name</strong>: descriptive name of the content.</li>
<li><strong>Description</strong>: optional description.</li>
<li><strong>Media file</strong>: the video or audio file (MP4, WebM or MP3 recommended).</li>
<li><strong>Active</strong>: uncheck to make the content unavailable.</li>
</ul>
<p>Then generate the access links in <a href="https://larpmanager.com/redirect/event/manage/onetimes/tokens/" target="_blank" rel="noopener"><strong>Event &gt; Tokens</strong></a>, with an optional note (for example the recipient). Each link can be opened only once; LarpManager records when it was used, by whom and from where.</p>
<hr>
<h2>Copying from another event</h2>
<p><em>Reuse the setup of a previous event.</em> To use it, activate the <a href="https://larpmanager.com/redirect/event/manage/features/copy/on/" target="_blank" rel="noopener"><strong>Copy</strong></a> feature.</p>
<p>Go to <a href="https://larpmanager.com/redirect/event/manage/copy/" target="_blank" rel="noopener"><strong>Event &gt; Copy</strong></a>, choose the event to copy from in <strong>Parent</strong>, and select the elements to copy in <strong>Target</strong> (configuration, tickets, registration form, characters, factions, and more):</p>
<p><img src="/static/tutorials/415_event-tools_05.webp" alt="Copy elements from another event" width="992" height="656"></p>
<p><em>Note: elements of this event with the same name are overwritten.</em></p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/writing-extras/" target="_blank" rel="noopener"><em><strong>Writing Extras</strong></em></a>, <a href="https://larpmanager.com/tutorials/organization-tools/" target="_blank" rel="noopener"><em><strong>Organization Tools</strong></em></a>, <a href="https://larpmanager.com/tutorials/checkin/" target="_blank" rel="noopener"><em><strong>Check-in</strong></em></a></em></p>', 415);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (37, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Organization Tools', 'organization-tools', '<p>This tutorial covers organization-wide tools: shuttle requests, the warehouse, short links, the integration with an external app, and the activity log.</p>
<hr>
<h2>Shuttle</h2>
<p><em>Let participants ask to be picked up, and organize the rides.</em> To use it, activate the <a href="https://larpmanager.com/redirect/manage/features/shuttle/on/" target="_blank" rel="noopener"><strong>Shuttle</strong></a> feature.</p>
<p>Users find a new "Shuttle" page in their menu, where they submit a request:</p>
<p><img src="/static/tutorials/420_organization-tools_05.webp" alt="Shuttle request form" width="992" height="716"></p>
<ul>
<li><strong>Number of passengers</strong>: how many people need a ride.</li>
<li><strong>Pickup location</strong>: the address or place of pickup.</li>
<li><strong>Additional details</strong>: details to recognize them (clothes, luggage, meeting point).</li>
<li><strong>Pickup date</strong>: the day of the ride.</li>
<li><strong>Pickup time</strong>: the time of the ride.</li>
</ul>
<p>The shuttle staff sees all requests in the same page and updates their status: "Waiting list", "We''re coming", "Arrived safe and sound", adding instructions for the passengers (such as the car model).</p>
<hr>
<h2>Warehouse</h2>
<p><em>Keep track of your props, costumes and equipment.</em> To use it, activate the <a href="https://larpmanager.com/redirect/manage/features/warehouse/on/" target="_blank" rel="noopener"><strong>Warehouse</strong></a> feature.</p>
<p>Create the places where items are stored in <a href="https://larpmanager.com/redirect/manage/warehouse/containers/" target="_blank" rel="noopener"><strong>Organization &gt; Containers</strong></a>:</p>
<p><img src="/static/tutorials/420_organization-tools_02.webp" alt="New warehouse container" width="1260" height="421"></p>
<p>Then add the items in <a href="https://larpmanager.com/redirect/manage/warehouse/items/" target="_blank" rel="noopener"><strong>Organization &gt; Items</strong></a>, each with its container, tags and photo:</p>
<p><img src="/static/tutorials/420_organization-tools_03.webp" alt="New warehouse item" width="1260" height="557"></p>
<p>Use <a href="https://larpmanager.com/redirect/manage/warehouse/tags/" target="_blank" rel="noopener"><strong>Organization &gt; Tags</strong></a> to group items, and <a href="https://larpmanager.com/redirect/manage/warehouse/movements/" target="_blank" rel="noopener"><strong>Organization &gt; Movements</strong></a> to record when items leave or return. For each event, <a href="https://larpmanager.com/redirect/event/manage/warehouse/area/" target="_blank" rel="noopener"><strong>Event &gt; Area</strong></a>, <a href="https://larpmanager.com/redirect/event/manage/warehouse/items/" target="_blank" rel="noopener"><strong>Event &gt; Items</strong></a>, <a href="https://larpmanager.com/redirect/event/manage/warehouse/checks/" target="_blank" rel="noopener"><strong>Event &gt; Checks</strong></a> and <a href="https://larpmanager.com/redirect/event/manage/warehouse/manifest/" target="_blank" rel="noopener"><strong>Event &gt; Manifest</strong></a> let you plan which items go where, and check them before and after the event.</p>
<hr>
<h2>URL shortener</h2>
<p><em>Create short links to long addresses.</em> To use it, activate the <a href="https://larpmanager.com/redirect/manage/features/urlshortner/on/" target="_blank" rel="noopener"><strong>URL shortener</strong></a> feature.</p>
<p>Go to <a href="https://larpmanager.com/redirect/manage/urlshortner/" target="_blank" rel="noopener"><strong>Organization &gt; URL shortener</strong></a> and click "New":</p>
<p><img src="/static/tutorials/420_organization-tools_01.webp" alt="New short URL" width="1260" height="260"></p>
<ul>
<li><strong>Name</strong>: a label for the link.</li>
<li><strong>Cod</strong>: the short code of the link.</li>
<li><strong>URL</strong>: the long address it redirects to.</li>
</ul>
<hr>
<h2>App integration</h2>
<p><em>Add a topbar button that sends logged-in users to your own application.</em> To use it, activate the <a href="https://larpmanager.com/redirect/manage/features/app_integration/on/" target="_blank" rel="noopener"><strong>App Integration</strong></a> feature.</p>
<p>In <a href="https://larpmanager.com/redirect/manage/config/app_integration/" target="_blank" rel="noopener"><strong>Organization &gt; Configuration &gt; App Integration</strong></a>, set:</p>
<p><img src="/static/tutorials/420_organization-tools_04.webp" alt="App integration configuration" width="983" height="559"></p>
<ul>
<li><strong>Button text</strong>: the label of the topbar button.</li>
<li><strong>Redirect URL</strong>: the address of your application.</li>
<li><strong>Shared secret</strong>: the key used to sign the login token, if your application supports single sign-on.</li>
<li><strong>Algorithm</strong>: the signing algorithm of the token (default: HS256).</li>
</ul>
<hr>
<h2>Activity log</h2>
<p><em>See who created, changed or deleted what.</em> To use it, activate the <a href="https://larpmanager.com/redirect/manage/features/logs/on/" target="_blank" rel="noopener"><strong>Activity Log</strong></a> feature.</p>
<p>The log of the whole organization is in <a href="https://larpmanager.com/redirect/manage/logs/" target="_blank" rel="noopener"><strong>Organization &gt; Activity Log</strong></a>, and the log of each event in <a href="https://larpmanager.com/redirect/event/manage/logs/" target="_blank" rel="noopener"><strong>Event &gt; Activity Log</strong></a>:</p>
<p><img src="/static/tutorials/420_organization-tools_06.webp" alt="Activity log" width="992" height="452"></p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/event-tools/" target="_blank" rel="noopener"><em><strong>Event Tools</strong></em></a>, <a href="https://larpmanager.com/tutorials/users/" target="_blank" rel="noopener"><em><strong>Users</strong></em></a></em></p>', 420);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (38, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Italian Associations', 'italian-associations', '<p>This tutorial covers the features for associations based in Italy: fiscal receipts, the register of volunteers, the fiscal code check and the annual fiscal report.</p>
<hr>
<h2>Annual fiscal report</h2>
<p><em>An annual summary of your fiscal activity, for the RUNTS.</em> To use it, activate the <a href="https://larpmanager.com/redirect/manage/features/ita_balance/on/" target="_blank" rel="noopener"><strong>Annual fiscal report</strong></a> feature, then open <a href="https://larpmanager.com/redirect/manage/balance/" target="_blank" rel="noopener"><strong>Organization &gt; Balance</strong></a>.</p>
<p>All the organization''s fiscal movements are prepared in the format ("rendiconto per cassa") ready to be uploaded in the RUNTS portal.</p>
<hr>
<h2>Fiscal code check</h2>
<p><em>Check the fiscal codes entered by your members.</em> To use it, activate the <a href="https://larpmanager.com/redirect/manage/features/fiscal_code_check/on/" target="_blank" rel="noopener"><strong>Fiscal code check</strong></a> feature. <a href="https://larpmanager.com/redirect/manage/check_membership/" target="_blank" rel="noopener"><strong>Organization &gt; Check data</strong></a> lists the members whose fiscal code does not match their personal data.</p>
<hr>
<h2>Receipts</h2>
<p><em>Generate a PDF fiscal receipt for each payment, as required by Italian law.</em> To use it, activate the <a href="https://larpmanager.com/redirect/manage/features/receipts/on/" target="_blank" rel="noopener"><strong>Receipt</strong></a> feature.</p>
<p>In <a href="https://larpmanager.com/redirect/manage/config/receipts/" target="_blank" rel="noopener"><strong>Organization &gt; Configuration &gt; Receipts</strong></a>, set the data shown on the receipts:</p>
<p><img src="/static/tutorials/995_italian-associations_01.webp" alt="Receipts configuration" width="983" height="559"></p>
<ul>
<li><strong>Full name</strong>: the name of the association, as shown in the receipt header.</li>
<li><strong>Legal address</strong>: the full address of the association.</li>
<li><strong>Fiscal code</strong>: the tax code of the association.</li>
<li><strong>RUNTS registration</strong>: the registration details, for example ''Iscritta al RUNTS sez. APS''.</li>
</ul>
<hr>
<h2>Register of volunteers</h2>
<p><em>Keep the register of volunteers required by the RUNTS regulations.</em> To use it, activate the <a href="https://larpmanager.com/redirect/manage/features/volunteer_registry/on/" target="_blank" rel="noopener"><strong>Register of volunteers</strong></a> feature.</p>
<p>Go to <a href="https://larpmanager.com/redirect/manage/volunteer_registry/" target="_blank" rel="noopener"><strong>Organization &gt; Volunteers</strong></a> to add volunteers and print the register:</p>
<p><img src="/static/tutorials/995_italian-associations_02.webp" alt="Register of volunteers" width="992" height="337"></p>
<hr>
<h2>Easter egg</h2>
<p><em>Occasionally show users a special page, and optionally award them a badge.</em> To use it, activate the <a href="https://larpmanager.com/redirect/manage/features/centauri/on/" target="_blank" rel="noopener"><strong>Easter egg</strong></a> feature.</p>
<p>In <a href="https://larpmanager.com/redirect/manage/config/centauri/" target="_blank" rel="noopener"><strong>Organization &gt; Configuration &gt; Easter egg</strong></a>, set:</p>
<p><img src="/static/tutorials/995_italian-associations_03.webp" alt="Easter egg configuration" width="983" height="737"></p>
<ul>
<li><strong>Probability</strong>: how often the page is shown, out of a thousand page views.</li>
<li><strong>Badge</strong>: the badge awarded to users who see it (see Badges in the Users tutorial).</li>
<li><strong>Description</strong>: text shown on the special page.</li>
<li><strong>Page</strong>: content of the special page.</li>
</ul>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/accounting/" target="_blank" rel="noopener"><em><strong>Accounting</strong></em></a>, <a href="https://larpmanager.com/tutorials/membership/" target="_blank" rel="noopener"><em><strong>Membership</strong></em></a>, <a href="https://larpmanager.com/tutorials/payments/" target="_blank" rel="noopener"><em><strong>Payments</strong></em></a></em></p>', 995);
INSERT INTO public.larpmanager_larpmanagertutorial VALUES (39, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Mail Settings', 'manage-mails', '<p>The platform sends automated emails to participants at key moments: registration confirmation, payment received, character assigned, and more. This tutorial explains how to customize those templates, configure a custom mail server, and manage mail-related settings.</p>
<h2>Mail notifications</h2>
<p>You can configure the emails that LarpManager sends when participants act. Go to <a href="https://larpmanager.com/redirect/manage/config/email/" target="_blank" rel="noopener"><strong>Organization &gt; Configuration &gt; Email notifications</strong></a>:</p>
<p><img src="/static/tutorials/999_manage-mails_01.webp" alt="Email notifications" width="983" height="890"></p>
<h2>Notifications digest</h2>
<p><em>Receive a single daily summary instead of one email for each new registration, update, payment or invoice to approve.</em></p>
<p>For the main email address of the organization, enable <strong>Notifications digest</strong> in <a href="https://larpmanager.com/redirect/manage/config/email/" target="_blank" rel="noopener"><strong>Organization &gt; Configuration &gt; Email notifications</strong></a> (the option is shown only if the organization has a main email address).</p>
<p>Each organizer can also choose it for their own notifications, in <a href="https://larpmanager.com/redirect/manage/preferences/" target="_blank" rel="noopener"><strong>Organization &gt; Preferences</strong></a>:</p>
<p><img src="/static/tutorials/999_manage-mails_04.webp" alt="Personal notifications digest" width="983" height="318"></p>
<p>Notifications are then collected during the day and sent together in one summary email.</p>
<h2>Custom mail server</h2>
<p>By default, LarpManager sends emails from &lt;slug&gt;@larpmanager.com using its own mail servers. This feature allows configuring an external mail server by providing its connection details. First, activate the <a href="https://larpmanager.com/redirect/manage/features/custom_mail/on/" target="_blank" rel="noopener"><strong>External mail server</strong></a> feature.</p>
<hr>
<p>Set the mail server details in <a href="https://larpmanager.com/redirect/manage/config/custom_mail_server/" target="_blank" rel="noopener"><strong>Organization &gt; Configuration &gt; Customised mail server</strong></a>:</p>
<p><img src="/static/tutorials/999_manage-mails_02.webp" alt="Organization mail server" width="983" height="467"></p>
<p>Insert the required information; all the emails regarding your events are sent using those connection details.</p>
<p><em>If you''re not sure, ask your email provider for these details.</em> </p>
<p><em>If you encounter any issue, please contact us, or your email provider, to check them.</em></p>
<hr>
<p>You can configure a mail server individually for each event. If an event has a custom mail server setting, those are used instead of the ones of the whole organization.</p>
<p>To override it for a single event, use <a href="https://larpmanager.com/redirect/event/manage/config/custom_mail_server/" target="_blank" rel="noopener"><strong>Event &gt; Configuration &gt; Customised mail server</strong></a>, with the same required information.</p>
<p><img src="/static/tutorials/999_manage-mails_03.webp" alt="Event mail server" width="983" height="467"></p>
<hr>
<p><em>Related tutorials: <a href="https://larpmanager.com/tutorials/deadlines/" target="_blank" rel="noopener"><em><strong>Deadlines</strong></em></a>, <a href="https://larpmanager.com/tutorials/organization-appearance/" target="_blank" rel="noopener"><em><strong>Organization Appearance</strong></em></a></em></p>', 999);

