INSERT INTO public.larpmanager_paymentmethod VALUES (1, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Wire', 'wire', '<p><strong>Beneficiary: </strong>Name of the recipient account holder.&nbsp;</p>
<p><strong>IBAN</strong>: International Bank Account Number of the recipient account (27-character long)</p><p><strong>BIC</strong>: Optional</p>', 'payee, iban, bic', 'payment_methods/ac81a0b8942e41a8bbcefa197ccfb3d8.png', 'u1', NULL);
INSERT INTO public.larpmanager_paymentmethod VALUES (2, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Freeform', 'any', '<p>No need for data; the participant will upload a text of any kind.&nbsp;</p>', '', 'payment_methods/873326d033b74568bb9e79d1e96762cf.png', 'u2', NULL);
INSERT INTO public.larpmanager_paymentmethod VALUES (3, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Paypal (legacy)', 'paypal', '<ol>
<li>You need to have a <strong>Business account&nbsp;</strong>(request it if you don''t already have it)</li>
<li>In <strong>PAYPAL_ID,&nbsp;</strong>put the email of your account (that you use to login).&nbsp;</li>
<li>Open the following page: https://developer.paypal.com</li>
<li>Log in with your PayPal credentials</li>
<li>Click on My Apps &amp; Credentials, and then on the Create App button</li>
<li>Enter the name of the App in App Name and confirm with Create App (any name will do)</li>
<li>Click on the "LIVE" selector, at this point you need to copy the Client ID and then by clicking on Show copy the secret key.</li>
<li>Input this secret key in the field <strong>PAYPAL_BUSINESS</strong></li>
</ol>', 'id, business', 'payment_methods/aba0f22f1f3b4cc8bfb7ca092ad0ba6e.png', 'u3', NULL);
INSERT INTO public.larpmanager_paymentmethod VALUES (4, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Stripe', 'stripe', '<ol>
<li>Login to your Stripe account: https://dashboard.stripe.com/</li>
<li>Go to the API keys section: https://dashboard.stripe.com/test/apikeys</li>
<li>Copy the "Publishable key" in <strong>STRIPE PK API</strong></li>
<li>Click on "Secret key", reveal it, and copy it on <strong>STRIPE SK API</strong></li>
<li>Go to the Webhooks section: https://dashboard.stripe.com/webhooks</li>
<li>Make sure you are in the live environment (look at top right, deselect "test mode")</li>
<li>Click on "Add endpoint"</li>
<li>&nbsp;As link put "https://&lt;slug&gt;.larpmanager.com/accounting/webhook/stripe" (&lt;slug&gt; is the subdomain of your organization)</li>
<li>Click on "Select events", then on "Checkout", then on "Select all checkout events", then "Add events"</li>
<li>Click on "Add endpoint"</li>
<li>Open the endpoint</li>
<li>Click on "Signing secret"</li>
<li>Copy that value on <strong>STRIPE WEBHOOK SECRET</strong></li>
</ol>', 'pk_api, sk_api, webhook_secret', 'payment_methods/86a08e7ab3bd41f9be8dff0bd5302d78.png', 'u4', NULL);
INSERT INTO public.larpmanager_paymentmethod VALUES (5, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'SumUp', 'sumup', '<ol>
<li>Login to your Sumup account: https://me.sumup.com/</li>
<li>Copy the merchant code (top right, under the account name) in <strong>SUMUP MERCHANT ID</strong></li>
<li>Go to the developer page: https://developer.sumup.com/protected/oauth-apps/</li>
<li>Click "Create application"</li>
<li>Insert as name "LarpManager", as url https://&lt;slug&gt;.larpmanager.com (&lt;slug&gt; is your organization subdomain)</li>
<li>Click on it&nbsp;</li>
<li>Select scope "products"</li>
<li>Make sure that the scopes "payments" is enabled. If not, contact sumup: https://developer.sumup.com/contact</li>
<li>Click "create client secret"</li>
<li>Copy "Client ID" in <strong>SUMUP CLIENT ID</strong></li>
<li>Copy "Client secret" (download it) in <strong>SUMUP CLIENT SECRET</strong></li>
</ol>', 'merchant_id, client_id, client_secret', 'payment_methods/6e4c4daef26f43c0a8bac55274cca6f0.png', 'u5', NULL);
INSERT INTO public.larpmanager_paymentmethod VALUES (6, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Redsys', 'redsys', '', 'merchant_code, merchant_terminal, merchant_currency, secret_key, sandbox, merchant_paymethods', 'payment_methods/d313edf6dff84bd0834b3ed32dbc1475.png', 'u6', 'es');
INSERT INTO public.larpmanager_paymentmethod VALUES (7, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Paypal (manual)', 'paypal_nf', '<p>Input the handle of your paypal account (that will be used to compose the PayPal.Me link):</p>
<ol class="X5LH0c">
<li class="TrT0Xe">Log into your Paypal account.</li>
<li class="TrT0Xe">Click on the gear icon on the top right hand of the page or click here.</li>
<li class="TrT0Xe">Your PayPal name will show up under the Profile section (as shown in the image below)</li>
</ol>', 'handle', 'payment_methods/7_3b97971f5d8747b1bd225266243b5179.png', 'u7', NULL);
INSERT INTO public.larpmanager_paymentmethod VALUES (8, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Satispay', 'satispay', '<p>Follow the instructions at: https://developers.satispay.com/reference/keyid, using the authentication token provided by your Dashboard</p>', 'key_id', 'payment_methods/24037547097e4bd3b530de38eaaf4ce3.png', 'u8', 'it');
INSERT INTO public.larpmanager_paymentmethod VALUES (9, NULL, false, '2025-01-01 00:00:00.000000+01', '2025-01-01 00:00:00.000000+01', 'Paypal', 'paypal_v2', '<ol>
<li>You need to have a <strong>Business account&nbsp;</strong>(request it if you don''t already have it)</li>
<li>Open the following page: https://developer.paypal.com/dashboard/applications/live</li>
<li>Log in with your PayPal credentials</li>
<li>Click on Create App, enter any name and confirm</li>
<li>Copy the Client ID in <strong>PAYPAL V2 CLIENT ID</strong></li>
<li>Copy the Secret key in <strong>PAYPAL V2 SECRET</strong></li>
<li>In the app page, under Webhooks, click on Add Webhook</li>
<li>As link put "https://&lt;slug&gt;.larpmanager.com/accounting/webhook/paypal" (&lt;slug&gt; is the subdomain of your organization)</li>
<li>Select the events "Payment capture completed" and "Payment capture denied" and save</li>
<li>Copy the Webhook ID in <strong>PAYPAL V2 WEBHOOK ID</strong></li>
</ol>', 'client_id, secret, webhook_id', 'payment_methods/aba0f22f1f3b4cc8bfb7ca092ad0ba6e.png', 'u9', NULL);

